// Кармалық нумерология — түсіндірме мәтіндері (қазақша)
window.KARMIC_TEXTS = {
 "month": {
  "1": "Қаңтар. Әулетте (Роду) бауырлар — аға-іні, апа-сіңлілер — арасындағы қарым-қатынас бұзылған. Енді қаңтар баласының өз еркімен алған міндеті — бауырларына көмектесу. Ол бауырының осы өмірде жинаған кармасының 50%-ын өтейді. Адам осы өмірде қателесуге бейім «қаңтарда тумаған» бауырына көмекке туған. Егер екі бала да қаңтарда туса, онда «қаңтарда тумаған» бала жетіспейді.",
  "2": "Ақпан. Әулетте жақындарға қамқорлық пен мейірімнің болмауына байланысты мәселелер бар. Адамдар бір-біріне көмектеспейді. Міндет — мейірімділікті, кешірімшілдікті, қамқорлықты, ілтипатты үйрену. Басқа адамдарды сезіну (емшілер, тәуіптер). Ақпан балаларын әжелері мен аталары тәрбиелеуі керек. Олар үшін бедел — аға буын. Мұндай адам өткен өмірінде онша мейірімді әрі рақымды болмаған. Сондықтан бұл өмірде бойында осы қасиеттерді дамытуы керек. Ол әулетке өз әжесіне немесе атасына (кез келген желі бойынша) келген. Сірә, ол үшін ата-анасы — жарлық емес, ол тек аға буынның өкілдерін тыңдайды. Ата-анасы ақпан баласын бала кезінен біреуге күтім жасауға үйретуі керек. Егер ол мұны үйренбесе, сезімтал әрі қамқор болмаса — оны жағымсыздықтар арқылы үйретеді. Жақын әйелдер ауыра бастайды, ол бәрібір қажетті дағдыларды алады, бірақ мұндай қайғылы жағдайларда.",
  "3": "Наурыз. Әулетте балаларды тәрбиелеудің дұрыс үлгісі бұзылған. Балаларға қысым көрсетілген. Ата-аналар балаларды құрметтеуді тоқтатқан. Бұған шамадан тыс қамқорлық та жатады. Мұндай отбасыларда балаларды «шайқай-тауық ана» немесе «көкек ана» қағидасымен тәрбиелейді.\nНаурызда туған адам өз анасына келген. Өткен өмірінде ол дербес болмаған, тағдыры көп жағынан анасына байланысты болған. Сондықтан осы өмірде дербестікке үйренуі керек. Неғұрлым ертерек дербес өмір бастап, ата-анасына сүйенбей, шешімді өзі қабылдауды үйренсе, ол үшін соғұрлым жақсы.\nКейін өз отбасында балаларды тәрбиелеудің қарама-қарсы үлгісін таңдаған дұрыс. Егер отбасындағы серіктестердің бірі «наурыздық» болса, балаларды тәрбиелеуде екінші — «наурыздық емес» серіктестің үлгісі алынады.",
  "4": "Сәуір. Сәуірде туған адам әкесіне көмектесуге келген. Әулетте ер желісі бойынша қателер жіберілген. Әкесіне сынақтардан өту керек, бірақ ол дайын емес.\nСәуір балалары өз еркімен әкелерінің кармалық кепілі болуды таңдаған, олардың тірі кезінде жасаған кармасының 50%-ын тазартады. Әкесінің қателерін ол тірі болғанша өтейді.",
  "5": "Мамыр. Әулетте әйел желісі бойынша күнәлар болған, көбіне түсік жасату немесе балалардан бас тарту. Анаға сынақ дайындалған, ал ол одан өтуге дайын емес.\nМамырда туған адам анасына келген. Ол өз еркімен анасының кармалық кепілі болуды таңдаған және оның тірі кезінде жасаған кармасының 50%-ын тазартады. Анасының қателерін ол тірі болғанша өтейді.\nМұндай адам анасымен жылы, сенімді қарым-қатынас құруды үйрену міндетімен келген, өйткені әдетте олар жанжалды болады. Анасын кешіріп, оған ренжуді тоқтату керек.",
  "6": "Маусым. Әулетте опасыздық пен сатқындық күнәсі жасалған. Сондықтан қазір маусым баласы өз қарым-қатынасын дұрыс бастауды және құруды үйренуі керек. Көбіне маусым балалары қарым-қатынастың көрнекі теріс үлгісі болуы үшін ата-анасы жағымсыз өмір сүретін отбасыларға келеді.\n«Маусымдықтар» үйленген/тұрмыстағы адамдармен кездесуге бейім. Олардың жеке өмірінде мәселелер, кармалық некелер болуы мүмкін. Олардың негізгі міндеті — кешіруді үйрену, азғыруларға берілмеу (опасыздық жасамау). Ажырасуға жол бермеу.",
  "7": "Шілде. Әулетте тілі, мәдениеті, дәстүрі өзгеріп, көшу болған. Сондай-ақ әулеттік дәстүрлерден бас тарту болған. Қазір шілде баласының міндеттері — өз әулетінің тамырын табу. Оларға шежіре ағашын құру ұсынылады. Егер шілде баласы туса, бұл әулеттің тоқырап қалғанының көрсеткіші. Сондықтан басқа қалаға көшу, тұрғылықты жерді ауыстыру немесе басқа қалада не елде білім алу маңызды. Егер адам өмірде қозғалмаса, өмір батпақтанып қалады. Нумерологияда жеті — арба (колесница) белгісі. Әулетті орнынан қозғау керек.",
  "8": "Тамыз. Шекспир тарихы. Әулетте мүдделердің бітіспес қақтығысы бар. Тамыз балалары — ата-ана арасындағы қарым-қатынастың рәсімдері мен дәстүрлері бұзылғанының көрсеткіші. Сондықтан тамыз баласының міндеті — жанжалдағы ата-анасын татуластыру, отбасының ыдырауына жол бермеу. Ата-аналар бәрібір жиі ажырасады. Сонда міндет — ең болмаса оларды татуластыру. Болашақта баланың өзі де жеке өмірінде ажырасуға бейім.",
  "9": "Қыркүйек. Қыркүйекте астралды денесі өте күшті, ең талантты адамдар туады. Әулетте талант жоғалған, сондықтан қазір баланың міндеті — әулеттің кәсібін (ремеслосын) қалпына келтіріп, оны көбейту. Ол не өз таланттарын ашуы, не ата-бабасы жасаған бір нәрсені тауып, көрсетуі керек.",
  "10": "Қазан. Әулетте қаржылық заңдар бұзылған, отбасы ақшасы ұрланған. Қазан баласының міндеті — мұра алу құқығына лайық болып, оны көбейту. Ал мұра алса — оны ешбір жағдайда сатуға болмайды. Үлкенірек бір нәрсе сатып алу үшін сататын жағдай ғана бұған жатпайды.\nАта-аналар қазан балаларына неғұрлым көп ақша берсе, олар кейін өздері соғұрлым аз таба алады.\nҚазанда туғандар әулеттің капиталын көбейтуі керек.",
  "11": "Қараша. Әулетте аға буын кіші буынға көмектесетін ұрпақтар сабақтастығы бұзылған. Мұндай отбасыларда балалар мен ата-аналар арасында бәсекелестік жиі туындайды. Балалардың тираниясы болады. Бала әулеттің мәртебесі мен шеберлігін көтеруі керек. Ол туралы ата-анасынан да қаттырақ айтуы керек. Үнемі дәлелдеп, назарға лайық болу керек.",
  "12": "Желтоқсан. Желтоқсанда туған бала — әулеттің бытыраңқы екенінің көрсеткіші. Бір-біріңді естуді, психологиялық көмек көрсетуді үйрену керек. Әулетте жанашырлық, түсіністік, жол беруге деген ықылас жоқ. Желтоқсан балаларын жиі үйірмелерге, бес күндік балабақшаға, кадеттерге, әжелері мен аталарына береді. Олар өздеріне назар аудару үшін жиі «құрбан синдромын» қосады. Өз-өзіне қол жұмсау желтоқсан балаларының арасында ең көп. 15 желтоқсанда туғандарға артистизм тән, олар басқа адамдарды шебер басқарады (манипуляция жасайды). «Алаңда асылған адам». Бәрі әрқашан олар айтқандай жаман бола бермейді. Олар мұны өздері байқамайды. 12 желтоқсанда туғандарда позитив аз, оларға психологияны үйрену керек."
 },
 "sz": {
  "1": "Бойыңыздағы білім мен әлеуетті тек ауызша түрде бөлісуіңіз керек: шешен, дәріскер болу, семинарлар, келіссөздер жүргізу, мұғалім, журналист, жазушы, менеджер және т.б. болу. Қоғамда сөзіңіз арқылы дамуыңыз керек. Сондай-ақ сіз бауырларыңызға (бар болса) көмектесу жүгін арқалайсыз. Сіз олар үшін тек тірек қана емес, ұстаз да болуыңыз керек.\nОқуыңыз және оқытуыңыз, зияткерлік біліміңіз бен дағдыларыңызды арттыруыңыз керек (жеткен жеріңізде тоқтамаңыз). Оқуды жарты жолда тастауға немесе одан мүлдем бас тартуға болмайды.\nМұндай міндеті бар адамдар көпшілік алдына шығудан жиі қорқады. Бұл қорқынышпен күресу керек.",
  "2": "Сізге қоршаған орта, жануарлар, балалар мен мүмкіндігі шектеулі адамдар үшін жауапкершілік арқалау керек. Әсіресе мұқтаж адамдарға қамқорлық жасап, оларды қорғау. Барлық әйелдерді, әсіресе жақындарыңызды (ана, апа-сіңлі, әйел, қыз және т.б.) қорғауға тұру; олардың денсаулығына қамқорлық жасау керек. Сондай-ақ түйсікті, жанашырлықты, төзімділікті, мейірім мен қамқорлықты дамытуды ұмытпаған жөн. Медицинаға жақын саланы таңдаған дұрыс.",
  "3": "Бұл міндет жай ғана ата-ана болуды емес, балаларыңызға білімді, тәжірибені, дағдыларды, таланттар мен қабілеттерді беруді білдіреді. Балаларыңызды тәрбиелеумен және оқытумен жеке өзіңіз айналысуыңыз керек. Сондай-ақ мұғалім болуыңызға немесе идеяларыңыз бен таланттарыңыздың ізбасарлары болуына болады. Сіздің міндетіңіз — біліміңізді жай беру ғана емес, балаға аяғынан тұруға көмектесу, оған өмірдегі барлық жолды ашу.",
  "4": "Сіз жай ғана кәсіпқой болып қоймай, басқа адамдарға да сіздің табыстарыңыздан табыс табуға мүмкіндік беруіңіз керек. Үлгі тұтарлық, ерік-жігері мықты, әділ басшы болу керек. Егер отбасын таңдап, кәсіби тұрғыда дамығыңыз келмесе, тұрмыстық мәселелерге жұмыста жүргендей қарауыңыз керек. Қаржылық әл-ауқат үшін некеге тұрудан аулақ болуға тырысыңыз. Бірінші орында таңдаған салада кәсіби тұрғыда даму міндеті тұруы керек. Жауапкершілікті өз мойныңызға алуды және қойылған міндетті өз бетіңізше орындай білуді үйренуіңіз керек. Егер өз бизнесіңіз болса, қандай да бір процеске тікелей өзіңіз қатысуыңыз керек («торттың үстіндегі шие»).",
  "5": "Сізге ғылыми немесе рухани зерттеулермен айналысу, білімді кеңейтіп, тереңдету, жақсы білім алу керек. Тексерілген ақпаратты көпшілікке жеткізу. Рухани даму, түрлі елдерге саяхаттау, басқа халықтардың түрлі мәдениеттері мен дәстүрлерін зерттеу керек. Зиянды тағамдарды, алкогольді және т.б. теріс пайдаланбай, дұрыс өмір салтын ұстануға міндеттісіз. Сіз әулет (Род) дәстүрлерінің рухани жалғастырушысы болып, адамгершілікті, моральды және заңдылықты алып жүруіңіз керек. Ер адамдарға ренжуге жол бермеңіз, бәріне лайықты қарауды үйреніңіз.",
  "6": "Сіз шынайы махаббат сезімінің, тазалықтың, қарым-қатынастағы үйлесімнің иесі болуыңыз керек. Жеке қарым-қатынаста эталон болуыңыз керек. Отбасыңызға назар аударып, отбасы мүшелеріңіз үшін тірек, қолдау, жан жұбанышы болуыңыз керек. Тура мағынасында отбасы мүддесіне қызмет ету керек. Ажырасу мен опасыздыққа жол берілмейді!",
  "7": "Өмір ұсынатын барлық қызмет түрлеріне белсенді қосылуыңыз керек. Өз үлгіңізбен адамдарды белсенді әрі прогрессивті өмір салтына үйрету. Сізге көп саяхаттау, басқа мәдениеттерді зерттеу, өмір салтыңызға жаңа бір нәрсе енгізу маңызды. Басқа халықтардың жағымды тәжірибесін үйреніп, Отанға оралып, бұл тәжірибені енгізіп, іс жүзінде қолдану. Көлік, ең болмаса велосипед жүргізуге міндеттісіз. Үнемі қозғалыста болып, жол жүрумен байланысты кәсіп иесі болуыңыз керек. Егер қозғалмасаңыз, аяқпен мәселелер басталуы мүмкін. Сондай-ақ басқа адамдарды белгіленген жоспарларды жүзеге асыруға шабыттандыру керек.",
  "8": "Сіз заңдылықты, әділдікті, ар-намыс пен қадір-қасиетті қорғауда тұруыңыз керек. Ізгі болып, тараптарды татуластыру, қандай да бір дау-жанжалдарда «төреші» болу керек. Өз көзқарасыңыз болып, әрқашан ішкі адамгершілік бағдарларыңызды ұстануыңыз керек. Айналаңызда жанжалға, қорлауға, азғындық пен адалсыздыққа жол бермеу. Сізге дауласуға және жанжалдасуға болмайды. Тепе-теңдік пен ішкі үйлесімді сақтауды үйреніңіз. Заңды сақтау және Құқықты зерттеу маңызды. Сегіз — әділдік пен адалдық арканы.",
  "9": "Сізге әулетіңіздің дәстүрлеріне сәйкес рухани даму, жасы үлкен адамдармен араласу, көне мәдениеттерді, әулетіңіздің, мемлекеттің тарихын зерттеу керек. Әулетіңіздің аға буынына, әсіресе ата-анаңызға барынша көмектесу керек. Туыстарыңызға көмектескіңіз келмегендіктен ұзаққа созылған созылмалы аурулар көрінуі мүмкін. Сіз өмірдің мәнін тауып, басқалардың қателерінен үйренуіңіз керек. Өз біліміңіз бен тәжірибеңіздің арқасында есейген шағыңызда кеңеспен және сөзбен көмектесуіңіз керек. Бұл белгі сондай-ақ кез келген эзотерикалық бағытты зерттеу және дербес өмір салтын ұстану қажеттігін көрсетеді. Тоғызыншы арканның ақшамен ешқандай байланысы жоқ. Егер ақшаның бір бөлігін қарттар үйіне садақа етсеңіз, өткен өмірдің Карма мәселесін жабасыз. Сондай-ақ өз бизнесіңіз болса, зейнеткерлерге жеңілдік жасауыңызға болады.",
  "10": "Сізге ақшаға дұрыс көзқарас қалыптастыру керек. Олардың соңынан қумаңыз, өйткені олар сізге тек көрсеткен руханилығыңыз үшін жоғарғы күштердің алғысы арқылы ғана келеді. Сіз тек өзіңізді ғана емес, жақындарыңызды, ең алдымен балаларыңызды қамтамасыз етуіңіз керек. Жақындарыңыздың сіздің қаржылық мүмкіндіктеріңізге сүйенуге құқығы бар, бөлісуді үйреніңіз. Егер сіз әйел болсаңыз да, бәрібір отбасыңызды, соның ішінде күйеуіңізді де қамтамасыз етуіңіз керек. Өз бизнесіңіздің болуы маңызды. Несие алуға және біреуге қарыз болуға болмайды!",
  "11": "Бұл міндет мінез күшінің, зейінді шоғырландырудың жарқын қырларын береді. Алайда мәні — эмоциялар мен сезімдерді басқара білу, оларды жағымды жасампаз арнаға бағыттау. Жол беруді, күшті қарсыласпен өзара әрекеттесуді, күрделі одақта ымыраға келуді үйрену керек. Кедергілерден қорықпау, кез келген «толқынға» батыл бару, күресу және берілмеу. Өмірде оңай болмайды. Сондай-ақ айналаңызды қорғау керек. Сіздің міндетіңіз — қорғау, қамқорлық жасап, өз позицияңызды қорғау керек. Бойыңызда ерлік, батылдық, қаһармандық сияқты сезімдерді дамыту. Сондай-ақ қорқыныштарыңызды жеңуді үйрену керек. Спортпен айналысу немесе әскерде қызмет ету өте пайдалы. Мұндай міндеті бар адамдар жиі күш қолданатын ерлер кәсіптерін, сондай-ақ хирургияны таңдайды. Дәрігердің айтқанының бәрін қайта тексеру ұсынылады, өйткені дәрігерлік қателер және дұрыс қойылмаған диагноздар болуы мүмкін.",
  "12": "Міндет сізден адамдарды тыңдауды, естуді, түсінуді, ақтауды үйренуді сұрайды. Ол тікелей адамдармен жұмысқа байланысты (психология саласы мінсіз сай келеді). Адамдарға мәселелерін түсінуге көмектесу үшін түйсікті пайдалануды үйрену керек. 12-міндеті бар адамдар әдетте бөтеннің ауыруы мен уайымын бастан кешіріп, сезінеді. Сезімдер мен эмоцияларды көрсетуден ұялмаңыз, жаныңызды ашып, жанашырлық, түсіністік, сүйіспеншілік пен еркелік көрсетіңіз. Күшті, дана, шыдамды тәлімгер болуды үйреніңіз. Ішкі тепе-теңдік және жоғары мақсаттар үшін өз мүддеңізді құрбан ете білу маңызды.",
  "13": "Бұл міндеттің өз атауы бар — Раху міндеті. Кез келген салада жаңалық ашушы болу керек. Ешкім ешқашан жасамаған нәрсені ойлап табу, жасау, жаратып шығару. Өзіңізді тыңдауды және өзіңізді өмірге ерекше көзқарасы бар, қарапайым емес адам ретінде сезінуді үйрену маңызды. Онымен адамдармен бөлісіңіз. Адамдарға альтруизм, мейірімділік арқылы қызмет етіп, пайдасыз көмектесу керек. Үнемі жетіліп, жаңа мақсаттарға ұмтылу. Ғылыми, шығармашылық, медициналық төңкеріс жасау керек, әрі ол адамдарға пайдасын тигізуі керек. Егер адам 13-міндетті орындамаса, жақын адамдарынан айырылу, ауыр сынақтар, аурулар ықтималдығы жоғары.",
  "14": "Бұл миссия тек отбасыңыздың игілігіне ұмтыла отырып, үйлесімді әрі қанағатшыл өмір салтын ұстану қажеттігін көрсетеді. Байлықты оны қатты қаламасаңыз ғана, азға қуануды үйренсеңіз ғана береді. Сіз отбасыңыздың тірегі мен орталығы болып, оларға көмектесіп, туыстарыңызды шабыттандырып, оларға қамқорлық жасауыңыз керек. Татуластырушы, бітімгер, делдал болу. Адамдарды әлемді тамашалауға, оны тәжірибенің алуан түрлілігімен сүюге үйретіңіз. Өсімдік өсіруді және олармен сөйлесуді үйреніңіз. Бұл белгі адамды көп жағынан шектейді (ақшада, қоғамдағы орнында, эмоцияларда және т.б.). Бұл шектеулерді өз кәсібіңіз (ремеслоңыз) арқылы үзу керек, яғни өз қолыңызбен немесе ақылыңызбен бір нәрсе жасауды үйрену керек, сонда өмірдегі барлық жол сізге ашылады. 14-аркан шығын мен несиені жақтырмайды. Түрлі қарыздардан аулақ болған дұрыс.",
  "15": "Эзотерикамен айналысып, түрлі пәндерді зерттеу керек. Өз үлгіңізбен және өмір салтыңызбен азғырулардың, арбаулардың, білімнің, шығармашылық бағыттардың түрлі нұсқаларын көрсету маңызды. Сіз адамдарды толқытып, оларды эмоциялар мен сезімдерге оятуыңыз керек. Тағдырларға ықпал етуге де рұқсат етілген, бірақ қалай екенін тек өзіңіз шешесіз. 15-міндеті бар адамдар өз үлгісімен қалай болмау керегін көрсетуі керек! Оларға бәрінде «алтын ортаны» ұстанған дұрыс — басқалардың өмірін сәл бүлдіру, сәл көтермелеу, сәл жанжалдасып, кейін татуласу және т.б. Мұндай адамдарға сөзге сақ болып, жақындарыңыз бен таныстарыңызға міндетті түрде зиян келтіретін сөзді артынан айтпау керек.",
  "16": "Бұл — тура мағынада да, ауыспалы мағынада да (мысалы, адамдардың дүниетанымын қайта құру) құрылысшының белгісі. Міндетіңіз сіздің бұл сөздің кең мағынасында құрылысшы болуыңыз керек екенін айтады. Өзін ескірткен нәрседен алыстауды, өмірді жаңа, болашағы бар, өзекті нәрсе үшін тазартуды үйренуіңіз керек. Жаңа есіктерді ашуды үйренуіңіз керек. Сіздің міндетіңіз — адамдардың стереотиптерін бұзу, жаңа құндылықтар жүйесін құру, адамзатты жаңа ғарыштық заңдарға дайындау. Сондай-ақ 16-міндеті бар адамдарға үйінің күйін қадағалау керек (бәрі жөнделген, жұмыс істейтін және ақпайтын болуы керек).",
  "17": "Сізге таланттарыңызды, артистизміңізді дамыту, өзін-өзі көрсету, креативтілік, әсемдікті сезіну үстінде жұмыс істеу керек. Сіз біздің әлемге өз шығармашылық туындыларыңызды әкелуіңіз керек, тіпті ол бір ғана өлең немесе өзіңіз салған бір сурет болса да, бастысы — кішкентайдан бастау. Егер бұл мақсат тым биік көрінсе, төменгі деңгейде өз үйіңіздің немесе учаскеңіздің әдемі дизайнын ойластыру ұсынылады. Өнердің түрлі салаларында өзіңізді байқап көру және ішкі әлеміңізді шығармашылық арқылы көрсету маңызды (ғылым, эзотерика, өнер, би, фото, кино және т.б.). Бұл шығармашылықты адамдардан жасыруға болмайды, оны басқаларға көрсету керек (мысалы, әлеуметтік желілер арқылы).",
  "18": "Сіздің міндетіңіз басқалардың қажеттіліктерін сезінуіңізді пайдаланып, адамдарға сол немесе басқа сәтте не маңызды екенін түсініп, басқа адамдар үшін жайлылық пен жайлы орта жасау қажеттілігімен байланысты. Стиль, сұлулық, үйлесім сезімін дамытыңыз. Қиялыңыз бен елестету қабілетіңізді мүмкіндігінше жиі пайдаланыңыз. Үй шаруашылығымен өз бетіңізше айналысып, үйдегі қолөнерді үйрену керек. Түйсік пен көрегендікті пайдаланыңыз. Айналаңызға қамқорлық жасап, қырағылық танытып, жақын адамдарға уақытында көмек көрсетуіңіз керек. Кез келген ортада жылы атмосфера жасауыңыз керек, жақсы тамақ пісіре білуіңіз, сондай-ақ гардероб пен стильді өз бетіңізше таңдай білуіңіз керек. Бұл — стиль, сұлулық пен сән, тоқу, тігін және үйдегі қолөнер белгісі.",
  "19": "Сіз қоғамда жоғары мәртебе мен орынға қол жеткізіп (ауқымы маңызды емес), өз ортаңызда дана, сенімді әрі әділ көшбасшы болуыңыз керек. Жоғары лауазымда отырып, мансап сатысы бойынша табысқа ұмтыла отырып, айналаңызға қолдау көрсетіп, шабыттандырып, үлгі тұтарлық болыңыз. Басқаларға да мансап сатысында жылжуға міндетті түрде көмектесу керек, әйтпесе жоғары лауазымнан түсіреді!",
  "20": "Сіздің міндетіңіз — әулеттің дәстүрлері мен негіздерін қорғау, әулеттің барлық мүшелеріне материалдық та, рухани да игіліктерге ие болуға көмектесу. Әулеттің дәстүрлерін, негіздерін және заңдарын сақтау және ұрпаққа беру. Дұрыс құндылықтар жүйесін сақтап, беру, отбасылық таланттарды, кәсіптер мен дәстүрлерді қайта жаңғырту. Әулет туралы естелікті қалпына келтіру, барлық маңызды есімдерді жаңғырту, ата-бабалардың зираттарын күтіп, барлық туыстарға көмектесу керек. Отбасы болып, қала сыртында тұру (немесе табиғатта жиірек болу), ауыл шаруашылығымен айналысу, балаларды ескі дәстүрлерде тәрбиелеу маңызды. Сондай-ақ Рита (немесе телегония) заңдарын сақтап, әулеттің тазалығын ұстану ұсынылады.",
  "21": "Отанның өкілі және қорғаушысы болу керек. Елдің мүддесін білдіру, шетелде заңдарды сақтау, өз халқыңызды дәріптеу. Шетелде тұру немесе шетелдік компанияларда жұмыс істеу, шет тілінде сөйлесу маңызды. Басқа елдердің технологияларын біздің дәстүрлерге біріктіру. Адамдардың дүниетанымын кеңейту. Бойыңызда төзімділік, жаңаның бәріне ашықтық сияқты қасиеттерді қалыптастыруыңыз керек. Әлем бойынша көп саяхаттап, шетелдіктермен араласып, түрлі елдердің мәдениеттерін, талғамдарын, тіпті инновацияларын біріктіруге ұмтылуыңыз керек. Балаларыңыз әртүрлі тілдерді білуі, әртүрлі халықтардың мәдениетін, тарихы мен дәстүрлерін зерттеуі керек.",
  "22": "Сіздің міндетіңіз — балаларға қарызды өтеу, балаларға байланысты кәсіпті таңдаған дұрыс, осылайша Карманы түзету сізге оңайырақ болады. Басқа балаларды тәрбиелеп, оқыту керек (балабақшаға, мектепке барып, өз кәсібіңіз туралы айту және т.б.). Сіз балалар үшін тірек және қорғаушы, ұстаз, тәлімгер бола аласыз, бұл ретте баланы өмірінде сүйемелдеп, ол үшін толық жауапкершілікті қабылдау маңызды. Сіз ашық, достық пейілді, баладай аңғал адам, сенімді дос, жақындарыңыз үшін тірек болуыңыз керек. Бойыңыздағы мазасыздықты, агрессияны, ренжісті, ашуды, әсіресе балаларға қатысты сөндіру керек."
 },
 "day": {
  "1": "(1) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — көшбасшылық, мақсаткерлік, мақсат қойып, оған жете білу, сөзді меңгеру, білім алу және оны беру.\nОл үшін міндетті орындауыңыз керек — бауырларыңызға қамқорлық жасап, оларға кеңес беріп көмектесу, жанжалға жол бермеу. Егер олармен қарым-қатынас бітіспес болса, онда қарым-қатынас бейтарап, арақашықтықта болғаны жақсы. Егер бауырыңыз болмаса — бұл ата-ананың қатесі. Бұл жағдайда бағдарламаны шәкіртіңіз, тағылымдамашыңыз арқылы өңдеуге болады. Сондай-ақ ұстазға және алған білімге құрметпен қарап, үнемі жаңаны үйрену керек.\n«Бірдің» теріс көрінісі де бар — билікқұмарлық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бауырының сатқындығы, олармен жанжал, олардың ауруы. Құжаттарды рәсімдеуде қателер, сөйлеу, есте сақтау, есту қабілетінде мәселелер болуы мүмкін. Адам алаяқтардың құрбаны болуы мүмкін.",
  "2": "(2) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — сезімталдық, қамқорлық, мейірімділік, басқа адамдардың психофизикалық күйін сезіну, емшілік пен тәуіптік дарыны.\nОл үшін міндетті орындауыңыз керек — жақын әйелдерге (ана, әже, қыз) қамқорлық жасау. Бала кезден үй жануарларына күтім жасауға, табиғатты қорғауға ұмтылыңыз.\n«Екінің» теріс көрінісі де бар — өздерін ренжітетін адамдарға деген сезімсіздік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: жақын әйелдердің ауыр аурулары; жүктілікті сақтау мәселелері, түсік; ер адамдарда бедеулік (аспермия, азооспермия); анамен жанжал, әйелдер тарапынан сатқындық, сирек жағдайда — ананың қайтыс болуы; несеп-жыныс жүйесінің аурулары. Жұптың аналары қаламайынша, олардың отбасында бала болмайды.\n«Екілерді» оларға даналықты, жақындарға қамқорлық жасай білуді беру үшін әжелер тәрбиелеуі керек.\nНумерологияда 2 — экология, денсаулық, қамқорлық, мейірім, ана және жалпы әйел белгісі.",
  "3": "(3) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жақсы есте сақтау қабілеті, Жердің ментальді өрісінен ақпаратты оқи білу, жақсы оқу қабілеті, кез келген нәрсені үйрене алу, шашыраңқы ақпаратты біріктіру қабілеті, ойды материалдандыру дарыны («Құпия» (Секрет) фильмі).\nОл үшін міндетті орындауыңыз керек — ең болмаса бір баланы (асырап алған болса да) тәрбиелеп, оқытып, оған мансап құруға немесе бизнесті өз перзентіндей өсіруге көмектесу. «Үштер» өздері қаламаса, олардың балалары болмайды.\n«Үштің» теріс көрінісі де бар — дербес болмау, шабыт керек — «сиқырлы түрткі».\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бала тууға бөгет, жүкті болу мәселелері, ене мен қайын енемен жанжал, балалар тарапынан сатқындық, балалардың ауруы, сәттілік жоқ, нақты құрылған жоспарлар орындалмайды.\n«Үштерді» көбіне аналары тәрбиелеуі керек. Олар үшін әйел — бедел. Олардың аналарымен жиі күрделі қарым-қатынасы болады. Ер адамдар «әйелінің уысындағы» және «анасының еркесі» болып өсуі мүмкін.\nНумерологияда 3 — әкелік пен аналық белгісі.",
  "4": "(4) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жоғары кәсібилік, болжамдылық, тұрақтылық, сенімділік, еңбекқорлық, консерватизм.\nОл үшін міндетті орындауыңыз керек — таңдаған салада кәсіпқой болу. Шала жұмысқа жол берілмейді. Бала кезде сіздің жұмысыңыз — мектептегі оқу, жақсы оқу маңызды.\n«Төрттің» теріс көрінісі де бар — жалқаулық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: әріптестердің сатқындығы, мансаптың күйреуі, басшылықпен мәселелер, мансап сатысымен жоғарылаудағы қиындықтар, астыртын ойындар, тірек-қимыл аппаратымен мәселелер.\nНумерологияда 4 — император, мансап және бизнес белгісі. «Төрттерді» бір нәрсені тез үйрене алуы үшін абсолютті қатаңдықта тәрбиелеу керек. Оларға өте талапшыл болу керек. Тәрбиесі неғұрлым жұмсақ болса, тағдыры соғұрлым күрделі.",
  "5": "(5) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — кез келген нәрсені кез келген адамға сата білу қабілеті; ғылымдарды зерттеу қабілеті, жылдам ойлау, жеңіл жүкпен саяхаттауды жақсы көру, кез келген адаммен тіл табыса білу.\nОл үшін міндетті орындауыңыз керек — ер адамдарға құрметпен қарау, жақын ортадағы ер адамдарға көмектесу, дұрыс әрі салауатты өмір салтын ұстану (СӨС пен дұрыс тамақтану, спорт), рухани даму, үлгі тұтарлық болу. Жұмыста ер адамдарға жеңілдіктер мен акциялар жасау қолайлы.\n«Бестің» теріс көрінісі де бар — асығыстық, сырттай байыпсыздық, маскүнемдікке бейімділік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: әкемен жанжал, әкенің аурулары, сирек жағдайда — әкенің қайтыс болуы, басшылармен мәселелер, анестезияның артық мөлшері, Квинке ісінуі және демікпе қаупі жоғары.\nНумерологияда 5 — Ұлы Абыз (Верховный Жрец) белгісі. Бұл — барлық сұрақтың жауабын білетін адам. Ол дұрыс тамақтануды ұстанады, өйткені ағзасы улануға бейім. «Бестер» кез келген табиғи емес материалдар мен өнімдерге өте сезімтал. Жиі алкогольге тәуелді болады немесе аз мөлшердегі алкогольден уланып қалуы мүмкін. «Бестерді» әкелері немесе ер адам тәрбиелеуі керек. Тек ер адам ғана олар үшін бедел бола алады. Олар тағдырымен әкесіне байланған. «Бес» әйелдерге онша белсенді емес ер адамдар беріледі.",
  "6": "(6) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — сыртқы тартымдылық, харизма, сүйкімділік, қонақжайлылық, басқа адамдардың қажеттіліктерін біледі, стиль сезімі бар (жақсы модельер бола алады), қолөнерге талантты, жақындарын алыстан сезеді.\nОл үшін міндетті орындауыңыз керек — ресми некеде болып, отбасы мүшелеріне, ата-анаға және барлық ұрпаққа қамқорлық жасау керек. Отбасылық қарым-қатынаста үлгі, эталон болу, ажырасуға және опасыздық жасауға, тіпті ойша да болмайды.\n«Алтының» теріс көрінісі де бар — қыңырлық (өте қыңыр).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: мүлікті бөлісумен ажырасу, кармалық қарым-қатынас, серіктестердің, соның ішінде іскерлік серіктестердің опасыздығы мен сатқындығы, мәмілелер мен келісімшарттардың бұзылуы, жүрек-қантамыр жүйесінде мәселелер.\nНумерологияда 6 — отбасы, үйдегі қолөнер мен үйдегі шығармашылық, сондай-ақ серіктестік белгісі.\nЕгер сіз опасыздық жасаған адам сізді шын жүректен кешірсе, белгінің теріс көріністері жұмсарады.",
  "7": "(7) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жылдам ойлау, бәрін терең тану, киелі нәрсені зерттеуді жақсы көреді, карма заңдарын сезеді, себеп-салдарлық байланыстарды (неге солай болатынын) көреді, жағдайды алдын ала болжай алады, бірақ оны өзгерте алмайды, сондықтан өз дарынын жиі қарғыс ретінде қабылдайды. «Жетілер» өте тапқыр.\nОл үшін міндетті орындауыңыз керек — ең болмаса ел ішінде саяхаттап, басқа халықтардың мәдениетін зерттеп, олардың технологияларын өз өміріңізде қолдану керек. Өмірге кішкентай пайдалы нәрселер ойлап табу (ең болмаса пакеттерге арналған пакет). Көлік, велосипед, самокат жүргізгені жақсы, жұмысты жол жүрумен, іссапарлармен байланыстысын таңдаған дұрыс, семинар өткізсеңіз, вебинар емес, көшпелі семинар өткізіңіз.\n«Жетінің» теріс көрінісі де бар — айлакерлік, арандатуға бейімділік, біліммен бөліскісі келмеу.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: көлікпен мәселелер (жиі бұзылу), автонесиелермен мәселелер (не бермейді, не төлемдерде қиындық), ұсақ жол-көлік оқиғалары (өлімге әкелмейтін), аяқпен мәселелер, тіпті сал болуға дейін, мансап пен бизнестегі кедергілер.\nНумерологияда 7 — арба (колесница), қозғалыс белгісі. «Жетілер» барлық жасырын, киелі нәрсені жақсы көреді және зияткерлік дамуға ұмтылады.",
  "8": "(8) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — ғалам заңдарына, тепе-теңдікке, әділдікке жауап беру, соттау құқығына ие болу.\nОл үшін міндетті орындауыңыз керек — тараптарды татуластыруыңыз керек, құқықты зерттеп, дұрыс шешім қабылдауды үйрену, сөзде тұру керек, заң бұзуға болмайды, жанжалдасуға болмайды.\n«Сегіздің» теріс көрінісі де бар — жанжалшылдық (адамдарға бұлай істеуге болмайтынын түсіндіруден шаршағандықтан).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бизнестегі мәселелер, әріптестер тарапынан арандату мен сатқындық, мұндай қызметкердің еңбегін байқамайды, омыртқамен мәселелер, көбіне бел бөлімі, жарықтар (грыжи), омыртқаның сыну қаупі.\nНумерологияда 8 — әділдік, сот төрелігі белгісі. Олардан тамаша заңгерлер шығады, өйткені олар заңдарды санаасты деңгейде біледі. Олар әрқашан жанжалды ортада өмір сүреді, құжаттарды тамаша қолдан жасайды, жиі қос өмір сүреді.",
  "9": "(9) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — «айқын» деген сөзбен басталатынның бәрі (айқын көру, айқын білу, айқын есту...); астралды қауыммен байланыс (періштелер, архангелдер, жоғары періштелер, қамқоршылар); бақсылық (шаманство), регрессия, экстрасенсорика; дербестік, өзін-өзі жеткілікті сезіну.\nОл үшін міндетті орындауыңыз керек — экстрасенсорлық қабілеттерді дамыту, ешкімге сүйенбей, өзін-өзі жеткілікті, дербес тұлға болу. Аға буынға көмек көрсету керек. Аға буын адамдарына жеңілдіктер немесе акциялар жасау қолайлы. Егер «тоғыз» әлеуметтік игіліктерден өз еркімен бас тартпаса, оны жоғалтулар арқылы кесіп тастайды.\n«Тоғыздың» теріс көрінісі де бар — жалғыздықтан қорқу, өзімшілдік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: оқшаулану, әлеуметтік өлім, ауруханаға жиі түсу.\nНумерологияда 9 — экстрасенсорика, дербестік, аға буын, қызмет ету белгісі.\n«Тоғыздың» санаастында жалғыздықтан қорқу бар. Олар жалғыз қалудан қорыққандықтан серіктесіне сұмдық нәрселерді кешіре алады, бірақ олар дәл жалғыздықта ашылады.\n«Тоғыздар» шын жүректен сүйе алмайды, олар өзін сол немесе басқа жағдайда сүйеді.",
  "10": "(10) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — көшбасшылық, мақсаткерлік, мақсат қойып, оған жете білу, сөзді меңгеру, білім алу және оны беру.\nОл үшін міндетті орындауыңыз керек — жақындарыңызды материалдық жағынан қамтамасыз етуіңіз немесе жақын адамыңыз өзін қамтамасыз ете алуы не өз бизнесін құра алуы үшін жайлы тұрмыстық жағдай жасауыңыз керек. Егер мұны істемесе, белгі минусқа кетеді.\n10 — жартылай кармалық туған күн. Қазір туған күнде өткен өмірде жіберілген кармалық мінез ерекшелігі көрінеді. Адам өткен өмірінде қаржы мәселелерінде тым пайдакүнем болған. Бірінші метациклде ол міндетті түрде отбасын қамтамасыз ету мәселесімен айналысуы керек. Егер міндетті орындай алмаса — ақшадан айырыла бастайды.\n10-ның теріс көрінісі де бар — билікқұмарлық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: барлық айналымдағы процестердің (бизнес, сауда) тоқтауы, ірі қаржылық мәселелер, сәттіліктің болмауы, жазатайым оқиғалар. Ағзадағы сұйықтық айналымының бұзылуы, сусыздану, лимфа мен қанның іркілуі; жиі сүйек аппаратының деформациясына әкелетін лимфамен мәселелер, ісінулер.\nНумерологияда 10 — бақ (фортуна) белгісі.",
  "11": "(11) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — сезімталдық, қамқорлық, мейірімділік, басқа адамдардың психофизикалық күйін сезіну, емшілік пен тәуіптік дарыны, басқа адамдардың эмоцияларын басқару қабілеті және ой күшімен адамды тоқтата алу қабілеті.\nОл үшін міндетті орындауыңыз керек — айналаңызды сөзбен қорғауыңыз керек.\n11 — жартылай кармалық туған күн. Қазір туған күнде өткен өмірде жіберілген кармалық мінез ерекшелігі көрінеді. Адам өткен өмірінде психофизикалық күшті асыра қолданған. Міндетін орындауға тырысса да, шамадан тыс агрессиялы болған. Оған бұл өмірде басқа адамдарды татуластыруды, қорғауды, көңілін көтеруді және жақындарының физикалық әрі психикалық күйіне қамқорлық жасауды үйрену маңызды.\n11-дің теріс көрінісі де бар — өздерін ренжіткендерге деген жүрексіздік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: жарақаттар, мертігу, жаралану; шабуылдар; зорлық-зомбылық; қажетсіз хирургиялық операциялар, оның өзінде жиі мүлдем басқа жағынан кеседі; дәрігерлік қателер; жасырын жаулар.\nНумерологияда 11 — күш белгісі.\nБарлығына бәсекелестік пен қарсыласу арқылы жетеді. Барлығынан жау көреді, бәріне күдікпен қарайды.",
  "12": "(12) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жақсы есте сақтау қабілеті, Жердің ментальді өрісінен ақпаратты оқи білу, жақсы оқу қабілеті, кез келген нәрсені үйрене алу, шашыраңқы ақпаратты біріктіру қабілеті, ойды материалдандыру дарыны («Құпия» (Секрет) фильмі).\nОл үшін міндетті орындауыңыз керек — адамдарға күн астындағы өз орнын, өз арнауын табуға көмектесу, пайдасыз көмектесу, айналаңызды психологиялық тұрғыдан қолдау керек.\n12 — жартылай кармалық туған күн. Қазір туған күнде өткен өмірде жіберілген кармалық мінез ерекшелігі көрінеді. Адам өткен өмірінде сәл дөрекі болған, айналасына жеткілікті жұмсақ қарамаған. Ол тек өзіне сеніп, өзіне ғана сүйенген. Енді ол тек өзіне бағдар алуы керек. Ешкімге сүйене алмайды.\n12-нің теріс көрінісі де бар — дербес болмау.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: депрессиялар, тәуелділіктің барлық түрлері, өзін түсінбеу, қоғамның айыптауы, қоғам тарапынан қолдаудың болмауы, онкология (белгінің ең күшті көрінісі).\nНумерологияда 12 — пайдакүнем болмау белгісі.\n12-лер шексіз сезімтал, әлемді жиі қызғылт түсте көреді, сондықтан өздерін қорлайтындарға тәуелді болып, оларды үнемі ақтайды.",
  "13": "(13) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — стандартты емес ойлау, мүлдем болжауға келмейтін адамдар, гипноздық қасиеттерге ие, балама нұсқаларды көре алады, жаңа істерсіз отыра алмайды.\nОл үшін міндетті орындауыңыз керек — сізге дейін ешкім ешқашан жасамаған нәрсені жасау, ең болмаса бір адамды сізге ілесуге шабыттандыру, жұмыс үшін көп міндетті жұмысты таңдаған дұрыс, мысалы, заңгерлік, құрылыс компаниялары, жаңа жобалар.\n13 — жартылай кармалық туған күн. Қазір туған күнде өткен өмірде жіберілген кармалық мінез ерекшелігі көрінеді. Өткен өмірінде мұндай адам әрқашан паровоздан алда жүгірген. Бұл өмірде оған ең күрделі міндет бұйырды — жаңалық ашушы болу, жаңа жолдар салу және көпшілікті соңынан ерту. Тұрақты нәрсенің бәрі адамнан алынады. Оның міндеті — үнемі жаңа энергоақпараттық ағында болу.\n13-тің теріс көрінісі де бар — жалқаулық (қорқынышты емес, кейде жалқаулануға болады).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: жоспарлардың бұзылуы, бәрі сіз ойлағаннан бірнеше есе нашар болады, өмірдегі күрт өзгерістер, апаттар, катастрофалар мүмкіндігі, жақындарды жоғалту, әлеуметтік өлім (қандай да бір істе айналадағылардың түсінбеуі, психиканың қайта туылуы).\nНумерологияда 13 — бұзылу, жаңа қасиеттерге ие болу арқылы трансформация белгісі.",
  "14": "(14) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — басқа адамдардың қажеттілігін түсіну, қарым-қатынасқа ашықтық.\nОл үшін міндетті орындауыңыз керек — бөлісу керек.\n14 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Адам өткен өмірінде тым сараң болған (сараңдық кез келген болуы мүмкін: білімге, ақшаға, эмоцияларға, әсерлерге, махаббатқа сараңдық). Сондықтан бұл өмірде оны көп жағынан шектейді. Оның негізгі міндеті — барына қанағат етуді үйрену. Барынан ләззат ала бастаған бойда — оған көбірек береді. Егер бұл өмірде адамға сараңдық сияқты қасиет тән болса — ол бұл кемшілікпен міндетті түрде күресуі керек.\nАуыл шаруашылығымен айналысу қолайлы. Өсімдік өсіріп, олармен адамдарды тамақтандыру (ең кемі — салатқа арналған салат жапырағын, райхан... өсіру). Әулеттің кәсіптерін қайта жаңғырту немесе жаңаларын бастау қолайлы.\n14-тің теріс көрінісі де бар — асығыстық, сырттай байыпсыздық, маскүнемдікке бейімділік, тоқыраған адамдар, жиі ережемен өмір сүреді.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: «барабашка» (үй иесі рухы) белгісі: үнемі жасырынып жүретін жасырын аурулар, мәселелер және т.б. Немесе мәселе оны түзету мүмкін болмай қалғанда ғана көрінеді. Баяу күйзеліс (разорение). Қазіргі сәтте қажетсіз, табыс пен пайда әкелмейтін нәрсені өз бетімен кесіп тастауды үйрену керек, әйтпесе мүлік пен денсаулықтан толық айырылу. Емделу уақытын жіберіп алу, анықтау қиын аурулар.\nНумерологияда 14 — қанағат (умеренность) белгісі.\nБұл күні туған адамдар «қолдағы торғайды» жақсы көреді. Бұлар — жанының тереңінде ең жомарт адамдар.\nОларда жасушаларды өсіру қабілеті бар. Қолдарында энергия жатыр.\nМұндай адамдарға онкологиялық науқастарға қол тигізуге болмайды!",
  "15": "(15) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — шайтандай тартымды, керемет баурағыш әрі сексуалды болу. Бұлар — тамаша ұйымдастырушылар. Хирургтар, әсіресе нейрохирургтар. Ең күшті рухани тәлімгерлер. Қоғамда — бұлар катализатор адамдар. Олардың қатысуымен керекті жауаптар ойға келеді. Абсолютті магиялық қорғаныс.\nОл үшін міндетті орындауыңыз керек — басқа адамдардың өмірін бүлдіру, адамдарды бір-біріне айдап салу, оларды басқару (манипуляция), не эзотерикамен, магиямен айналысу керек.\nБолмайды: 2 жақтың (қараңғы/жарық) біреуін ғана қабылдау, қараңғы жақпен келісімшартты бұзу; жаман да, жақсы да қылықтар жасап, тепе-теңдік іздеу керек.\nЕгер мұндай адам тек қараңғы жақпен жүрсе, карма бойынша жазаланады.\n15 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Адам өткен өмірінде оған рұқсаты болмай тұрып оккультизммен айналысқан. Адамда болуы мүмкін онкологияның себептерінің бірі дәл өткен өмірде жатыр (басқа адамға зиян келтіру мақсатында рәсімдер жасау немесе осы мақсатпен маманға жүгіну). Егер мұндай адам бұл өмірде жарық жолға түсуді шешсе — оған өмірде сынақтардан өтуге тура келеді.\n15-тің теріс көрінісі де бар — қыңырлық (өте қыңыр).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: жақын адамдарды жоғалту, кез келген жағдайды абсолютті минусқа дейін өршіту (шыбыннан түйе жасау), мансап пен бизнестің күйреуі, қабілеттердің жабылуы, өткір бітіспес жанжалдар, психиканың бұзылуы, жедел өтетін ауыр аурулар, кеш сатыларда анықталған онкология (жиі — ми онкологиясы).\nНумерологияда 15 — магия, қылмыс, сексуалдылық, эзотерика белгісі.\nӨткен өмірінде қылмыспен немесе магиямен айналысқан. Түрмеге түскенде мұндай адамдар солып қалмай, керісінше дамиды. Оларға алкоголь мен есірткі әсер етпейді, денсаулығына зиян келтірмейді.",
  "16": "(16) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — мұндай адамдарды барлық ерекше әрі жұмбақ нәрсе қызықтырады, олардың өрісінде адамдардың теріс қасиеттері қоздырылады, өйткені олар адамдардың энергетикасын тазартуы керек (бірақ мұны әрқашан істей бермейді).\nОл үшін міндетті орындауыңыз керек — үй салу, адамдардың дүниетанымын құру.\n16 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Адам өткен өмірінде басқа адамдардың өмірін бұзған. Бұл өмірде оған үйлесімді қарым-қатынас құруды; адамдарды қосуды; басқаларға мүлік пен баспанаға ие болуға көмектесуді (құрылыс, жөндеу, риэлторлық) үйрену керек. Ол ешбір жағдайда бұзуға кеңес бермеуі керек. Өз үйін салу; үйдің техникалық күйін қадағалау қолайлы.\n- мұра сұрауға болмайды\n- бұзушы кеңестер беруге болмайды, тек жасампаздық\n- отбасыларды біріктіру\n- бөтеннің мүлкіне қызғануға болмайды\n- өткенмен оңай қоштасуды үйрену\n- жылжымайтын мүлікті өз атыңызға рәсімдеу қалаусыз.\n- отпен сақ болу\n- үй салып, оны өз атыңызға рәсімдемеу.\n16-ның теріс көрінісі де бар — айлакерлік, ойланбай кесіп тастайды, «қара тізімдері» бар, қажетсіз нәрсені жинауға, үйді қоқысқа толтыруға бейім; бала кезде бәрін сындырады.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: осы салада қалпына келтіру мүмкіндігінсіз мансап пен бизнестің түбірімен күйреуі, жылжымайтын мүлікпен және оны рәсімдеумен мәселелер, баспанасыз қалу қаупі, жылжымайтын мүліктен айырылу, адамнан өмірлік маңызды бір нәрсені (отбасы, бизнес, мүше) тартып алады, мүшелерді бөлік-бөлігімен алып тастайды.\nНумерологияда 16 — құрылыс (рухани немесе жердегі) белгісі. Адам неғұрлым көп салса, соғұрлым көп игілік алады.",
  "17": "(17) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — романтикалық және талантты болу.\nОл үшін міндетті орындауыңыз керек — талантты адамдарға танымал болуға көмектесу. Өз таланттарыңызды ашып, өзіңіз танымал болуыңыз керек: камера, ютуб... Шығармашылықпен айналысу керек: ғылым, эзотерика, өнер.\n17 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Мұндай адам өткен өмірінде «жұлдыз» болған. Бұл өмірде ол даңқ пен құрметке жұмсағырақ қарауы керек. Өткен өмірінде мұндай адам жалған пайғамбар, жалған ұстаз болуы, авторлық құқықты бұзуы, талантты адамдарға сатқындық жасауы немесе мансап сатысымен даңқ пен гүлденуге тым жылдам көтерілуі мүмкін. Бұл өмірде танымал тұлға болу үшін оған көп нәрсені үйреніп, түсіну керек. Ең алдымен өзі туралы. Мұндай адам даңқ өмірдегі ең басты нәрсе емес екенін түсінбейінше, әрқашан екінші қатарда болады. Кәсіпқой болу керек, сонда оған адамдар тартылады.\n17-нің теріс көрінісі де бар — жанжалшылдық.\nМіндет орындалмаса (өнертабысты, авторлықты ұрласа), жағымсыз оқиғалар болуы мүмкін:\n- тура және ауыспалы мағынада биіктен құлау,\n- мансаптың күйреуі,\n- әскери қызметшілер үшін — погонынан айырылу қаупі,\n- жоғары жылдамдықтағы жол-көлік оқиғалары,\n- әуе апаттары,\n- бронх-өкпе жүйесімен мәселелер.\nТіпті интернетте де шынайы авторлықты міндетті түрде көрсету керек.\nЕң талантты адамдар 17 қыркүйекте туған.\nНумерологияда 17 — жұлдыз белгісі. Бұлар — өте талантты адамдар, бірақ бұл туралы білмейді.\nЕгер мұндай адамдарды бала кезде басып тастаса, олар циник болып кетеді.",
  "18": "(18) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді —\n- бала кезден өте артистік,\n- өтірікті нәзік сезеді, бірақ өздері әсірелеуге бейім,\n- қалай алдауды біледі,\n- оларда алаяқтық рухы бар,\n- соңғы вагонға секіріп мінеді, жауды тылдан айналып өтеді,\n- өтірікке өте сезімтал,\n- үйде отырғанды жақсы көреді.\nОл үшін міндетті орындауыңыз керек —\n- үй жұмыскерін жалдамай, үй шаруашылығын жеке өзіңіз жүргізу керек,\n- үйдің дизайнымен және әсемдігімен жеке өзіңіз айналысу,\n- ата-анаға көмектесу,\n- жанжалға жол берілмейді.\n18 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Мұндай адам өткен өмірінде өте көп алдаған, бұл өмірде мұны істеуге болмайды. Ол басқа адамдардың логикасын өте нәзік сезеді. Бұл — шығармашыл әрі түйсігі мықты адам. Одан тамаша аспаз, актер немесе дизайнер шығуы мүмкін. Мұндай адам әсірелегенді жақсы көреді. Оның талантын шығармашылық кәсіпте қолданып, дұрыс арнаға бағыттауға болады.\n18-дің теріс көрінісі де бар —\n- ата-анамен жиі жанжал және шиеленіскен қарым-қатынас, оларды жиі елемейді,\n- ата-анасына шағымданады (жала жабады).\n18-лер — жақын ортада (өзіне сенетіндермен) өзімшіл және (ұсақ) алаяқтар — сәл өтірік айтты, бір жерде ақшаны толық бермеді. Әрине, үлкендерді құрметтемеу — әңгімені бөлу, қол сілтеу. Кейін: «Сіздер қандай ызыңсыздар, сіздермен қандай іш пыстырарлық әрі қызықсыз!» деп айту. Осылайша өз қылықтарын ақтау.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін:\n- адамды алдау,\n- алаяқтықтың құрбаны болу,\n- өзі шыңы болмайтын махаббат үшбұрышына қатысу,\n- жайсыз өмір,\n- жайсыз үй, тұрмыстық келеңсіздіктер, ұсақ жөндеу қажет,\n- ішек, бүйрек, несепағармен мәселелер.\nНумерологияда 18 — үй, үй жайлылығы мен әсемдік белгісі.",
  "19": "(19) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — мәртебелілік, мақсаткерлік, мақсат қойып, оған жете білу, айналадағылардың беделі мен құрметі.\nОл үшін міндетті орындауыңыз керек — өз орныңызды пайдаланып, өмір бойы басқа адамдарға көмектесу керек. Өкілеттіктеріңізді өз пайдаңызға қолданбауыңыз керек. Достар, туыстар ортасында мәртебеге жету қолайлы. Сізді құрметтеп, сізден кеңес сұрауы керек. Сіз айналадағылар үшін бедел болуыңыз керек.\n19 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Мұндай адам өткен өмірінде өте жоғары лауазымда болған. Ол министр, шенеунік, ірі өнеркәсіпші немесе кәсіпкер болуы мүмкін. Адам билігін теріс пайдаланған. Ол ерік бостандығы заңын бұзған, сондықтан бұл өмірде басқа адамдарға қысым жасамай, оларды шабыттандыру аса маңызды.\n19-дың теріс көрінісі де бар — билікқұмарлық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін:\n- мәртебе мен биліктен айырылу,\n- беделге нұқсан келу,\n- мансаптағы мәселе,\n- қарсыластардың астыртын ойындары,\n- шенеуніктермен және мемлекетпен мәселелер (арандату),\n- 19-дарды түрмеге отырғызбайды, бірақ мәртебесінен айырады, мұны дабырамен, жанжалмен жасайды,\n- ағзадағы күшті қабыну процестері,\n- ағзаның жедел улануы, лимфа айналымы мен шығару жүйелерінің бұзылуы.\nНумерологияда 19 — мәртебе мен билік, қоғамдағы жоғары орын белгісі.",
  "20": "(20) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — мейірім, қамқорлық, рақымдылық, басқа адамдардың психофизикалық күйін сезіну, емшілік пен тәуіптік дарыны.\nОл үшін міндетті орындауыңыз керек — әулеттің (Родтың), халықтың дәстүрлерін еске түсіріп, қолдау немесе өз дәстүрлеріңізді ойлап табу керек. Әулетіңіздің мүшелеріне көмектесу қолайлы.\n20 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Мұндай адам өткен өмірінде өз әулетінің дәстүрлерін сатқан. Мұндай бұзушылықтарға: некеден тыс қарым-қатынас, басқа ұлт өкілімен қарым-қатынас, бөтен мәдениетке кету және тағы басқалар жатады. Соның ішінде адам өз ата-бабаларын есіне алмаған жағдай.\n20-ның теріс көрінісі де бар — өздерін ренжітетін адамдарға деген сезімсіздік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін:\n- әулеттің барлық мүшелерімен жанжал,\n- олар тарапынан сатқындық (сотқа беруге болмайды),\n- туыстардың аурулары,\n- балалардағы генетикалық ауытқулар.\nНумерологияда 20 — Әулет (Род) белгісі.",
  "21": "(21) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жақсы есте сақтау қабілеті, Жердің ментальді өрісінен ақпаратты оқи білу, жақсы оқу қабілеті, кез келген нәрсені үйрене алу, шашыраңқы ақпаратты біріктіру қабілеті, ойды материалдандыру дарыны («Құпия» (Секрет) фильмі).\nОл үшін міндетті орындауыңыз керек —\n- шетелге саяхаттау керек,\n- шетелде тұрып, Отанды дәріптеу, Отанның дәстүрлерін сақтау және отандастарыңызға көмектесу,\n- немесе шетелде тұру,\n- немесе шетелдікке тұрмысқа шығу,\n- немесе шетелдік компанияда шетелдіктермен жұмыс істеу,\n- немесе шетелдіктерге кеңес беру,\n- шет тілдерін үйрену (ең болмаса шет тілін түсінуі керек).\n21 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Мұндай адам өткен өмірінде өз Отанына қатысты қылмыс жасаған. Ол басқа мемлекеттің мүддесін білдіруі, өз талантын бөтен елге сатуы, Отанды қорғағысы келмеуі мүмкін. Немесе әйел өз әулетіне ұрпақ тапқысы келмеген.\n21-дің теріс көрінісі де бар — дербес болмау, шабыт керек — «сиқырлы түрткі».\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін:\n- шетелдегі мәселелер, тіпті депортацияға дейін,\n- шетелдіктер немесе шетелдегі отандастар тарапынан сатқындық,\n- паразиттік аурулардың барлық түрлері, сирек вирустар мен аурулар.\nНумерологияда 21 — әлем белгісі.",
  "22": "(22) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — достық пейіл және балаларды сезіну/түсіну, бірнеше істі бір мезгілде атқара білу.\nОл үшін міндетті орындауыңыз керек —\n- өз балаларыңызды тәрбиелеумен жеке айналысу және (немесе) жұмыста көп міндеттілік,\n- бизнес: филиалдар, желі, көп мақсатты бизнес.\n22 — кармалық туған күн. Қазір туған күнде өткен өмірдің өтілмеген сабағы көрінеді. Мұндай адам өткен өмірінде балаларына дөрекі қараған. Өткендегі түсік жасатуды көрсетуі мүмкін. Немесе адам балаларын тастап кеткен, оларды тәрбиелегісі келмеген.\n22-нің теріс көрінісі де бар — жалқаулық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін:\n- достар мен 7 жасқа дейінгі кішкентай балалар тарапынан сатқындық,\n- көптеген ұсақ пайдасыз әбігер; неге жармасарын білмейді,\n- бір шешілген мәселе бірнеше жаңасын тудырады,\n- балалар вирустары мен аурулары,\n- міндет орындалмаса — мүгедектік белгісі, жиі ақымақтықтан.\nНумерологияда 22 — балалық шақ пен көптік, достық белгісі.\nБұлар — тәттіні және кәмпитті (кейде) жақсы көретін ең достық пейілді адамдар.\nОлар көп балалы отбасыларда (3 баладан бастап) тууы керек, егер отбасы көп балалы болмаса, белгі достық арқылы өңделеді.",
  "23": "23 санында Меркурий (5) және Күн (1) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n(1) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — көшбасшылық, мақсаткерлік, мақсат қойып, оған жете білу, сөзді меңгеру, білім алу және оны беру.\nОл үшін міндетті орындауыңыз керек — бауырларыңызға қамқорлық жасап, оларға кеңес беріп көмектесу, жанжалға жол бермеу. Егер олармен қарым-қатынас бітіспес болса, онда қарым-қатынас бейтарап, арақашықтықта болғаны жақсы. Егер бауырыңыз болмаса — бұл ата-ананың қатесі. Бұл жағдайда бағдарламаны шәкіртіңіз, тағылымдамашыңыз арқылы өңдеуге болады. Сондай-ақ ұстазға және алған білімге құрметпен қарап, үнемі жаңаны үйрену керек.\n«Бірдің» теріс көрінісі де бар — билікқұмарлық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бауырының сатқындығы, олармен жанжал, олардың ауруы. Құжаттарды рәсімдеуде қателер, сөйлеу, есте сақтау, есту қабілетінде мәселелер болуы мүмкін. Адам алаяқтардың құрбаны болуы мүмкін.\n\n(5) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — кез келген нәрсені кез келген адамға сата білу қабілеті; ғылымдарды зерттеу қабілеті, жылдам ойлау, жеңіл жүкпен саяхаттауды жақсы көру, кез келген адаммен тіл табыса білу.\nОл үшін міндетті орындауыңыз керек — ер адамдарға құрметпен қарау, жақын ортадағы ер адамдарға көмектесу, дұрыс әрі салауатты өмір салтын ұстану (СӨС пен дұрыс тамақтану, спорт), рухани даму, үлгі тұтарлық болу. Жұмыста ер адамдарға жеңілдіктер мен акциялар жасау қолайлы.\n«Бестің» теріс көрінісі де бар — асығыстық, сырттай байыпсыздық, маскүнемдікке бейімділік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: әкемен жанжал, әкенің аурулары, сирек жағдайда — әкенің қайтыс болуы, басшылармен мәселелер, анестезияның артық мөлшері, Квинке ісінуі және демікпе қаупі жоғары.\nНумерологияда 5 — Ұлы Абыз (Верховный Жрец) белгісі. Бұл — барлық сұрақтың жауабын білетін адам. Ол дұрыс тамақтануды ұстанады, өйткені ағзасы улануға бейім. «Бестер» кез келген табиғи емес материалдар мен өнімдерге өте сезімтал. Жиі алкогольге тәуелді болады немесе аз мөлшердегі алкогольден уланып қалуы мүмкін. Тек ер адам ғана олар үшін бедел бола алады. Олар тағдырымен әкесіне байланған. «Бес» әйелдерге онша белсенді емес ер адамдар беріледі.",
  "24": "24 санында Венера (6) және Ай (2) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n24 — жұмсақ адамдар.\n(2) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — сезімталдық, қамқорлық, мейірімділік, басқа адамдардың психофизикалық күйін сезіну, емшілік пен тәуіптік дарыны.\nОл үшін міндетті орындауыңыз керек — жақын әйелдерге (ана, әже, қыз) қамқорлық жасау. Бала кезден үй жануарларына күтім жасауға, табиғатты қорғауға ұмтылыңыз.\n«Екінің» теріс көрінісі де бар — өздерін ренжітетін адамдарға деген сезімсіздік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: жақын әйелдердің ауыр аурулары; жүктілікті сақтау мәселелері, түсік; ер адамдарда бедеулік (аспермия, азооспермия); анамен жанжал, әйелдер тарапынан сатқындық, сирек жағдайда — ананың қайтыс болуы; несеп-жыныс жүйесінің аурулары. Жұптың аналары қаламайынша, олардың отбасында бала болмайды.\n«Екілерді» оларға даналықты, жақындарға қамқорлық жасай білуді беру үшін әжелер тәрбиелеуі керек.\nНумерологияда 2 — экология, денсаулық, қамқорлық, мейірім, ана және жалпы әйел белгісі.\n\n(6) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — сыртқы тартымдылық, харизма, сүйкімділік, қонақжайлылық, басқа адамдардың қажеттіліктерін біледі, стиль сезімі бар (жақсы модельер бола алады), қолөнерге талантты, жақындарын алыстан сезеді.\nОл үшін міндетті орындауыңыз керек — ресми некеде болып, отбасы мүшелеріне, ата-анаға және барлық ұрпаққа қамқорлық жасау керек. Отбасылық қарым-қатынаста үлгі, эталон болу, ажырасуға және опасыздық жасауға, тіпті ойша да болмайды.\n«Алтының» теріс көрінісі де бар — қыңырлық (өте қыңыр).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: мүлікті бөлісумен ажырасу, кармалық қарым-қатынас, серіктестердің, соның ішінде іскерлік серіктестердің опасыздығы мен сатқындығы, мәмілелер мен келісімшарттардың бұзылуы, жүрек-қантамыр жүйесінде мәселелер.\nНумерологияда 6 — отбасы, үйдегі қолөнер мен үйдегі шығармашылық, сондай-ақ серіктестік белгісі.\nЕгер сіз опасыздық жасаған адам сізді шын жүректен кешірсе, белгінің теріс көріністері жұмсарады.",
  "25": "25 санында Кету (7) және Юпитер (3) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n(3) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жақсы есте сақтау қабілеті, Жердің ментальді өрісінен ақпаратты оқи білу, жақсы оқу қабілеті, кез келген нәрсені үйрене алу, шашыраңқы ақпаратты біріктіру қабілеті, ойды материалдандыру дарыны («Құпия» (Секрет) фильмі).\nОл үшін міндетті орындауыңыз керек — ең болмаса бір баланы (асырап алған болса да) тәрбиелеп, оқытып, оған мансап құруға немесе бизнесті өз перзентіндей өсіруге көмектесу. «Үштер» өздері қаламаса, олардың балалары болмайды.\n«Үштің» теріс көрінісі де бар — дербес болмау, шабыт керек — «сиқырлы түрткі».\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бала тууға бөгет, жүкті болу мәселелері, ене мен қайын енемен жанжал, балалар тарапынан сатқындық, балалардың ауруы, сәттілік жоқ, нақты құрылған жоспарлар орындалмайды.\n«Үштерді» көбіне аналары тәрбиелеуі керек. Олар үшін әйел — бедел. Олардың аналарымен жиі күрделі қарым-қатынасы болады. Ер адамдар «әйелінің уысындағы» және «анасының еркесі» болып өсуі мүмкін.\nНумерологияда 3 — әкелік пен аналық белгісі.\n\n(7) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жылдам ойлау, бәрін терең тану, киелі нәрсені зерттеуді жақсы көреді, карма заңдарын сезеді, себеп-салдарлық байланыстарды (неге солай болатынын) көреді, жағдайды алдын ала болжай алады, бірақ оны өзгерте алмайды, сондықтан өз дарынын жиі қарғыс ретінде қабылдайды. «Жетілер» өте тапқыр.\nОл үшін міндетті орындауыңыз керек — ең болмаса ел ішінде саяхаттап, басқа халықтардың мәдениетін зерттеп, олардың технологияларын өз өміріңізде қолдану керек. Өмірге кішкентай пайдалы нәрселер ойлап табу (ең болмаса пакеттерге арналған пакет). Көлік, велосипед, самокат жүргізгені жақсы, жұмысты жол жүрумен, іссапарлармен байланыстысын таңдаған дұрыс, семинар өткізсеңіз, вебинар емес, көшпелі семинар өткізіңіз.\n«Жетінің» теріс көрінісі де бар — айлакерлік, арандатуға бейімділік, біліммен бөліскісі келмеу.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: көлікпен мәселелер (жиі бұзылу), автонесиелермен мәселелер (не бермейді, не төлемдерде қиындық), ұсақ жол-көлік оқиғалары (өлімге әкелмейтін), аяқпен мәселелер, тіпті сал болуға дейін, мансап пен бизнестегі кедергілер.\nНумерологияда 7 — арба (колесница), қозғалыс белгісі. «Жетілер» барлық жасырын, киелі нәрсені жақсы көреді және зияткерлік дамуға ұмтылады.",
  "26": "26 санында Сатурн (8) және Уран (4) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n(4) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жоғары кәсібилік, болжамдылық, тұрақтылық, сенімділік, еңбекқорлық, консерватизм.\nОл үшін міндетті орындауыңыз керек — таңдаған салада кәсіпқой болу. Шала жұмысқа жол берілмейді. Бала кезде сіздің жұмысыңыз — мектептегі оқу, жақсы оқу маңызды.\n«Төрттің» теріс көрінісі де бар — жалқаулық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: әріптестердің сатқындығы, мансаптың күйреуі, басшылықпен мәселелер, мансап сатысымен жоғарылаудағы қиындықтар, астыртын ойындар, тірек-қимыл аппаратымен мәселелер.\nНумерологияда 4 — император, мансап және бизнес белгісі. «Төрттерді» бір нәрсені тез үйрене алуы үшін абсолютті қатаңдықта тәрбиелеу керек. Оларға өте талапшыл болу керек. Тәрбиесі неғұрлым жұмсақ болса, тағдыры соғұрлым күрделі.\n\n(8) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — ғалам заңдарына, тепе-теңдікке, әділдікке жауап беру, соттау құқығына ие болу.\nОл үшін міндетті орындауыңыз керек — тараптарды татуластыруыңыз керек, құқықты зерттеп, дұрыс шешім қабылдауды үйрену, сөзде тұру керек, заң бұзуға болмайды, жанжалдасуға болмайды.\n«Сегіздің» теріс көрінісі де бар — жанжалшылдық (адамдарға бұлай істеуге болмайтынын түсіндіруден шаршағандықтан).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бизнестегі мәселелер, әріптестер тарапынан арандату мен сатқындық, мұндай қызметкердің еңбегін байқамайды, омыртқамен мәселелер, көбіне бел бөлімі, жарықтар (грыжи), омыртқаның сыну қаупі.\nНумерологияда 8 — әділдік, сот төрелігі белгісі. Олардан тамаша заңгерлер шығады, өйткені олар заңдарды санаасты деңгейде біледі. Олар әрқашан жанжалды ортада өмір сүреді, құжаттарды тамаша қолдан жасайды, жиі қос өмір сүреді.",
  "27": "27 санында Марс (9) және Меркурий (5) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n(5) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — кез келген нәрсені кез келген адамға сата білу қабілеті; ғылымдарды зерттеу қабілеті, жылдам ойлау, жеңіл жүкпен саяхаттауды жақсы көру, кез келген адаммен тіл табыса білу.\nОл үшін міндетті орындауыңыз керек — ер адамдарға құрметпен қарау, жақын ортадағы ер адамдарға көмектесу, дұрыс әрі салауатты өмір салтын ұстану (СӨС пен дұрыс тамақтану, спорт), рухани даму, үлгі тұтарлық болу. Жұмыста ер адамдарға жеңілдіктер мен акциялар жасау қолайлы.\n«Бестің» теріс көрінісі де бар — асығыстық, сырттай байыпсыздық, маскүнемдікке бейімділік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: әкемен жанжал, әкенің аурулары, сирек жағдайда — әкенің қайтыс болуы, басшылармен мәселелер, анестезияның артық мөлшері, Квинке ісінуі және демікпе қаупі жоғары.\nНумерологияда 5 — Ұлы Абыз (Верховный Жрец) белгісі. Бұл — барлық сұрақтың жауабын білетін адам. Ол дұрыс тамақтануды ұстанады, өйткені ағзасы улануға бейім. «Бестер» кез келген табиғи емес материалдар мен өнімдерге өте сезімтал. Жиі алкогольге тәуелді болады немесе аз мөлшердегі алкогольден уланып қалуы мүмкін. «Бестерді» әкелері немесе ер адам тәрбиелеуі керек. Тек ер адам ғана олар үшін бедел бола алады. Олар тағдырымен әкесіне байланған. «Бес» әйелдерге онша белсенді емес ер адамдар беріледі.\n\n(9) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — «айқын» деген сөзбен басталатынның бәрі (айқын көру, айқын білу, айқын есту...); астралды қауыммен байланыс (періштелер, архангелдер, жоғары періштелер, қамқоршылар); бақсылық (шаманство), регрессия, экстрасенсорика; дербестік, өзін-өзі жеткілікті сезіну.\nОл үшін міндетті орындауыңыз керек — экстрасенсорлық қабілеттерді дамыту, ешкімге сүйенбей, өзін-өзі жеткілікті, дербес тұлға болу. Аға буынға көмек көрсету керек. Аға буын адамдарына жеңілдіктер немесе акциялар жасау қолайлы. Егер «тоғыз» әлеуметтік игіліктерден өз еркімен бас тартпаса, оны жоғалтулар арқылы кесіп тастайды.\n«Тоғыздың» теріс көрінісі де бар — жалғыздықтан қорқу, өзімшілдік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: оқшаулану, әлеуметтік өлім, ауруханаға жиі түсу.\nНумерологияда 9 — экстрасенсорика, дербестік, аға буын, қызмет ету белгісі.\n«Тоғыздың» санаастында жалғыздықтан қорқу бар. Олар жалғыз қалудан қорыққандықтан серіктесіне сұмдық нәрселерді кешіре алады, бірақ олар дәл жалғыздықта ашылады.\n«Тоғыздар» шын жүректен сүйе алмайды, олар өзін сол немесе басқа жағдайда сүйеді.",
  "28": "28 санында Күн (1) және Венера (6) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n28-де Күннен (көшбасшылықтан) гөрі Венера көбірек.\n(6) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — сыртқы тартымдылық, харизма, сүйкімділік, қонақжайлылық, басқа адамдардың қажеттіліктерін біледі, стиль сезімі бар (жақсы модельер бола алады), қолөнерге талантты, жақындарын алыстан сезеді.\nОл үшін міндетті орындауыңыз керек — ресми некеде болып, отбасы мүшелеріне, ата-анаға және барлық ұрпаққа қамқорлық жасау керек. Отбасылық қарым-қатынаста үлгі, эталон болу, ажырасуға және опасыздық жасауға, тіпті ойша да болмайды.\n«Алтының» теріс көрінісі де бар — қыңырлық (өте қыңыр).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: мүлікті бөлісумен ажырасу, кармалық қарым-қатынас, серіктестердің, соның ішінде іскерлік серіктестердің опасыздығы мен сатқындығы, мәмілелер мен келісімшарттардың бұзылуы, жүрек-қантамыр жүйесінде мәселелер.\nНумерологияда 6 — отбасы, үйдегі қолөнер мен үйдегі шығармашылық, сондай-ақ серіктестік белгісі.\nЕгер сіз опасыздық жасаған адам сізді шын жүректен кешірсе, белгінің теріс көріністері жұмсарады.\n\n(1) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — көшбасшылық, мақсаткерлік, мақсат қойып, оған жете білу, сөзді меңгеру, білім алу және оны беру.\nОл үшін міндетті орындауыңыз керек — бауырларыңызға қамқорлық жасап, оларға кеңес беріп көмектесу, жанжалға жол бермеу. Егер олармен қарым-қатынас бітіспес болса, онда қарым-қатынас бейтарап, арақашықтықта болғаны жақсы. Егер бауырыңыз болмаса — бұл ата-ананың қатесі. Бұл жағдайда бағдарламаны шәкіртіңіз, тағылымдамашыңыз арқылы өңдеуге болады. Сондай-ақ ұстазға және алған білімге құрметпен қарап, үнемі жаңаны үйрену керек.\n«Бірдің» теріс көрінісі де бар — билікқұмарлық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бауырының сатқындығы, олармен жанжал, олардың ауруы. Құжаттарды рәсімдеуде қателер, сөйлеу, есте сақтау, есту қабілетінде мәселелер болуы мүмкін. Адам алаяқтардың құрбаны болуы мүмкін.",
  "29": "29 санында Ай (2) және Нептун (7) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n29-дар 2 сияқты жұмсақ емес, зияткерлік дамуға ұмтылады, айлакер.\n(7) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жылдам ойлау, бәрін терең тану, киелі нәрсені зерттеуді жақсы көреді, карма заңдарын сезеді, себеп-салдарлық байланыстарды (неге солай болатынын) көреді, жағдайды алдын ала болжай алады, бірақ оны өзгерте алмайды, сондықтан өз дарынын жиі қарғыс ретінде қабылдайды. «Жетілер» өте тапқыр.\nОл үшін міндетті орындауыңыз керек — ең болмаса ел ішінде саяхаттап, басқа халықтардың мәдениетін зерттеп, олардың технологияларын өз өміріңізде қолдану керек. Өмірге кішкентай пайдалы нәрселер ойлап табу (ең болмаса пакеттерге арналған пакет). Көлік, велосипед, самокат жүргізгені жақсы, жұмысты жол жүрумен, іссапарлармен байланыстысын таңдаған дұрыс, семинар өткізсеңіз, вебинар емес, көшпелі семинар өткізіңіз.\n«Жетінің» теріс көрінісі де бар — айлакерлік, арандатуға бейімділік, біліммен бөліскісі келмеу.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: көлікпен мәселелер (жиі бұзылу), автонесиелермен мәселелер (не бермейді, не төлемдерде қиындық), ұсақ жол-көлік оқиғалары (өлімге әкелмейтін), аяқпен мәселелер, тіпті сал болуға дейін, мансап пен бизнестегі кедергілер.\nНумерологияда 7 — арба (колесница), қозғалыс белгісі. «Жетілер» барлық жасырын, киелі нәрсені жақсы көреді және зияткерлік дамуға ұмтылады.\n\n(2) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — сезімталдық, қамқорлық, мейірімділік, басқа адамдардың психофизикалық күйін сезіну, емшілік пен тәуіптік дарыны.\nОл үшін міндетті орындауыңыз керек — жақын әйелдерге (ана, әже, қыз) қамқорлық жасау. Бала кезден үй жануарларына күтім жасауға, табиғатты қорғауға ұмтылыңыз.\n«Екінің» теріс көрінісі де бар — өздерін ренжітетін адамдарға деген сезімсіздік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: жақын әйелдердің ауыр аурулары; жүктілікті сақтау мәселелері, түсік; ер адамдарда бедеулік (аспермия, азооспермия); анамен жанжал, әйелдер тарапынан сатқындық, сирек жағдайда — ананың қайтыс болуы; несеп-жыныс жүйесінің аурулары. Жұптың аналары қаламайынша, олардың отбасында бала болмайды.\n«Екілерді» оларға даналықты, жақындарға қамқорлық жасай білуді беру үшін әжелер тәрбиелеуі керек.\nНумерологияда 2 — экология, денсаулық, қамқорлық, мейірім, ана және жалпы әйел белгісі.",
  "30": "30 санында Юпитер (3) және қосымша Сатурн (8) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n(8) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — ғалам заңдарына, тепе-теңдікке, әділдікке жауап беру, соттау құқығына ие болу.\nОл үшін міндетті орындауыңыз керек — тараптарды татуластыруыңыз керек, құқықты зерттеп, дұрыс шешім қабылдауды үйрену, сөзде тұру керек, заң бұзуға болмайды, жанжалдасуға болмайды.\n«Сегіздің» теріс көрінісі де бар — жанжалшылдық (адамдарға бұлай істеуге болмайтынын түсіндіруден шаршағандықтан).\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бизнестегі мәселелер, әріптестер тарапынан арандату мен сатқындық, мұндай қызметкердің еңбегін байқамайды, омыртқамен мәселелер, көбіне бел бөлімі, жарықтар (грыжи), омыртқаның сыну қаупі.\nНумерологияда 8 — әділдік, сот төрелігі белгісі. Олардан тамаша заңгерлер шығады, өйткені олар заңдарды санаасты деңгейде біледі. Олар әрқашан жанжалды ортада өмір сүреді, құжаттарды тамаша қолдан жасайды, жиі қос өмір сүреді.\n\n(3) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жақсы есте сақтау қабілеті, Жердің ментальді өрісінен ақпаратты оқи білу, жақсы оқу қабілеті, кез келген нәрсені үйрене алу, шашыраңқы ақпаратты біріктіру қабілеті, ойды материалдандыру дарыны («Құпия» (Секрет) фильмі).\nОл үшін міндетті орындауыңыз керек — ең болмаса бір баланы (асырап алған болса да) тәрбиелеп, оқытып, оған мансап құруға немесе бизнесті өз перзентіндей өсіруге көмектесу. «Үштер» өздері қаламаса, олардың балалары болмайды.\n«Үштің» теріс көрінісі де бар — дербес болмау, шабыт керек — «сиқырлы түрткі».\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: бала тууға бөгет, жүкті болу мәселелері, ене мен қайын енемен жанжал, балалар тарапынан сатқындық, балалардың ауруы, сәттілік жоқ, нақты құрылған жоспарлар орындалмайды.\n«Үштерді» көбіне аналары тәрбиелеуі керек. Олар үшін әйел — бедел. Олардың аналарымен жиі күрделі қарым-қатынасы болады. Ер адамдар «әйелінің уысындағы» және «анасының еркесі» болып өсуі мүмкін.\nНумерологияда 3 — әкелік пен аналық белгісі.",
  "31": "31 санында Уран (4) және Марс (9) бойынша екі бағдарлама бар. Олар адамның мінезінде әртүрлі дәрежеде көрінуі мүмкін.\n(9) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — «айқын» деген сөзбен басталатынның бәрі (айқын көру, айқын білу, айқын есту...); астралды қауыммен байланыс (періштелер, архангелдер, жоғары періштелер, қамқоршылар); бақсылық (шаманство), регрессия, экстрасенсорика; дербестік, өзін-өзі жеткілікті сезіну.\nОл үшін міндетті орындауыңыз керек — экстрасенсорлық қабілеттерді дамыту, ешкімге сүйенбей, өзін-өзі жеткілікті, дербес тұлға болу. Аға буынға көмек көрсету керек. Аға буын адамдарына жеңілдіктер немесе акциялар жасау қолайлы. Егер «тоғыз» әлеуметтік игіліктерден өз еркімен бас тартпаса, оны жоғалтулар арқылы кесіп тастайды.\n«Тоғыздың» теріс көрінісі де бар — жалғыздықтан қорқу, өзімшілдік.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: оқшаулану, әлеуметтік өлім, ауруханаға жиі түсу.\nНумерологияда 9 — экстрасенсорика, дербестік, аға буын, қызмет ету белгісі.\n«Тоғыздың» санаастында жалғыздықтан қорқу бар. Олар жалғыз қалудан қорыққандықтан серіктесіне сұмдық нәрселерді кешіре алады, бірақ олар дәл жалғыздықта ашылады.\n«Тоғыздар» шын жүректен сүйе алмайды, олар өзін сол немесе басқа жағдайда сүйеді.\n\n(4) Сіз бойыңыздан осы туған күн санына тән жарқын жағымды қасиеттерді ашқыңыз келді — жоғары кәсібилік, болжамдылық, тұрақтылық, сенімділік, еңбекқорлық, консерватизм.\nОл үшін міндетті орындауыңыз керек — таңдаған салада кәсіпқой болу. Шала жұмысқа жол берілмейді. Бала кезде сіздің жұмысыңыз — мектептегі оқу, жақсы оқу маңызды.\n«Төрттің» теріс көрінісі де бар — жалқаулық.\nМіндет орындалмаса, жағымсыз оқиғалар болуы мүмкін: әріптестердің сатқындығы, мансаптың күйреуі, басшылықпен мәселелер, мансап сатысымен жоғарылаудағы қиындықтар, астыртын ойындар, тірек-қимыл аппаратымен мәселелер.\nНумерологияда 4 — император, мансап және бизнес белгісі."
 },
 "opv": {
  "1": "Қате: өткен өмірде сіз бауырыңызға (аға-інің немесе апа-сіңліңізге) сатқындық жасағансыз.\nӨткен өмірде бауырыңызға сатқындық жасау.\nКері әсері (обратка): бұл өмірде бауырыңыз тарапынан опасыздыққа, жанжалдарға және сатқындыққа тап болуыңыз мүмкін. Еске салайық, бұл адамға ренжуге және онымен келіспеушілікке баруға болмайды, бұл жағдайыңызды одан әрі нашарлатады. Егер бауырыңыз болмаса, бағдарлама сізден едәуір жас кез келген адамды таңдауы мүмкін. Ал сатқындықтың түрі сіз үшін ең ауыр болатыны алынады. Сондай-ақ құжаттарды рәсімдеудегі мәселелер, бір нәрсені тіркеуден бекерден-бекер бас тарту, алаяқтық және фактілер мен қолтаңбаларды қолдан жасау осы арканның әсерімен байланысты екенін атап өтеміз. Сіз бұл соққыны тойтаруға емес, қабылдауға әрқашан дайын болуыңыз керек. Бірақ біз карманың салдарын емдегеннен гөрі оның әсерінің алдын алуды ұсынамыз.\nТүзету жолдары: Кез келген көмек пен қолдау көрсету керек. Жанжалға жол берілмейді.",
  "2": "Қате: анаңызға сатқындық жасау, оған жанжалды әрі дөрекі қарау.\nАнаға және аналық сезімге сатқындық жасау.\nКері әсері (обратка): бұл арканның әсерімен анаңызбен жанжал іс жүзінде сөзсіз. Оның сізге қатысты қандай қарым-қатынас пен өзара әрекет түрін таңдайтынына байланысты мазасыздық пен ашу сезінуіңіз мүмкін. Бірақ ұрысуға болмайды, керісінше, ол не істесе де, татуласып, кешірім сұраған жөн. Кез келген жақын әйелдің, соның ішінде қызыңыздың ауыр ауруы да карманың кері әсері болып табылады.\nТүзету жолдары: Ренжімей, анаңызға бәрінде көмектесу маңызды. Жанжалға жол берілмейді.",
  "3": "Қате: өткенде сіз не балалы болудан үзілді-кесілді бас тарттыңыз, не оларды назарсыз және қамқорлықсыз қалдырдыңыз. Яғни ата-аналық қамқорлық міндетін орындай алмадыңыз.\nБалаға сатқындық жасау, балалы болудан немесе оны тәрбиелеуден бас тарту.\nКері әсері (обратка): қазір балалар тақырыбы сіз үшін өте күрделі болады. Бала тууда және жүкті болуда физиологиялық немесе психологиялық қиындықтар болуы мүмкін. Балалардың кез келген жанжалын, келіспеушілігін, сатқындығын кешіру керек. Ал осы өмірде де балалы болғысы келмейтіндер немесе жасы әлі жетпейтіндер арканның басқа көрінісіне тап болады — барлық жобаларды қисынды соңына дейін жеткізуге мүмкіндік бермейді. Олар ең соңғы сәтте тоқтап қалады.\nТүзету жолдары: Өз балаңызды толыққанды тәрбиелеумен жеке айналысу талап етіледі. Жанжалға жол берілмейді.",
  "4": "Қате: өткен өмірде сіз кәсіби міндеттеріңізді дұрыс орындамағансыз және немқұрайлылық трагедияның себебі болуы мүмкін еді, кейде белгі жалқаулық пен арамтамақтықты көрсетеді.\nБасқаның есебінен өмір сүрген немесе жұмысқа адал қарамаған.\nКері әсері (обратка): сізге кәсібилігіңізді дәлелдеу оңай болмайды. Мектепте бағаларды төмендетеді, мұғалімдер ата-аналар жиналысында сізге қарсы шығуы мүмкін. Студент әріптестер мен жұмыстағы әріптестер сізді қуана арандатып, орныңызға таласады. Мансаптық жол соншалықты оңай болмайтынына дайындалуыңыз керек. Серіктестер мен орындаушылардың немқұрайлылығы себебінен бизнес тұрақсыз болады.\nТүзету жолдары: Еңбекқорлықпен жоғары мансаптық өсуге өз бетіңізше жету маңызды.",
  "5": "Қате: әкеге немесе оның әулеттегі тәрбиелік желісіне сатқындық жасау.\nӘкеге және әкелік сезімге сатқындық жасау.\nКері әсері (обратка): әкемен жанжал, өзара ренжістер және оның тарапынан сатқындық сіз үшін қалыпты жағдай болуы мүмкін. Карманың кері әсері өткен өмірдегі қылығыңызға осылай жауап береді. Ер адамдар сізге жеке өмірде де, мансап пен бизнесте де сатқындық жасауы мүмкін. Бастықтарыңыз сізге көмектеспейді, керісінше, олар сізден қорқады. Сізді өздерінің бәсекелесі санайды. Мұқият болыңыз және олармен тым ашық болмаңыз.\nТүзету жолдары: Ренжімей, әкеңізге бәрінде көмектесу маңызды. Жанжалға жол берілмейді.",
  "6": "Қате: жұбайыңызға опасыздық және сатқындық жасау.\nОтбасылық байланыстарға сатқындық, опасыздық, отбасыларды бұзу.\nКері әсері (обратка): жақын адамыңыздың опасыздығына, сондай-ақ тыңдамауына, жанжалдарына және сатқындығына дайын болыңыз. Бұл — белгі әсерінің қалыпты жағдайы. Серіктесіңізге неғұрлым көп күдіктенсеңіз, оның опасыздық жасау қаупі соғұрлым жоғары. Оның сізді ауыртуға деген барлық әрекетін кешіріңіз, өйткені сіз де өткен өмірде дәл солай істегенсіз. Сондай-ақ белгі бақытты әрі үйлесімді қарым-қатынас құруға мүмкіндік бермейді. Жомарттық пен даналық танытқаннан кейін бәрі реттеледі. Сізге беймәлім жанжал себебінен мәмілелер бұзылуы мүмкін.\nТүзету жолдары: Опасыздық пен сатқындықты кешіре отырып, шынайы қарым-қатынас көрсету маңызды.",
  "7": "Қате: сіз басқа адамдардың өздеріне лайықты нәрсеге ие болуына кедергі жасадыңыз. Тағдырларға араласып, оларды бұздыңыз.\nАдамдардың жетістіктеріне кедергі жасау.\nКері әсері (обратка): сізге көлік жүргізгенде өте ұқыпты болып, аяқтарыңызға көбірек көңіл бөлген жөн. Карма әділдікті қалпына келтіруге тырысып, адамға жиі дәл осы жақтан жақындайды. Алайда ол көбіне табысыңызды кенеттен бұғаттайды. Біреу немесе бір нәрсе бекерден-бекер сізді лайықты құқықтарыңыздан айырады. Жағдайды түзетуге тырыспаңыз, оның жай ғана жанынан өту керек.\nТүзету жолдары: Адамдарға және олардың идеяларының жүзеге асуына пайдасыз көмектесу керек.",
  "8": "Қате: сіз заңды өрескел бұздыңыз. Оның үстіне қылығыңыз қасақана болды. Жасап жатқан ісіңіз бостандығыңызға және өміріңізге түсуі мүмкін екенін анық білдіңіз. Жоспарлап, жеке өзіңіз орындадыңыз. Нақты қандай қылмыс екені карманың толық бағдарламасында көрінеді.\nКісі өлтірумен байланысты емес, заңды қасақана бұзу.\nКері әсері (обратка): мұндай адамдарды ата-аналары жиі мұрадан айырады. Олар ұтылысқа моральдық тұрғыдан дайын болуы керек. Сотта және құқық қорғау органдарында сәтсіздіктер. Әділетсіз сотталу және өз ақиқатын дәлелдей алмау. Құқықтық тұзаққа түсу ғана емес, алаяқтық пен алдаудың құрбаны болу қаупі де бар. Бұл белгі дәлелдеуі өте қиын арандатулар береді. Ірі сатып алуларды ойламаған жөн, бәрін жоғалту қаупі бар.\nТүзету жолдары: Заңды сақтау, әділетсіздікті, алаяқтықты, айыппұлдарды кешіру маңызды.",
  "9": "Қате: сіз жақын адамдарыңызды қиындық пен ауру үстінде тастап кеттіңіз, туыстарыңызға қамқорлық жасамадыңыз, оларды жерлемедіңіз.\nТуысын қиындық пен ауру үстінде қасақана тастап кету.\nКері әсері (обратка): сізге жалғыздық сабағынан өтуге тура келеді. Бұл соншалықты қорқынышты емес, бірақ қиын, өйткені адамдарға ренжуге болмайды. Сізді қолдаусыз қалдыруы, тіпті ең жақын адамдарыңыз арқадан пышақ салуы мүмкін. Бірақ бұл, бәлкім, белгінің ең жұмсақ көрінісі, өйткені ол үйіңізге аурулар мен тіпті жоғалтулар әкелуге қабілетті. Сізді өзіңізге қымбат адамдардан мүлдем түрлі жолдармен алыстатқандай болады.\nТүзету жолдары: Әулеттің барлық мүшелеріне көмек көрсету, отбасы мүшелерін жерлеу маңызды.",
  "10": "Қате: қаржылық қылмыстар (ұрлық, тонау, алаяқтық, ысырап ету, күйзелтіп банкрот ету).\nОйластырылған банктік, қаржылық алаяқтық, ұрлық.\nКері әсері (обратка): табысыңызды қолыңызда мықтап ұстаңыз, өйткені арканның сізді тек табыстан ғана емес, жинаған барлық қорыңыздан айыратын күші бар. Аркан ақшаны жақсы көреді және оларды сізден қандай да бір жолмен қуана тартып алады. Оның үстіне оның міндеті тонау емес, көбіне қарыз шұңқырына тарту. Сондықтан күмәнді мәмілелерден, ірі несиелерден сақтанып, қаржылық міндеттемелерге кірмеңіз, салымдар мен тапқан ақшаңызды қорғаңыз.\nТүзету жолдары: Қаржылық міндеттемелерді сақтау, несие алмау, талан-таражды кешіру.",
  "11": "Қате: басқа адамдарға физикалық немесе моральдық зиян келтіру.\nАдамның денсаулығына зиян келтіру, жануарды өлтіру.\nКері әсері (обратка): бұл позициядағы белгі дәрігерлік қателер, сәтсіз диагноздар, қажетсіз операциялар, физикалық денеге қатты зақым, шабуылдар, жарақаттар беруі мүмкін. Ол әрқашан адам үшін ең маңызды нәрсеге — денеге соққы береді. Алайда кейде, адам өте сақ болғанда, басқа қанаттан келіп, жасырын жаулардың шебер жұмысы арқылы мансаптан айыра алады.\nТүзету жолдары: АДАМДАР МЕН ЖАНУАРЛАРҒА медициналық қамқорлық пен күтім көрсету.",
  "12": "Қате: басқа адамдардың сезімдері мен қадір-қасиетін қорлау, оларды депрессияға және өз-өзіне қол жұмсауға итермелеу, моральдық қорлау және дөрекілік.\nАдамдарға тәкаппар, дөрекі әрі ұятсыз қарау, жансыздық.\nКері әсері (обратка): бұл белгі көбіне онкологиялық немесе басқа емделуі қиын ауру береді. Жалпы ол бұл позицияда денсаулыққа жауап береді. Бірақ бұл арканның өзі физиологияны басатындықтан емес, ол ішкі әлемді жарақаттайтындықтан. Бұл — таза күйіндегі психосоматика. Сіз қорладыңыз, демек енді сізді қорлайды. Сіз бастыңыз, демек сізді шектейді. Және тағы басқалар. Карма сізді қарусыздандыру, қалыптан шығару, жақсылап қорқыту үшін қандай тәсілдерді таңдайды? Әрине, денсаулық. Назар аударыңыз, бұл кезеңде қорқыныштарды «айналдырып шығару» (прокрутка страхов) өте пайдалы. Оның ниетін дәлірек анықтай аласыз, ең болмаса депрессияның себебін көрсетесіз. Оны жоя алсаңыз, мәселе өздігінен шешіледі.\nТүзету жолдары: Рақымдылық пен шыдамдылық таныту, дөрекілік пен әдепсіздікті кешіру.",
  "13": "Қате: адамның қасақана, алдын ала ойластырылған өліміне себеп болу, тұрмыстық тілде — кісі өлтіру.\nАдамның өліміне қасақана емес, бірақ кінәлі түрде себеп болу.\nКері әсері (обратка): белгі қауіптің жоғары дәрежесін береді. Карма денсаулығыңызға соққы беріп, тек аурулар ғана емес, апаттар да әкелуі мүмкін. Бірақ бәрібір ол соншалықты түбегейлі әрекет етуге сирек барады. Сондықтан көбіне мансап пен бизнеске соққы береді. Сізді әлеуметтік игіліктерден айырады. Өмірде күрт әрі аса азапты өзгерістер береді. Барынша мұқият болуды және апаттар мен операцияларға жол бергеннен гөрі тым сақ болған дұрыс деп ұсынамыз. Аркан өте күшті және сізді өз қолында мықтап ұстайды. Бірақ өзіңіздің кармалық жазалаушыңызға ренжуге болмайтынын есте сақтаңыз.\nТүзету жолдары: Әрекетке қабілетсіз адамға толық қамқорлық жасау.",
  "14": "Қате: әулет пен адамды кәсіптерден, шеберліктің ерекше құпияларынан және киелі білімнен айыру. Қазір бұл бизнесті қасақана күйрету деп аталады.\nОтбасы бюджетін немесе кәсібін күйрету.\nКері әсері (обратка): баяу күйреу, ақша тез кетпейді, сондықтан қаржылық ырғақтың бұзылғаны сізге бірден көрінбейді. Отбасылық бизнестен шеттету, қарсыластардың астыртын ойындарына байланысты жұмыстан айырылу. Айналаңызда айтылмай қалған көп нәрсе және жасырын жаулар бар. Аркан дамып келе жатқан мәселені көруге мүмкіндік бермейді. Біреу сізге қарсы стратегия ойластырып жүр. Оның үстіне белгі клиенттер ағынының тоқтауы немесе сізге қызметкер ретінде қызығушылықтың төмендеуі себебінен бизнес пен мансапта жиі мәселелер береді. Диагностикадан өтуді ұмытпаңыз, ең жақсысы — тиянақты дәрігерде, өйткені аркан шын мәселені жасырып, дұрыс диагноз қоюға кедергі жасағанды жақсы көреді.\nТүзету жолдары: Отбасыңызды өз бетіңізше қамтамасыз ету, ұрпақтарға табыс көзін қалдыру.",
  "15": "Қате: оккультизмді, қара магияны немесе қылмысты, адамдарға қатыгездікпен әрі қорлаумен жасалған жыныстық және басқа зорлық-зомбылықты қолдану.\nРитуалдық магияны пайдаланып адамдарға зиян келтіру.\nКері әсері (обратка): белгі өте агрессиялы, бірақ Карманың қолында елеулі құрал ретінде сирек шығады. Ол бар нәрсені өршітеді (катализдейді). Жанжалды шарықтау шегіне жеткізеді, аурудың барысын жылдамдатады, бизнесіңізге немесе мансабыңызға араласып, дөңгелекке өте үлкен таяқ сұғады. Онкология қаупі жоғары. Алайда оның негізгі міндеті — сізді эмоцияға шығару, қатты ашуландыру, мазасыздандыру, қорқыту, сіз тарапынан кек пен зорлыққа шақыру. Кері әсер сізге ренжуге себеп бермейтінін әрқашан есте сақтауыңыз керек. Ол өткен өмірдегі қарызды қайтарады.\nТүзету жолдары: Магиямен айналысуға тыйым салынады, адамдарға өмірдегі өз жолын табуға көмектесу маңызды.",
  "16": "Қате: сіз адамды үйінен айырдыңыз, осылайша оған мансап, отбасылық және бақуатты өмір құруға мүмкіндік бермедіңіз.\nАдамды мүлкінен, соның ішінде үйінен қасақана айыру.\nКері әсері (обратка): ең жағымсыз аркандардың бірі. Көбіне ол мүлікті тартып алады немесе тұрғын үй жағдайын нашарлатады. Бұл жақын туысты жоғалтуға қол сұғудан немесе дәрігерге өміріңізге қажетті мүшені алып тастауға жол беруден әлдеқайда жеңіл. Сондай-ақ аркан мансабыңызды, бизнесіңізді, отбасылық өміріңізді бұзуға қабілетті. Жалпы оның өміріңізді күйбеңге айналдыратын күші бар.\nТүзету жолдары: Өз меншігіңіз болмауы, адамдарға оған ие болуға көмектесу маңызды.",
  "17": "Қате: сіз талантты адамға сатқындық жасадыңыз немесе оның шығармашылық және зияткерлік еңбегіне басқаша қызықтыңыз. Бұл оның дамуын тоқтатып, адамзатқа маңызды ақпаратты беруге мүмкіндік бермеді.\nАвторлық құқықты бұзу, талантты адамға сатқындық жасау.\nКері әсері (обратка): тура немесе ауыспалы мағынада биіктен құлау азаптарыңыздың себебі болуы мүмкін. Сізге жобаңызды немесе идеяңызды дамытуға жол бермейді, лайықты лауазымды немесе марапаттарды алуға мүмкіндік бермейді. Сізді бағаламайды, қолдамайды және көмек ұсынбайды. Наразы адамдардың гуілі астында өзіңізді жүзеге асыруға тура келеді. Сонымен қатар идеяларыңызды ұрлап, еңбегіңізді басқа адамдар иемденіп, еңбегіңізді бұрмалап, оған қарама-қарсы мағына беруі мүмкін. Оның үстіне, әсіресе достарыңызбен тым ашық болмаған жөн. Белгі жиі дәл жақын достардың сатқындығын береді.\nТүзету жолдары: Талантты адамдарға жол тартуға көмектесу, олардың құқықтары мен өнертабыстарын қорғау.",
  "18": "Қате: сіз сізге шексіз сенген адамдарды мұрнынан жетектеп, алдап, олармен ойнадыңыз.\nОтбасылық қарым-қатынастағы пайдакүнемдік, айлакерлік.\nКері әсері (обратка): сізге шындықты айтады деп үміттенбеңіз. Өтірік — қарсыластар ғана емес, жақын адамдар да пайдаланатын жалғыз құрал болады. Аркан үйіңіздегі жайлылық пен ыңғайлылыққа да әсер етеді, тек тұрмыс қана емес, отбасындағы атмосфера да кез келген сәтте шиеленісуі мүмкін. Мүмкін, опасыздықты, іскерлік серіктестердің, достардың сатқындығын кешіруге тура келеді. Жаланың, айыптаудың, өсектің, астыртын әрекеттердің ортасында қалуыңыз мүмкін. Оның үстіне белгі отбасыңыздың барлық мүшелерімен жанжал береді. Оларға сізге қарсы жасаған кез келген теріс қылығын кешіріңіз.\nТүзету жолдары: Жақындарды сатқындықтан сақтап, қорғау, алдамау және айлакерлік жасамау.",
  "19": "Қате: сіз қоғамдағы орныңызды, сізге көрсетілген сенімді жеке пайдакүнемдік мақсатта пайдаландыңыз. Әрқашан қол жетпейтін болып қалу үшін адамдарды басқардыңыз (манипуляция жасадыңыз).\nБилікті теріс пайдалану, лауазымдық қылмыстар.\nКері әсері (обратка): бұл аркан билік, мемлекеттік органдар, сондай-ақ бастықтар мен қоғамдағы шені мен орны жоғары адамдар арқылы әрекет еткенді өте жақсы көреді. Мәртебесі бар адамдардан гөрі тағылымдамашыларға сүйенгеніңіз әлдеқайда сенімді. Сізге жоғары лауазымға жетуге жол бермейді, ал жіберсе де, арандатудан сақтаныңыз. Аркан беделге қатты соққы беріп, адамды болашақтағы перспективалардан айырады.\nТүзету жолдары: Қамқорлық көрсету, адамдарға мансаптық өсуде көмектесу.",
  "20": "Қате: әулетке (Родқа) сатқындық жасау. Бұл тізім өте үлкен, ол тек идеологиялық, мәдени, ұлттық, діни ғана емес, нәсілдік мәселелерді де қамтиды.\nӘулеттің дәстүрлері мен мүдделеріне сатқындық, беделін түсіру.\nКері әсері (обратка): туыстарыңыздан соққыларға дайын болыңыз. Бұл олардан келетін жаман хабарлар ғана емес, сатқындық та. Әулеттің кез келген мүшесі сізді жаралауға құқылы, бірақ сіз ренжуге және жанжалдасуға құқығыңыз жоқ екенін есте сақтауыңыз керек.\nТүзету жолдары: Әулеттің барлық мүшелеріне көмектесу, қаржылай қолдау көрсету.",
  "21": "Қате: Отанға сатқындық жасау. Мұнда тізіп шығу да уақытыңызды тым көп алады. Әркім бүкіл елге не зиян келтіруі мүмкін екенін біледі.\nОтанның дәстүрлеріне, тұтастығы мен негіздеріне сатқындық жасау.\nКері әсері (обратка): өміріңізді Отанмен байланыстырған жөн, өйткені шетелде сізді көңіл қалу мен трагедиялар күтеді. Сіз вирустық ауруларға, сондай-ақ паразиттер жұқтыруға тым бейімсіз. Өте сирек аурулар, судьялардың сіздің пайдаңызға емес стандартты емес шешімдері, ешқашан болмаған жерде күтпеген кедергілер. Бұл арканда Карманың ниетін ешнәрсе болжай алмайды, өйткені ол ешкімге ешқашан істемегендей әрекет етеді. Шетелдіктермен мәмілелерден сақтаныңыз.\nТүзету жолдары: Елді дәріптеу, оның шекарасын қорғау және азаматтарға көмектесу маңызды.",
  "22": "Қате: әулет ұрпақтарының өліміне қасақана себеп болу, соның ішінде түсік жасату.\nТүсік жасату немесе түсік жасатуға мәжбүрлеу, балаларға зорлық-зомбылық.\nКері әсері (обратка): сізді мәселелер шеңберіне қояды. Бәрі бірден үйіліп түседі, бірақ соған қарамастан, жеңіске сенімді жоғалтпасаңыз, оңай еңсересіз. Аркан бұрын сипатталған кез келген белгінің көріністерінің жиынтығын береді. Карма құрал ретінде нақты нені және қандай көлемде қолданатынын болжау өте оңай емес, сондықтан өзіңіз үшін бір ережені қабылдаған дұрыс — ешқашан ештеңеге ренжімеу.\nТүзету жолдары: Кез келген балаларға көмектесу, олардың сатқындығын кешіру. 3-тен көп баланың болуы."
 },
 "name": {
  "1": "Өмірді танып, өз тәжірибеңіз бен біліміңізбен қарым-қатынас арқылы бөлісу.",
  "2": "Түйсікті дамыту, жанашырлық, төзімділік, мейірім мен қамқорлық таныту.",
  "3": "Жаратушы болу. Балалы болып, оларға аяғынан тұруға көмектесу, өмірдегі барлық жолды ашу. Немесе өз идеяларыңызды өмірге енгізу.",
  "4": "Өмірдің қандай да бір саласында кәсіпқой болу.",
  "5": "Рухани даму, түрлі елдерге саяхаттау, басқа халықтардың түрлі мәдениеттері мен дәстүрлерін зерттеу.",
  "6": "Жеке қарым-қатынаста шынайы махаббат сезімінің, тазалықтың, үйлесімнің иесі болу.",
  "7": "Көп саяхаттау, басқа мәдениеттерді зерттеу, өмір салтыңызға жаңа бір нәрсе енгізу. Өз үлгіңізбен адамдарды белсенді әрі прогрессивті өмір салтына үйрету.",
  "8": "Тепе-теңдік пен ішкі үйлесімді сақтауды үйрену. Заңдылықты, әділдікті, ар-намыс пен қадір-қасиетті қорғауда тұру.",
  "9": "Әулетіңіздің дәстүрлеріне сәйкес рухани даму, жасы үлкен адамдармен араласу, көне мәдениеттерді, әулетіңіздің, мемлекеттің тарихын зерттеу.",
  "10": "Ақшаға дұрыс көзқарас қалыптастыру.",
  "11": "Эмоциялар мен сезімдерді басқарып, оларды жағымды жасампаз арнаға бағыттай білу. Бойыңызда ерлік, батылдық, қаһармандық сияқты сезімдерді дамыту.",
  "12": "Адамдарды тыңдауды, естуді, түсінуді, ақтауды үйрену.",
  "13": "Ешкім ешқашан жасамаған нәрсені ойлап табу, жасау, жаратып шығару.",
  "14": "Тек отбасыңыздың игілігіне ұмтыла отырып, үйлесімді әрі қанағатшыл өмір салтын ұстану керек. Өз қолыңызбен немесе ақылыңызбен бір нәрсе жасауды үйрену, сонда өмірдегі барлық жол сізге ашылады.",
  "15": "Сіз адамдарды толқытып, оларды эмоциялар мен сезімдерге оятуыңыз керек.",
  "16": "Адамдардың стереотиптерін бұзу, жаңа құндылықтар жүйесін құру. Жаңа есіктерді ашуды үйренуіңіз керек.",
  "17": "Таланттарыңызды, артистизміңізді дамыту, өзін-өзі көрсету, креативтілік, әсемдікті сезіну үстінде жұмыс істеу.",
  "18": "Айналаңызда үйлесім, жайлылық, ыңғайлылық, стиль мен сұлулық жасау.",
  "19": "Қоғамда жоғары мәртебе мен орынға жету (ауқымы маңызды емес), өз ортаңызда дана, сенімді әрі әділ көшбасшы болу.",
  "20": "Әулеттің дәстүрлері мен негіздерін қорғау, әулеттің барлық мүшелеріне материалдық та, рухани да игіліктерге ие болуға көмектесу.",
  "21": "Адамдардың дүниетанымын кеңейту. Бойыңызда төзімділік, жаңаның бәріне ашықтық сияқты қасиеттерді қалыптастыру.",
  "22": "Ашық, достық пейілді, баладай аңғал адам, сенімді дос, жақындарыңыз үшін тірек болу."
 },
 "zk": {
  "1": "• Сөзді ауызша да, жазбаша да шебер меңгеру.\n• Сөзбен адамдардың жан пернелерін қозғай білу.\n• Ақпаратты өңдеу және беру, коммуникация.\n• Ақпаратты адамдарға жеткізу, дана кеңестермен көмектесу және сөз арқылы үйлесім мен сұлулық жасау.\n• Жастармен өзара әрекеттесу.\n• Бауырларға, көршілерге және құрдастарға көмек.\n• Білім, оқу.\n• Жаңаны меңгеру, оны көпшілікке бейімдеу.\n• «Ешкім жүрмеген жолдармен» жүру, басқаларды соңыңнан ерту.",
  "2": "• Экология, психология, эзотерика, нәзік энергиялар.\n• Медицина, тәуіптік, шөппен емдеу.\n• Жаратылыстану ғылымдары, табиғатпен және жануарлармен өзара әрекеттесу.\n• Киелі білім, оқу және білім беру.\n• Бай ішкі әлем, қиял, түйсік.\n• Талдау, диагностика, ақпараттың үлкен ағындары.\n• Аналық, анамен, әйелдермен қарым-қатынас.\n• Адамдарға өздерінің «жол көрсетер жұлдызын» табуға көмектесу.\n• Қорқыныштарды жеңу, құпияларды ашу.",
  "3": "• Балалық шақ, аналық, жүктілік, бала тууы, өсіп келе жатқан ұрпақты тәрбиелеу, ата-аналық рөлді орындау.\n• Ең жақсы ана/әке және мінсіз әйел/күйеу болу.\n• Үйді абаттандыру, қолөнер, өнер мен шығармашылық.\n• Шығармашылық жобаларға, шағын бизнеске басшылық ету.\n• Отбасына, ұжымға, әлсіздердің қауіпсіздігіне қамқорлық.\n• Үйлесім мен сұлулық кеңістігі, мәдениет пен өнер.\n• Ер адамдарда — өзі үшін өмір сүріп, жұмыс істейтін, ерлік жасайтын және онымен тату-тәтті өмір сүретін әйелді таңдау.",
  "4": "• Рухани ояну, адамдарға нұр жеткізу.\n• Жоспарлардың айқындығы, тұрақтылық.\n• Жауапкершілік пен кәсібилік.\n• Жоғары буын басшысы, басқару, билік.\n• Келісе білу, адамдар мен ақпаратты біріктіру қабілеті.\n• Өз әулетіңізді негіздеу.\n• Әйелдерде — әйелдік энергияға ауысу, күйеуін құрметтеу, онымен келісімде өмір сүру, үлкен үйдің немесе жобаның иесі болу.\n• Шығармашылық арқылы үлкен бизнеске шығу.",
  "5": "• Рухани тәлімгерлік, қамқорлық, әкелік.\n• Отбасын құру және нығайту, отбасылық дәстүрлерді сақтау.\n• Балаларды оқыту және тәрбиелеу.\n• Ақпарат пен қызметті құрылымдау.\n• Қоғамдық қызмет.\n• Тәжірибе — білім берудің себебі.\n• Заңдарды сақтау.\n• Дін, тарих, философия, ғылыми эзотерика.\n• Ғылыми зерттеулер, халықтар тарихы мен олардың салт-дәстүрлері.",
  "6": "• Рухани ақпаратты құрылымдау.\n• Үй ошағы, жайлылық, отбасылық қарым-қатынас.\n• Отбасы, қарым-қатынас мәселелері бойынша сәтті кеңес беру.\n• Махаббат пен игілікте өмір сүру.\n• Үйлесімді ұжым құру.\n• Әсем заттарды жасау, жинау.\n• Үйді, киімді сәндеу.\n• Жанжалдарды дипломатиялық жолмен шешу.",
  "7": "• Саяхаттар, қозғалыс, белсенділік, спорт, әскери іс.\n• Көлік жүргізу, транспорт, құрастыру.\n• Зерттеу қызметі, өнертапқыштық, бизнес, саясат.\n• Байланыстар мен орын ауыстырулардың көптігі.\n• Балаларыңызға жақсы балалық шақ жасау, баланың өмірін үйлесімге, түсіністікке, махаббатқа толтыру, оған рухани құндылықтар беру.\n• Әулет ақпаратын тазарту, әулеттің жақсы естелігін сақтау.\n• Қызмет етудегі көшбасшылық, үлгі болу.\n• Интернет кеңістігінде жүзеге асу.\n• Ақпаратты дауыстап жеткізу, ұжымның мақсаттарына жету.",
  "8": "• Үйлесім, тепе-теңдік күйі, әділдік.\n• Дұрыс мінез-құлық пен қылықтар, адамдар мен жануарлардың құқықтарын қорғау.\n• Энергиялардың тазалығына, ойдың тазалығына ішкі сенім.\n• Ойдың кең ауқымы, дипломатия мен даналық, мұқияттылық.\n• Басқалардың әрекетіне жаһандық түрде араласпау, бәрін ақпараттық тұрғыда бір-бірімен байланыстыратын, кеңес беретін орган болу.\n• Жоғары игі тәрбие, жақсы білім, ұқыптылық.\n• Отбасыңызды алға жылжыту үшін байланыстар құру.\n• Мерекелер мен демалысты ұйымдастыру, құжаттармен жұмыс.",
  "9": "• Өзін оқшаулау, оңашалық, өз еркімен жалғыздық, тақуалық (отшельничество).\n• Даналығыңыз бен тәжірибеңізді айналадағы әлемге жеткізу, кеңес беру.\n• Әркім бір-біріне кедергі жасамай, өз бетімен дами алатын игі кеңістік жасау.\n• Руханилықты қылықтар арқылы бағалау.\n• Қызмет етудегі пайдакүнемсіздік, үлкендерге, қарттарға, жалғызбастыларға көмек.\n• Терең білім, тарихты зерттеу, дәстүрлерді сақтау.\n• Эзотерика, философия, ғылым, көне мәдениеттер мен дәстүрлер.\n• Әлеуметтік жұмыс, еріктілік.",
  "10": "• Ерекше шығармашылық қызмет, Кармамен жұмыс.\n• Қаржылық тәуелсіздік, өзіңізді және жақындарыңызды материалдық қамтамасыз ету, адамдарға қаржылай көмек, қайырымдылық.\n• Өмірден рахат алу, босаңсыған болу.\n• Белгілі бір сәтте қай жерде болу керегін сезіну.\n• Күшті дұрыс бөлу, оларды керекті арнаға бағыттау.\n• Отбасыңыз үшін тұмар, табыс символы болу.\n• Тұтасты бөліктерге бөлу.\n• Адамдарға көмек, кеңес беру, «Тағдыр жөніндегі маман» болу.\n• Жаһандық әлеуметтік жобалар.\n• Банк құрылымдары, бизнес, қаржы.",
  "11": "• Әскери немесе мемлекеттік қызмет, күш құрылымдары.\n• Күштің ішкі шоғырлануы, осы энергияның көзі бола білу.\n• Денемен жұмыс, массаж, фитнес, спорт, йога.\n• Өз табиғатыңызды, күшіңізді, сексуалдылығыңызды асыл түрде көрсету.\n• Әйелге — ішкі агрессияны ер адамды қылықтар, ерліктер жасауға, өмір биіктеріне жетуге шабыттандыратын әйелдікке айналдыру.\n• Төңкеріс пен серпіліс, басқаларды соңынан ерткен көшбасшы.\n• Жаңа Эгрегор құру.\n• Данышпандықты ашу.",
  "12": "• Ғылым, психология, философия, өнер, эзотерика, астрология, нумерология.\n• Жағдайды түрлі жағынан бағалау, көп қырлы көзқарас.\n• Қайта ойлауға арналған сынақ, дағдарысты саналы түрде жасау және бағытты өзгерту.\n• Адамдарға қызмет етуді миссия ретінде қабылдау, жобаны әлеуметтік қажеттіліктерге бағыттау.\n• Жобаларды жаңарту, жасау және жіберу.\n• Музыка мен белгілердің үйлесімі, медиумдық мүмкіндіктер, әлемнің, музыканың, адам жанының сұлулығын нәзік сезіну қабілеті.\n• Белгілі бір аралықпен бала дүниеге әкелу.\n• Мақсатқа жету үшін бір нәрсені құрбан ету, үлкен нәрсе үшін кішкентайды құрбан ету және сонымен бірге құрбан позициясынан шығу.",
  "13": "• Балама көзқарас, жаңа жолдар салу, ғылым, өнер, эзотерика саласындағы төңкеріс, барлық қажетсіз нәрседен тазару.\n• Кеңістікті, жағдайларды, адамдар арасындағы өзара әрекеттесуді күшейту және трансформациялау, тұйық жағдайда ұжымның назарын ауыстыру.\n• Әлсіреген эгрегорды бұзу немесе нығайту.\n• Реанимация, қалпына келтіру (реставрация), экстремалды жағдайларда көмек.\n• Жаңару ретіндегі қоштасу, кенеттен өзгерістер.\n• Өзіңе адал болу.\n• Экстремалды салаларда жұмыс.\n• Ақпаратты құрылымдау, шәкірттерге білім беру.",
  "14": "• Табиғат, гүл өсіру, ауыл шаруашылығы, селекция.\n• Қолөнер, негізінен атадан балаға мұра болған.\n• Жануарларға қамқорлық, ветеринария.\n• Үйлесімді қарым-қатынас, ішкі мен сыртқының тепе-теңдігі.\n• Кез келген жағдайда «алтын ортаны» табу.\n• Ымыраға келе білу, бұған басқаларға да көмектесу.\n• Басқалар үшін жақсы жол көрсетуші және адамдарды біріктіріп, таныстыру үшін олардың арасындағы дәнекер болу.\n• Бітімгершілік, әлеуметтік жұмыс, құпия қызметтер.\n• Емшілік, медицина, фармацевтика.",
  "15": "• Ішкі эмоционалдылық, құмарлық, сексуалдылық, сүйкімділік (шарм).\n• Харизма, актерлік қабілеттер, шығармашылық.\n• Адамдар мен жағдайға ықпал ету, кеңістікті басқару.\n• Өз энергияңызды бақылап, оны дұрыс бөлу.\n• Түрлі азғырулар мен тәуелділіктерден арылу.\n• Қылмыс әлемін айналып өтіп, қара магиядан аулақ болу.\n• Емшілік, эзотерика, оккультизм, экстрасенсорика, магия.\n• Рухани көшбасшылық, тәлімгерлік, басқа адамдарға көмек.\n• Бизнес, шоу-бизнес, сахна.\n• Танымалдылық.",
  "16": "• Жаңаны салу және жасау.\n• Рухани көшбасшылық, адамдардың дүниетанымын қалыптастыру.\n• Нәзік жоспарлардың ақпаратын әлемге жеткізу.\n• Жеке өмір кеңістігін қайта ұйымдастыру.\n• Бұзылғанның орнына жаңа әлем құру, қажетсізді алып тастау, ескі бағдарламалардан тазару.\n• Жағымды аскетизм, мойынсұну арқылы ішкі өсу.\n• Медитация мен дұға.\n• Үй, жылжымайтын мүлік, үй-жайлардың дизайны мен жөндеуі.\n• Үй шаруасы, шаруашылық, аспаздық.",
  "17": "• Шығармашылық, артистік, көркемдік, музыкалық және басқа талант.\n• Кез келген іске креативті тәсіл, әсемдікті сезіну қабілеті, романтизм, шабыт.\n• Әсем заттар жасау, шығармашылық жобалар.\n• Әлемді сұлулыққа толтыру: музыкалық шығармаларда, көркем кенептерде немесе үйді сәндеуде.\n• Жақсы дос болу, достық өмірде маңызды орын алады.\n• Өнер, қолданбалы эзотерика, астрология, нумерология.\n• Әскер, мәртебелі лауазым, регалиялар, жұлдыздар.",
  "18": "• Үй, отбасы ошағы, әулет ұясы.\n• Жайлылық жасау, тамақ дайындау, үйдегі, тұрмыстағы, киімдегі жайлылық.\n• Адам жанын тану, қарым-қатынастағы жылулық пен шынайылық.\n• Айналадағыларды әлеммен және адамдармен жағымды қарым-қатынас құруға үйрету.\n• Балаларды мифтер мен ертегілер арқылы тәрбиелеу, отбасы мен ұжымда ерекше, әсем-жұмбақ, сиқырлы атмосфера жасау.\n• Психология, белгі жүйелерінің барлық түрлері, бейнелер жасау.\n• Өзін-өзі тануға арналған шығармашылық.\n• Әйелдік пен ерліктің тепе-теңдігі, ата-ана мен жақындарға құрмет.\n• Қорқыныштармен жұмыс, шынайы болу, өтірік пен алдаудан, опасыздықтан аулақ болу.",
  "19": "• Көшбасшылық, басшылық, ақылды басқару, билік.\n• Жоғары мәртебе, мансаптық өсу, болашақтылық.\n• Ірі жобаларды, өндірістерді, бизнесті ұйымдастыру.\n• Басты болып, басқа адамдарға көмектесу, соңыңнан ерту.\n• Жылыту, көмектесу, сенім ұялату, оптимизммен қуаттандыру.\n• Эгоцентризмсіз және өзін кемсітусіз дұрыс өзін-өзі бағалау.\n• Асылдық, мейірім, адалдық, соңынан ерте білу.\n• Ой мен қылықтағы дербестік, бөтен пікірге тәуелсіздік.\n• Саясат, басшылық жұмыс, шығармашылық.",
  "20": "• Әулеттік қарым-қатынас, жақын және алыс туыстарға қамқорлық.\n• Отбасында үйлесімді қарым-қатынас құру және қолдау.\n• Өз әулетіңіздің тарихын білу, оны ұрпаққа жеткізу.\n• Әулеттік ақпаратты тазарту, әулеттің энергия көзі мен қолдауын алу, дәстүрлер мен қағидаларды қайта жаңғырту.\n• Жаһандық процестерге, саяси құрылымға, мәдениетке, дінге ықпал ету.\n• Өз құндылықтар жүйесін құру.\n• Тарих, отбасылық психология, отбасылық медицина, сот-құқықтық жүйе, саясат.",
  "21": "• Шет мемлекеттер, саяхаттар, интернет кеңістігі.\n• Жаңаның, ерекшенің, «шетелдіктің» бәріне ашықтық.\n• Түрлі халықтарға, нәсілдерге, халықтың әлеуметтік топтарына төзімділік пен бейтарап қарау.\n• Отанға деген махаббат пен құрмет, дипломатия, бітімгершілік.\n• Айналаңызда үйлесімді кеңістік, тыныштық жасау.\n• Шетелдіктермен өзара әрекеттесу, түрлі мәдениеттегі адамдарды біріктіру, «теңіз асқан» дәстүрлер мен шет тілдерін үйрену, жаңалықтарды өмірге енгізу.\n• Түрлі халықтардың дәстүрлері мен мәдениеті, заманауи технологиялар.",
  "22": "• Балаларға қамқорлық, балалық тікелейлікті сақтау, мейірім.\n• Нәтижеге материалдық байланыссыз жұмыс.\n• Саяхаттар, шоу-бизнес, ойын-сауық.\n• Идея беру, басқалардың өміріне қуаныш, әзіл әкелу.\n• Кез келген көзқарасты қабылдау, таңдау еркіндігі.\n• Жеңілдік, бұғаудың болмауы, еркіндік, өмірмен ойнау.\n• Жаһандық мақсаттар, жағдайдан, шындықтан жоғары көтерілу.\n• Әлемде жоғалған бір нәрсені қайта жасау.\n• Шығармашылық көрініс.\n• Достық, көптеген достық байланыстар, достық қарым-қатынас."
 },
 "tp": {
  "1": "Сіздің таланттарыңыз: Кез келген адаммен тіл табыса білу. Ақпаратқа ғылыми тәсіл. Дамыған интеллект. Көпшілік алдында сөйлей білу. Тамаша мұғалім, дәріскер.\nСізге БЛОК кедергі жасайды: Бауырыңызға ренжу және онымен келіспеушілік, тіл табыса алмау, бауырыңыздың алдындағы шамадан тыс жауапкершілік пен қамқорлық сезімі, оқып, білімін жетілдіргісі келмеу, ұстазға немесе тәлімгерге деген жақтырмаушылық.",
  "2": "Сіздің таланттарыңыз: Емшілік. Басқа адамдардың психофизикалық және эмоционалдық күйін сезіну. Түйсік, жануарларды түсіну. Шөптерді ажырата білу.\nСізге БЛОК кедергі жасайды: Анаға және жалпы барлық әйелдерге ренжу. Әйелдердің қыңырлығын, әлсіздігін елемеу, жанжалшылдық пен дөрекілік. Адам әйелді оның өмірін бәрінде жеңілдетуге міндетті деп санайды.",
  "3": "Сіздің таланттарыңыз: Балаларды тәрбиелей білу. Ойларды материалдандыру («Құпия» (Секрет) фильмі). Жақсы кәсіпкерлер, бірақ оларға жұп (серіктес құрылтайшылар, достар) керек. Таланттар, шығармашылық.\nСізге БЛОК кедергі жасайды: Балалы болғысы келмеу немесе оларды тәрбиелеуге дұрыс қарамау. Шамадан тыс қамқорлық, бақылау немесе керісінше, тәрбиеден барынша шеттегісі келу. Өз тілектері мен мақсаттары баланың қажеттіліктерінен жоғары, ал баланың өзі тек қалыптасқан тұлға туралы стереотиптің заты.",
  "4": "Сіздің таланттарыңыз: Жоқтан бизнес құра білу. Бәрінде кәсіпқой, оған қажетті тәжірибе мен дағдылар беріледі. Тамаша басшылар, қатал, бірақ әділ.\nСізге БЛОК кедергі жасайды: Кәсіби әл-ауқатқа қойылатын асыра талаптар. Жоқ мінсіз жағдайлар қалыптасқанша жұмысқа шығудан қорқу. Басқаның есебінен өмір сүруге, басқаның табыстары мен жетістіктерін пайдалануға деген ықылас.",
  "5": "Сіздің таланттарыңыз: Даналық, руханилық. Басқа адамдардың арнауын көре білу, олардың қажеттіліктерін оқу. Сөзбен емдеу. Не жақсы, не жаман екенін түсіну.\nСізге БЛОК кедергі жасайды: Әкеге, жалпы ер адамдарға санаасты ренжіс. Ер адамға сенуден қорқу, ер адамдардың жетістіктері мен табыстарын жоққа шығару, дөрекілік пен ұстамсыздық. Өзін ер адамдардың арасында бірегей деп мойындау немесе әйелдің барлық ер адамдарды елемеуі.",
  "6": "Сіздің таланттарыңыз: Отбасын, қарым-қатынаста үйлесім құра білу. Жақындарды алыстан сезіну. Қолөнер, қонақжайлылық, үйдегі барлық кәсіпті меңгеру. Қарым-қатынасқа ашықтық, күлімсіреу. Адамдар оларды әрқашан мейіріммен қабылдайды.\nСізге БЛОК кедергі жасайды: Өзін отбасылық өмір байланысымен байланыстырғысы келмеу, жақындарға дұрыс қарамау, өз қыңырлығын қанағаттандыруға деген өткір қажеттілік, ымыраға келгісі, бейімделгісі келмеу.",
  "7": "Сіздің таланттарыңыз: Толқынның қырын сезе білу, яғни керекті сәтте және керекті уақытта көру, тез шешім қабылдау. Көптеген нұсқаның ішінен ең сәттісін таңдау. Жылдам ойлау. Бейтаныс адаммен сәтті диалог құру дарыны.\nСізге БЛОК кедергі жасайды: Қолдау, қамқорлық, шабыттандырушы болу қажеттілігі, дербестік пен жауапкершіліктен қорқу. Болашақ пен мүмкіндіктерді көре алмау, адам бастағанын жарты жолда тастайды.",
  "8": "Сіздің таланттарыңыз: Кез келген заңдарды, қағидаларды, негіздерді білу. Әділдік, өлшем сезімі. Эмоцияларды басқара білу. Жанжалда салқын, екі бағытта ойлайды. Әрқашан «Б» жоспары бар. Құжаттарды бәрінен жақсы қолдан жасайды.\nСізге БЛОК кедергі жасайды: Заңға дұрыс қарамау. Не құқықтық тазалыққа шамадан тыс талапшылдық, регламентпен өмір сүруге деген ықылас, бұл ызыңсыздық пен икемсіздік болып көрінуі мүмкін, не керісінше алаяқтыққа және тәуекелге бейімділік.",
  "9": "Сіздің таланттарыңыз: Эзотерикалық таланттар, «айқын...» дегеннің барлық түрлері (айқын көру, айқын есту, айқын түсіну...). Абсолютті өзін-өзі жеткілікті, тәуелсіз, кез келген нәрсені жалғыз жасай алады. Жоғарғы күштердің көмегі.\nСізге БЛОК кедергі жасайды: Жалғыздықтан қорқу, достық пен махаббатқа дұрыс қарамау, бопсалау мен эмоция алуға деген өзімшіл қажеттілік түрінде көрінетін серіктестіктегі жалған құрбандық.",
  "10": "Сіздің таланттарыңыз: Ауадан ақша жасай білу. Бизнесті қалай көбейту, дамыту керегін сезіну. Кез келген істегі болашақ.\nСізге БЛОК кедергі жасайды: Кедейліктен қорқу, ақшаға дұрыс қарамау. Не сараңдық пен «неміс прагматизмі» түрінде, не керісінше тез баюға, жеңіл әрі заңсыз ақшаға деген ықылас түрінде көрінеді.",
  "11": "Сіздің таланттарыңыз: Қарсыластың әлсіз жақтарын көреді. Тіпті шарасыз жағдайларда да жеңе білу. Басқа адамдардың эмоцияларын басқара білу. Жауларды және олардың жоспарларын алдын ала тани алады. Әсіресе сыни жағдайларда (шкафты жалғыз жылжыту) ғажайып күшке ие. Төзімділік пен ақылдың салқындығы.\nСізге БЛОК кедергі жасайды: Бәсекелестіктен, қысымнан қорқу, өз күшіне сенімсіздік. Мұндай адамдар жиі күреске кірмей беріліп қалады, ал қорғанғанда әдетте өте өткір, агрессиялы болады, аффектілі мінез-құлыққа бейім.",
  "12": "Сіздің таланттарыңыз: Психологтар. Басқа адамдардың эмоцияларын сезеді. Лайықты сөздер таба білу. Қарым-қатынасқа ашықтық. Басқа адамдардың арнауын білу.\nСізге БЛОК кедергі жасайды: Санаасты ұят сезімі, өз білімі мен эмоцияларын көпшілік алдында көрсетуден қорқу. Адам депрессия мен ренжіске оңай түседі, салыстырудан қорқады, оңашалық пен тұйықтықты қалайды.",
  "13": "Сіздің таланттарыңыз: Көбірек көреді, көлемдірек түсінеді. Баламаларды көреді. Кез келген жағдайдан шығар жол табады. Ерекше (эксклюзивті) нәрсені көру. «А» жоспары мен «Б» жоспары бар. Гипноз дарыны. Басқа адамды қайта бағдарламалау қабілеті. Оған өз еркін таңу.\nСізге БЛОК кедергі жасайды: Өлімнен, жазадан, тағдыр (рок), карма, ауыр ауру, сынақтардан санаасты қорқу. Мұндай адамдар өзгерістерден қорқады, өйткені оларды сұмдық белгі деп санайды, шамадан тыс күдікшіл әрі сезімтал.",
  "14": "Сіздің таланттарыңыз: Кез келген динамикалық жағдайды тыныштандыра білу. Жасушалардың регенерациясына бейімділік. Емшілік дарыны. Тамаша селекционерлер. Өсімдіктердің жаңа сорттарын шығара алады. Жануарлар оларды қатты жақсы көреді (ветеринария).\nСізге БЛОК кедергі жасайды: Көптеген көрінісі бар сараңдық: білімге, эмоцияларға, ақшаға, даңққа, әсерлерге, махаббатқа. Адам өз ережелеріне бағынбауға өткір әсер етеді, жоспарланбаған нәрсенің бәрінен қорқады.",
  "15": "Сіздің таланттарыңыз: Айқын көру және басқа экстрасенсорлық қабілеттер, соның ішінде магиялық қорғаныс. Қалағанының бәрі, тіпті басқа адамдарға зиян келтірсе де, орындалады. Ақылға сыймайтын харизма. Тамаша әзіл сезімі. Ұйымдастырушылық қабілеттер.\nСізге БЛОК кедергі жасайды: Азғырулардың барлық түріне бейімділік, соның ішінде алкоголь, есірткі, компьютерлік ойындар, ерте есею, магия, оккультизм. Тәуелділіктің кез келген түрі, соның ішінде атаққұмарлық, қызғаныш, қылықтарының салдары туралы ойланбайды.",
  "16": "Сіздің таланттарыңыз: Ешқандай құралсыз кез келген нәрсені нөлден сала білу. Іске іргелі тәсіл. Тез шешімдер. Болашаққа жоспар құра білу. Алдын ала көру.\nСізге БЛОК кедергі жасайды: Адам өткенмен өмір сүруге үйренеді, жаңа өмірге есік ашудан, оған өзгерістер енгізуден, мүмкіндіктер мен сәттерді пайдаланудан қорқады. Ескіде қалғанды қалайды, қоштасуды, жоғалту мен айырылуды ауыр өткереді.",
  "17": "Сіздің таланттарыңыз: Шығармашылықтың барлық түрлері, сезімдердің романтикалығы. Түстердің, иістердің, дыбыстардың кеңірек ауқымы. Кез келген идеяны, арманды, міндетті іліп алып, жүзеге асыра білу. Даңқ пен табыс алу қабілеті.\nСізге БЛОК кедергі жасайды: Өз мүмкіндіктеріне, таланттарына, шеберлігіне, сұлулығына, интеллектісіне және қабілеттеріне сенімсіздік. Адам өзін, сондай-ақ ойларын, сезімдері мен эмоцияларын білдіре алмайды, сондықтан дөрекі болып көрінеді, өз ерекшеліктерінен ұялады.",
  "18": "Сіздің таланттарыңыз: Үйдегі қолөнердің барлық түрлері. Адамның стиль, сұлулық сезімі бар. Үйлеспейтінді үйлестіреді. Кез келген нәрсені өзгерте алады. Өтірікті сезеді. Өздері шебер өтірік айтады. Түс көру дарыны. Олардың қолында орасан зор жасампаз энергия бар. Сұлулық жарата алу қабілеті.\nСізге БЛОК кедергі жасайды: Кешіре, жағдайды жібере, сене алмау. Өтірік пен сатқындыққа ауыр қарау. Санаасты осалдық пен ұяңдық. Жағдайды бекерден-бекер шарықтау шегіне дейін ушықтыра білу.",
  "19": "Сіздің таланттарыңыз: Мансап жасау қабілеті. Бәрінде сәтті, рухы мен еркі мықты. Сымбатты, келбетті. Әлеуметтік тұрғыда орташа деңгейден жоғары көрінеді.\nСізге БЛОК кедергі жасайды: Санаасты қорқыныштар мен фобиялардың жиынтығы, өзін білмеу. Толыққанды еместік кешені. Көбіне мұның бәрі тек дүрбелеңге бейімділікті көрсетеді.",
  "20": "Сіздің таланттарыңыз: Әулеттің барлық таланттары (ана мен әке жағынан).\nСізге БЛОК кедергі жасайды: Отбасылық дәстүрлерге, әулет мүшелеріне жиіркене қарау, аға буынның кеңестерін ұстанғысы, туыстарының кәсіптері мен мамандықтарын жалғастырғысы келмеу, өз мүдделерін бәрінен жоғары жариялау, әулеттен бас тарту.",
  "21": "Сіздің таланттарыңыз: Қажылық (зиярат). Адамдарды, басқа халықтарды түйсікпен түсіну. Бейнелі ойлау. Кез келген жағдайға бейімделе білу. Жаңашылдық.\nСізге БЛОК кедергі жасайды: Саяхаттан, ұшақпен ұшудан қорқу, шетелдік қауымдастықты, мәдениетті, ережелерді, заңдарды жақтырмау. Күдікшіл патриотизм, икемділік пен төзімділіктің болмауы және басқа ұлттар мен халықтарды құрметтемеу. Бұл адамға шетелде тұруға кедергі жасамайды, бірақ шиеленіс тудырады.",
  "22": "Сіздің таланттарыңыз: Қарым-қатынасқа ашықтық. Жеңілдік, достық пейіл. Адам жағымды әрі сүйкімді. Бірнеше істі бір мезгілде атқара алады. Ең кемі — бәрінің екіден болуы. Көп қырлылық.\nСізге БЛОК кедергі жасайды: Есеюге дұрыс қарамау, балалықтан немесе керісінше қартаюдан қорқу, қыңырлыққа, ойланбаушылыққа бейімділік. Мұндай адамдар жасына сай өмір сүрмейді, көбіне аңғалдау, сенгіштеу болады."
 },
 "tpChel": {
  "1": "Жасөспірімдік кезеңге байланысты мәселелер, бауырлармен (туған және немере), құрдастармен (адамның жасына қарамастан) күрделі қарым-қатынас туралы, сондай-ақ өзін қабылдау және қоғамдағы өз орнын табу мәселелері туралы айтады. Көбіне адамның пісіп-жетілмегенін немесе жалпы инфантильді мінез-құлқын көрсетеді. Егер 1-позициядан картаға Императрица (әйелдерге қатысты) немесе Император (ер адамдарға қатысты) әсер етсе, бұл адамда өзінің жынысын сәйкестендіруде мәселелер болуы мүмкін екенінің белгісі болады. Нақты тұжырым құрудағы, өз көзқарастарын таныстырудағы мәселелерді немесе көпшілік алдында сөйлеуден қорқуды көрсетуі мүмкін.",
  "2": "Анамен қарым-қатынаста туындайтын мәселелер, оның адам психикасына бұзушы ықпалы туралы хабарлайды. Бұл авторитарлы ана болуы мүмкін, бірақ баланы тәрбиелеудің орнына оны еркелеткен тым көнгіш ана да болуы мүмкін. Көптеген мәдениеттерде ата-ананы құрметтеу — баланың негізгі міндеті. Христиандарда тіпті «Әке-шешеңді құрметте» деген өсиет бар (Зап. 5.16). Алайда 21-ғасырда өмір сүретін адамдардың анасымен қарым-қатынасында жиі көп мәселе болады. Бір жағынан, біз мәдени және діни дәстүрлерді ұстану қажеттілігін сезінеміз, ал екінші жағынан, ананың баласын тәрбиелеу кезеңінде жіберетін қателерінің саны жылдам өсіп келеді. Нәресте, кішкентай бала, тіпті жасөспірім де анасымен қарым-қатынаста тәуелді. Егер олардың арасындағы қарым-қатынас проблемалы болса, кінәні жиі дәл бала өз мойнына алады. Оның ойына анасын бір нәрсеге кінәлау келмейді де. Балалар пайдасыз сүйеді, сондықтан ересектер келтіретін ренжістерді соғұрлым ауыр қабылдайды. Қосымша карта табиғатпен байланыстың жетіспеуі, биологиялық ырғақтың бұзылуы және мұғалімдердің, тәрбиешілердің немесе адамның кәсібіне қатысы бар басқа әйелдердің ықпалынан туған блоктар туралы хабарлауы мүмкін.",
  "3": "Бұл арканды, келесісі сияқты, әйелдер үшін және ер адамдар үшін бөлек түсіндірген жөн. Егер әйелдің кармалық картасын талдасақ, ол әйелдікке байланысты мәселелерді, дәлірек айтқанда оны елемеуді немесе керісінше өз сыртқы келбетіне шамадан тыс назар аударуды көрсетеді. Мүмкін, әйел өзін өмір ойынында киюге болатын басқа рөлдерді ескермей, тек көңілдес немесе ана рөлінде ғана қабылдайды. Ер адамдарға келсек, олардың жағдайында карта мінездің шамадан тыс әйелшелігі, өзінің жыныстық тиесілігін сәйкестендіруге байланысты мәселелер, тіпті кастрация кешені туралы айтады. Жиі жай ғана әйелдермен қарым-қатынастағы мәселелерді, олардың ер адамда тудыратын қорқынышын көрсетеді. Екі жынысқа да қатысты карта сұлулықты қабылдай алмауды, ұсқынсыз нәрсенің бәріне тартылуды білдіруі мүмкін.",
  "4": "Бұл аркан (алдыңғысы сияқты) ер адамдар мен әйелдер үшін бөлек түсіндіріледі. Ер адамдардың кармалық кестесі жағдайында ол өз ерлігін елемеуді немесе дөрекілік пен брутальдық одан нағыз ер адам жасайды деп сенетін «мачо» түрін білдіреді. Әйелдерге келсек, аркан мінездегі шамадан тыс еркектікті немесе жұптағы қарым-қатынасқа әсер етуі мүмкін жыныстық сипаттағы мәселелерді көрсетеді. Карта жиі қарсы жыныс өкілдерімен қарым-қатынастағы мәселелерді де көрсетеді. Екі жынысқа да қатысты карта билікке, басқа адамдарды басқаруға (манипуляция жасауға) және бақылауға деген ықыласқа байланысты мәселелер туралы белгі береді. Жиі бұл адамның табиғатынан жұмысқұмар екенін көрсетеді.",
  "5": "Әкемен өткендегі де, қазіргі де қарым-қатынастағы мәселелер, оның адамға бұзушы ықпалы туралы хабарлайды. Жиі адамның жалған пайғамбарлар мен «гуруларға» бейім екенін де айтады, яғни алдында еліктейтін нысан, бедел болу қажеттілігі бар — өкінішке қарай, кезінде әкесі бола алмаған нәрсе. Дәл сондықтан адам түрлі «ұстаздар» мен секта жетекшілерінің ықпалына оңай түседі. Оқуға қатысты мәселелерді, қажетті білімнің болмауынан туған кешендерді немесе керісінше — жақсы білім беретін құндылықтарды қабылдамауды көрсетуі мүмкін.",
  "6": "Ең алдымен, дұрыс серіктестік қарым-қатынас құруға байланысты мәселелер, бұзушы қарым-қатынасты жалғастыру, қажытатын құмарлыққа бейімділік туралы айтады. Көпшілігіміз берік қарым-қатынас құрып, өмірдің қиын сәттерінде тірек пен қолдау табатын серіктесті кездестіруді армандаймыз. Яғни соның арқасында өзіңді сүйікті сезінетін адамды табуды. Дәл сондықтан өмірдің бұл бөлігі адамдарға ең көп мәселе әкеліп, ауыртады. «Ғашықтар» (Влюблённые) адамның не өзі сау қарым-қатынас құра алмайтынын, не санаастында онымен бастапқыдан сау қарым-қатынас құра алмайтын серіктесті іздейтінін көрсетеді. Сонымен қатар аркан бұл адамның шешімсіз, екіұдай және өз таңдауын жасай алмайтынын көрсетуі мүмкін.",
  "7": "Табысқа жетуден, белгілі, танымал болудан, мойындалудан қорқуды, ал екінші жағынан — басына мініп алуға болатын адамды көрсетеді. Мұндай тұлға кінә сезімінсіз «жоқ» немесе солай жауап беруге мәжбүрлегені үшін ашусыз «иә» дей алмайды. Бүгінгі күні көптеген адам табысқа жете алар еді, бірақ ішкі қорқыныштары мұны істеуге мүмкіндік бермей, оларды жарты жолда тоқтатады немесе жолдың ең басында өзіне және өз табысына деген сенімін бұзады.",
  "8": "Өзін тұлға ретінде қабылдаудағы мәселелер туралы айтады, адамның кінә сезіміне толы екені және өзін-өзі сынауға бейім екені туралы ақпарат береді. Кейбір жағдайларда күнәлар үшін, әдетте нақты жасағандары емес, өзі ойлап шығарғандары үшін жазадан қорқуды көрсетуі мүмкін. Көбіне адам өзіне деген мұндай көзқарасты өмір бойы қалыптастырады. Мұндай мәселелердің пайда болуының жиі себебі — бала кезде адамға үйде де, мектепте де, негізінен дін сабақтарында қолданылған тәрбие әдістері, онда Жаратушының сүйіспеншілігі туралы айтудың орнына оқушыларды тозақ отымен қорқытады. Мұндай мәселелерді талдау адамның қай жағдайда жасамаған күнәлары үшін кінә сезінетінін, ал қай жағдайда уайымы толығымен орынды екенін ажырату тұрғысынан ерекше күрделі, өйткені әрқайсымыз жіберген қателеріміз үшін бір кездері кінә сезімін бастан кешірдік.",
  "9": "Ең алдымен, жалғыздықтан қорқу немесе жалғыз ештеңе істей алмаймын деген қорқыныш, адамның өзін тағдырдың құрбаны сезінетініне сенімділік туралы белгі береді. Қосымша өзін және өз білімін төмен бағалауға байланысты кешендер туралы хабарлайды. Адам өзін басқалардан, негізінен жақын ортасындағылардан ақымақпын деп санайды. Бұл аркан белгі беретін мәселелер адамның руханилығына, оның үлкендерге қатынасына және алған тәжірибесін пайдалана алмауына да қатысты болуы мүмкін, бұл тұлғаның өзін-өзі бағалауын одан әрі нашарлатады.",
  "10": "Қауіпсіздік сезімінің жетіспеуі және материалдық тұрақсыздық туралы белгі береді. Құмар ойындарға бейімділікті білдіруі мүмкін. Қосымша кармалық ауыртпалықтарды көрсетуі мүмкін. Барлығымыз материалдық сипаттағы мәселелерге тап боламыз. Дегенмен ол бар болса, бұл адамның ақшаға қатысты «алтын ортаны» таба алмайтыны туралы ақпарат: не олардан қорқады, не оларды есінен танып аңсайды. Кармалық кестесінде Бақ Дөңгелегі (Колесо Фортуны) бар адам материалдық пен рухани арасындағы тепе-теңдікті таба алмайды. Бұл позициядағы Бақ Дөңгелегіне 1., 5. немесе 6. позициялардан XXII карта әсер еткенде жағдай ушығады (мұндай әсер ақшаға байланысты мәселелер ата-ана үйінен әкелінгенін және мұндай мәселелерді кейін пайда болғандарға қарағанда өңдеу қиынырақ екенін білдіреді).",
  "11": "Адамға өзіне және өз күшіне сенім жетіспейтінінің белгісі, әлсіздік пен аурулардан қорқу туралы айтады. Өкінішке қарай, бұл арканның жалғыз мағынасы емес, ол адамның зорлық-зомбылықтың, агрессияның құрбаны болғанын немесе болып жүргенін де көрсетуі мүмкін. Мұндай мәселелердің саны азаюдың орнына жыл сайын көбейіп келеді, ал оларға тап болғандар немесе тап болып жүргендер өздерін қорғап, көмек іздеудің орнына, керісінше, бақытсыздықтарын жасырып, санаастына тығып, тіпті агрессорлардың өздеріне қатысты осындай әрекеттерін ақтауға тырысады. Жиі бұл аркан адамның бала кезінде зорлық-зомбылыққа ұшырауы мүмкін екенін еске салады, адам мұны мойындаудан қорқады, өйткені өмірдің мұндай кезеңін мүлдем ұмытқан ата-анаң немесе қамқоршыларың бала кезден саған қатыгез қарағанын өзіңе мойындағаннан оңайырақ. Қосымша карта адамның өз денесі мен оның күйін қадағалағысы келмейтінінің белгісі болуы мүмкін.",
  "12": "Адамның эмоционалдық тұрақтылығының жоқтығы, оның өз ішіне кетуге бейімділігі туралы хабарлайды, сондай-ақ талданатын адамның сана күйін өзгертетін стимуляторларды (алкоголь, есірткі, психотроптық препараттар) қолдануға бейім екенінің белгісі болуы мүмкін. Карта жиі адамның улы ұят деп аталатын сезімді бастан кешіретінін, яғни өзіне ешқандай қатысы жоқ нәрсе үшін кінә сезінетінін айтады (мысалы, маскүнемнің әйелі мас күйеуінің қылықтарынан ұялып, оның бұзықтығын ата-анасы мен таныстарынан жасырады). Шекті жағдайларда күшті эмоционалдық бұзылыс туралы айтуы мүмкін.",
  "13": "Көбіне өз өмірі үшін жауапкершілік алудан қорқу, оған қандай да бір өзгерістер енгізуден қорқу, қартайудан және өлімнен қорқу сияқты мәселелер туралы айтады. Айтпақшы, бұл бір қарағанда көрінгендей сирек мәселелер емес. Біз жастықтың табиғи емес жолмен жасалған культі заманында өмір сүріп жатырмыз. Бұл туралы бір әжімнен тұтас трагедия жасайтын түрлі жарнамалар шексіз айтып жатады. Экраннан көрсетілетін, тек жас көрінетін актерлер ойнайтын көркем фильмдер, болашақ қызметкер мүмкіндігінше жас болуы басты шарт болып табылатын жұмысқа қабылдау хабарландырулары. Бүгін жасқа қарай алынған тәжірибе, дәл кемелденген адамдардың артықшылығы болып табылатын өмірлік даналық бағаланбайды. Әрқайсысы тағдырдың тауқыметімен жарыста жеңгенімді еске салатын әжімдерімнен де, өмірлік тәжірибемнің бар екенінің кепілі болып табылатын жасымнан да мен жеке өзім ұялмасам да, көп адамда бұл мәселе бар.",
  "14": "Өмірде «алтын ортаны» табудағы мәселелер, өлшем сезімінің және ішкі мен сыртқы мазмұн арасындағы үйлесімнің жоқтығы туралы айтады. Адамның жауапсыздыққа және тоқырауға бейім екенін хабарлайды, атап айтқанда: бір нәрсе қолға алғысы келсе де, бәрібір оған бағыт көрсетіп, не істеу керегін айтқанша, ал одан да жақсысы — жұмысты ол үшін орындағанша күтеді. Мұндай адам жиі ғажайып күтеді және өмірінде бір нәрсе өзгере ме, әлде сол күйі сұрғылт болып қала ма — тек өзіне байланысты екенін түсінгісі келмейді. Адамның өз пікірі жоқ екенін, көршілер, таныстар не айтса, соны ұстанатынын айтуы мүмкін, бұл өзін жүзеге асыру процесін едәуір қиындатады.",
  "15": "Бұл аркан өте бұзушы және өңдеуге қиын мәселелерді көрсетеді. Жыныстық қысыммен (домогательство), зорлық-зомбылықпен байланысты ренжістер туралы, сондай-ақ секталар мен қылмыстық топтардың ықпалына бейімділік туралы, адамның қара магиямен айналысуы мүмкін екені туралы хабарлайды. Күшті жыныстық тәуелділікті, бұл саладағы бұрмалаулар мен ауытқуларға бейімділікті немесе керісінше өмірдің бұл бөлігінен толық бас тартуға, артық ұқыптылыққа, өтірікке, жалған ұятқа бейімділікті көрсетуі мүмкін, бұл серіктестердің жақын өміріне әсер етуі мүмкін. Мұндай мәселелерді психологтар мен сексологтардың көмегінсіз жеңу өте қиын. Мұндай мәселелері бар адаммен тек карталар арқылы жұмыс істеуге болса да, клиентпен байланыс орнату қиын болар еді, өйткені бізде мұндай тақырыптағы әңгімелер әлі күнге дейін қоғамда қабылданған болып саналмайды және орынсыз әзіл деңгейінде қалады. Жұмсағырақ мағынада аркан адамның өз энергиясын дұрыс қолдана алмайтынын айтуы мүмкін: не оны бекер жұмсайды, не мүлдем дерлік пайдаланбайды.",
  "16": "Депрессияларға, жүйке бұзылыстары мен невроздарға бейімділікті көрсетеді. Мұндай жағдайда адамға клиникалық емдеу курсынан өтуге кеңес берген дұрыс. Сонымен қатар адамның бастағанын соңына дейін жеткізе алмайтынын және өткенге өзіне әсер етуге жол беретінін айтады. Көпшілігіміз жағымсыз естеліктерді, бастан кешкен жан жарақаттарын ұмыта алмаймыз. Бір нәрсе шықпаса, ауыр балалық шақпен, бізге жаман адамдардың ықпал еткенімен ақталамыз, тағдырға, өмір жағдайына шағымданамыз немесе бар кінәні бізді қуалаған сәтсіздікке артамыз. Аркан сондай-ақ адамның өзіне бағыттаған, өз істерінің бұзылуына әкелетін бейсаналы бұзушы әрекеттерін көрсетуі мүмкін.",
  "17": "Адамның сезімдер саласында мәселелері бар екенін, оларды, әсіресе «жаман» деп есептелетіндерін (ашу, ыза, жек көру және т.б.) ашық білдіруден қорқатынын хабарлайды. Қосымша адамның бұғатталған креативтілігі, махаббат, достық, жанашырлық сияқты сезімдерге ұятсыз (циникалық) қарауы туралы айтады. Адам осы бағыттардағы қажеттіліктерін білдіре алмайды. Сол немесе басқа жағдайда не сезінетінін түсіндіре алмайтын, ал қабылдаған барлық шешімдері немесе әрекеттері не сәтсіздікке ұшырайтын, не соңына дейін жеткізілмейтін мұндай адамдарды кездестіру оңай. Бұл жиі мұндай шешімдер шынайы қажеттіліктерді көрсетпей, керісінше, адамға шынымен керек болған нәрсе емес болғандықтан, мұң тудыратындықтан болады. Бұғатталған креативтілік, өз кезегінде, адамға таланттарын толық көрсетуге мүмкіндік бермейді. Оларды көпшілік алдында көрсету мүмкіндігі жоқ.",
  "18": "Иллюзиялар мен қиялдар әлемінде өмір сүруге бейімділік, нақты әлемнен едәуір немесе толық қол үзу, шындықпен және өз санаастымен байланыстың жетіспеуі туралы, сондай-ақ адамның өз психикасы мен ондағы процестер туралы ештеңе білмейтіні туралы айтады. Адамның өмірде өзін жоғалтқанының, онымен не болып жатқанын білмейтінінің, өз реакцияларын түсінбейтінінің дәлелі болуы мүмкін. Ай (Луна) сондай-ақ жоғары эмоционалдық сезімталдық пен эмпатияны көрсетеді, бұл адамның тек өз мәселелері үшін ғана емес, болып жатқан нәрсеге ешқандай қатысы болмаса да, басқа адамдардың мәселелері үшін де терең уайымдауына әкеледі. Кейде керісінше жағдай да кездеседі: адам өзінің қайталанбас екеніне сенімді болып, тек өзі туралы ойлайды, сондықтан жанашырлыққа мүлдем қабілетсіз, бірақ бұл көбіне ер адамдарға қатысты. Әйелдер жағдайында жүкті болуға (зачатие), жүктілікке немесе босануға байланысты қорқыныштар мен блоктар туралы айтуы мүмкін.",
  "19": "Төмен өзін-өзі бағалауды және өзін-өзі құрметтеу сезімінің жоқтығын көрсетеді. Күлкілі көрінуден қорқу, басқа адамдардың өзі туралы пікіріне тәуелділік туралы айтады. Өз артықшылықтарын қоғамға көрсетуді қиындататын блоктар туралы хабарлайды. Кармалық кестесінде Күн (Солнце) бар адам өзіне және өз күшіне сенбейді, қандай да бір бастамаларының мәнін, жиі тіпті өмірдің мәнін оңай жоғалтады. Нәтижесінде толық көңіл қалуға және ішкі бостыққа жетуі мүмкін. Мұндай адам кез келген нәрсеге қуанады, ешқандай ұмтылысы жоқ, ал өзін сәтсіз және табиғаттың қатесі деп санайды. Дегенмен керісінше жағдай да мүмкін: қарапайым адам ешқандай ескертуді қабылдамайтын көшбасшы сияқты әрекет етеді, ал оны сынауға батылы барғандарды жауы ретінде қабылдайды.",
  "20": "Шамадан тыс жауапкершілік, ерекше құндылықтар иерархиясы (дінге немесе өмір философиясына консервативті көзқарас) салдарынан пайда болған блоктар туралы айтады. Отбасына немесе шыққан тегіне байланысты кешендер туралы хабарлайды. Адамның өзі үшін жасаған құндылықтар жүйесі оның көзқарастарына, өмірге тәсіліне және жеке таңдауына әсер ететіні баршаға белгілі. Кармалық кестесінде Сот (Суд) арканы бар адам жиі ата-ана үйінен «алып шыққан» құндылықтар жүйесін ұстанады, оның қазіргі жағдайға сай келмеуі мүмкін екенін ұмытады. Сондай-ақ нәтижесіне қарамастан, өзінің барлық әрекетін игі мақсаттармен, бәрі «жоғары игілік» үшін жасалғандай етіп түсіндіруге және негіздеуге бейімділік туралы айтуы мүмкін.",
  "21": "Ең алдымен, түрлі фобиялар (мысалы, клаустрофобия), невроздар, қажытатын мінез-құлық (мысалы, шамадан тыс артық тамақтану немесе сатып алуға әлсіздік) туралы хабарлайды. Жұмсағырақ түрде өмір сүруден қорқу және адамның бәрін өзі еңсере ала ма деген мазасыздығы туралы айтады. Жиі шетелге шығудан және шетелдіктермен араласудан қорқуды, шетелдік нәрсенің бәрін қабылдамауды көрсетеді. Адам заманауи техниканы түсінбейтіндіктен одан қорқатынын, компьютерді, интернетті, ұялы телефонды пайдаланбауға тырысатынын айтатыны да болады. Егер үлкен адамдардың мінез-құлқында бұл түсінікті болса, жастарға бұл өмір мен мансаптық өсуді едәуір қиындатады.",
  "22": "Ерте балалық шақта (туғаннан 7-8 жасқа дейін) болған мәселелерді, сондай-ақ туған сәт пен мектепте оқуды бастау аралығында бастан кешкен оқиғаларды көрсетеді. Бұл жиі біз есімізде жоқ жағдайларға қатысты, ал кармалық кесте санаастында терең көмілген түрлі мәселелерді көлеңкеден шығаруға мүмкіндік береді. Аркан сондай-ақ әрқайсымыздың ішімізде өмір сүретін ішкі баланы (жасымыз 0 болсын, 60 болсын) және оның мәселелерін жиі елемейтінімізді көрсетеді, өйткені анда-санда бізге өз қажеттіліктері туралы айтуға тырысатын нәзік әрі дәрменсіз дауысқа құлақ салуға уақыт таппаймыз. Осыған байланысты аркан өзін еркін көрсетудегі мәселелер, көңіл көтере білудің жеткіліксіздігі, оғаш және тіпті қауіпті ойын-сауыққа бейімділік туралы хабарлауы мүмкін."
 },
 "ku1": {
  "1": "Егер туған бауырлары болса — бауырларына қатысты әбігер. Оларды бірлескен бизнеске алуға болмайды, олар сәтсіздіктің себебі болуы мүмкін. Немесе (бауыры болмаса) адам — семинарларға құмар, өсекші. Пайдасыз ақпаратқа көп күш пен уақыт жұмсайды. Соның ішінде компьютерлік технологияларға, әлеуметтік желілерге тәуелділік. Ойынқұмарлық. Адам өз біліміне сенімсіз.",
  "2": "Диеталарға, денсаулыққа, процедураларға тұйықталу. Адам стилистерге көп ақша жұмсайды және денсаулығын қатты тәуекелге тігеді. Осылайша өзін анорексияға және психикалық ауытқуларға жеткізуге болады.",
  "3": "Балаларға немесе олардың жоқтығына қатысты әбігер. Мұндай ата-аналар өте мазалағыш (навязчивые).",
  "4": "Жұмысқұмарлық. Адам жұмыстан шықпайды. Тіпті демалыста да тапсырмалармен отырады. Алайда жұмыста тек әрекет еркіндігін бағалайды, ешкімге бағынбайды.",
  "5": "Рухани жолды, Ұстазды іздеу. Сектанттыққа, соның ішінде дінге өте бейім.",
  "6": "Отбасына тәуелділік. Мұндай адамдар опасыздық жасамайды.",
  "7": "Адам саяхатқа, жаңа әсерлер мен таныстықтарға тәуелді. Бүкіл уақыты мен ақшасын соларға жұмсайды. Ер адамдарда көлікке тәуелділік.",
  "8": "Бизнеске, мәмілелерге тұйықталу. Жиналыстарды жақсы көреді. Сотқа беруді, өз ақиқатын дәлелдеуді жақсы көреді. «Әр қазанның қақпағы». Тамаша кадр мамандары, кемеңгер бухгалтерлер (ұрламайды), жауапты заңгерлер.",
  "9": "Жалғызбасты адамдар. Тыныштықты жақсы көреді, жалғыз қалу үшін жиі жанжал тудырады. Кейбіреулерінде эзотерикалық білімге тәуелділік ретінде жұмыс істейді. Эзотерикалық қабілеттері жоқ.",
  "10": "Қаржылық әл-ауқатқа тәуелді адамдар. Пайдакүнем емес! Бірақ қарызға бермейді. «Ондықтарға» өмір сүру ауыр.",
  "11": "Жағымсыздықтарды, кедергілерді, бәсекелестікті жақсы көреді. Жауларын жақсы көреді. Әңгімеде тек сыни тақырыптарды қозғайды немесе спортқа тәуелді. Рухы ең мықты адамдар! Оларды тағдыр да, адамдар да сындыра алмайды.",
  "12": "Құрбан адамдар. Аяушылықты, ауруларды, әлсіздіктерді жақсы көреді. Қоғамдық пікірге тәуелді. Емделмейтін тәуелділіктер.",
  "13": "Экстримге, өткір сезімдерге тәуелділік. Өліммен ойнайды. Өткір эмоциялардан рахат алады, сол үшін жанжалдасады.",
  "14": "«Батпақ». Бір нәрсені өзгертуден қорқады, өмірде тұрақтылыққа ұмтылады. «Қолдағы торғай аспандағы тырнадан артық». Мұндай ер адамдармен іс тындыру қиын.",
  "15": "Тәуелділіктер мен әдеттердің барлық түрлері, міндетті түрде жаман емес. Соның ішінде жыныстық тәуелділіктер. Опасыздыққа бейім. Өзіне бәрін рұқсат етеді. Аналарға кеңес: қатаң тәрбие, әсіресе 15 жаста. Ұстап қалсаңыз — жағымсыздыққа кетуге жол бермейсіз. Алкоголь мен есірткі ағзаға зиян келтірмейді.",
  "16": "Өз баспанасына тәуелділік. Жалға алу емес. Баспанасыз қалудан қорқады. Өткен өмірден келген қорқыныш.",
  "17": "Ақылға сыймайтын талантты адамдар! Бірақ «үстелге» жазады. Жұмыстарын жасырады. Немесе даңқ пен көпшілік алдында болуға тәуелді, бірақ мүлдем дарынсыз адамдар.",
  "18": "«Диван адамдары». Үйді, жайлылықты, өз мысығын жақсы көреді... Мейрамхана тамағы мен қонақүй жайлылығын қабылдамайды. Қонақтар мен әңгімені жақсы көреді.",
  "19": "Мәртебеге, билікке, орынға тәуелділік. Мықты манипуляторлар. Не «патша», не «кілемше».",
  "20": "Әулетке, Отанға, халыққа күшті эмоционалды байланыс. Бұл адамдар — өз әулетінің орталығы.",
  "21": "Брендтерге, сәнді киімге, жаңа технологияларға тәуелділік. Сәнге тәуелділік.",
  "22": "Достарға тәуелділік. Кешіруге деген керемет қабілет."
 },
 "ku2": {
  "1": "Өткен өмірде адам маңызды ақпаратты жеткізбеген, шындықты ашпаған немесе адамға жала жапқан, маңызды сөздерді айтпаған, бір нәрсе туралы ескертпеген. Қазір сөйлеп тоймайды. Регрессте аса құнды ақпаратты еске түсіреді.",
  "2": "Адам өткен өмірде анасынан қамқорлық пен еркелік көрмеген. Оның болмауынан азап шеккен. Қазір ананың махаббатына лайық болу үшін көп нәрсені құрбан етуге дайын. Бірақ жан ешқалай тоя алмай, бақытты сезіне алмайды. Ананы жоғалту туралы қайталанатын түстер болуы мүмкін.",
  "3": "Адам өткен өмірде әкелік/аналық сезімді бастан кешпеген. Ол үйленбеуге ант берген (туған күн картасында 1, 3, 7, 9, 2, 6 оқшауланған сандары болса) немесе адам балаларынан айырылған — тартып алған/қайтыс болған (оқшауланған сандарсыз). Бұл ауыр тақырып, әсіресе қазір балалары болмаса.",
  "4": "Адам өткен өмірде әлеуметтік жағдайына байланысты кәсіби дағдыларын аша алмаған. Ақымақ бастыққа бағынған. «Қызмет етуге қуанар едім, жағымпаздануға жиіркенемін». Қазір барлық нәрседе керемет кәсіпқой.",
  "5": "Адам әкесінің қолдауының болмауынан зардап шегеді. Өткен өмірде әкесі оны езген немесе әкесімен мүлдем байланысы болмаған. Қазір әкемен қарым-қатынас — ауыр тақырып. Әйелдер ер адамдарға тым құрбандыққа бейім болып, серіктестікке үйленген немесе жасы үлкен ер адамдарды таңдауы мүмкін.",
  "6": "Өткен өмірде адамның жауапсыз махаббаты немесе есеппен құрылған некесі болған. Ол өзара махаббат сезімінен рахат ала алмаған. Қазір қанша махаббат алса да, адам бақытсыз, бірақ өзі сүйе біледі.",
  "7": "Адам өткен өмірде бір аумаққа қамалған (шетке шыға алмаған). Ол саяхатты аңсаған, түрмеде отырмаса да, өзін түрмедегідей сезінген. Қазір шеңберді, ережелерді, міндеттерді жек көреді. Сирек үйленеді/тұрмысқа шығады. Серіктесі еркіндікті сүйетін болса, бұл қадамға баруы мүмкін. Басқа елге виза болуы үшін жиі шетелдіктерге үйленеді. Еркін кестесі, таңдау еркіндігі және іссапарлары бар жұмысты таңдайды.",
  "8": "Өткен өмірде бұл адамдар әділетсіз сотталып, әділетсіз жазаға тартылған. Олар кінәсіздігін дәлелдей алмаған. Қазір көбіне адвокат немесе полицей кәсібін таңдайды. Әділдіктің салтанат құрғанын қалайды. Ең алдымен — ар-намыс пен қадір-қасиет!",
  "9": "Адам өткен өмірде жетім болған. Оны жерлейтін ешкім болмаған. Қазір бұл мәселеге алдын ала қамқорлық жасайды. «Мені туған жерге жерлеңдер» деген «пунктик» болуы мүмкін. Қазір жалғыз қалмау үшін кімге болса да, не болса да кешіруге дайын. Жоғалтуларды ерекше ауыр қабылдайды. Жиі жетім болып туады немесе ата-анасына қызықсыз болады. Бұл өмірде жалғыздық қорқынышын жеңуі керек.",
  "10": "Адам өткен өмірде бай болып туған, бірақ толығымен күйреген. Бұл оның ақымақтығымен байланысты болған (бәсекеде ұтылған, тонап кеткен). Сондықтан қазір ақшаны тәуекелге тікпей, қаржылық тәуелсіздігін сақтауға ұмтылады. Мұндай адам бизнесте серіктес ретінде жақсы, өйткені ақша туралы әулеттік білімі бар.",
  "11": "Адам өткен өмірде азаптауды, зорлық-зомбылықты бастан кешіп, психологиялық емес сұмдық ауырсынуды сезінген. Қазір ауырсынуға төзімділігі төмен. Ауырсынудан қатты қорқады. Кері әсер де болуы мүмкін: өзіне де, басқаларға да ауырсыну келтіреді. Бұл белгімен жас қыздар босанудан қорқады. Балалар күрт қимылдардан, ата-ананың дауысын көтеруінен қорқады. Егер бала ақаулармен туса (қисаюлар, тері бөртпелері, мүшелердің дисфункциясы немесе патологиясы, ұрық суына тұншығу), онда ол өткен өмірде алған жарақаттарынан қайтыс болған. Егер жоқ болса, адам азаптауды бастан кешірген, бірақ соған ұшыраған жасында дененің тиісті деформациялары болады. Бұл — эфирлік дененің заңы.",
  "12": "Адам өткен өмірде қызметші болған, құлдықта немесе тұтқында болған. Оның сөз бостандығы мен ерік бостандығы болмаған. Қазір тәуелсіздікке және өзімшілдікке ұмтылады. Және бұл дұрыс!",
  "13": "Адамды өткен өмірде өзі сенген адам өлтірген. Кек алуға ант берген. Карма заңы бойынша өлтірушінің әулетінде, жазалаушымен қандас туыс болып туады. «Жазалаушы» бұл өмірде адамға ерекше қатыгез қарап, аффект (ашу-ыза жарылысын) тудырады. «Жазалаушының» төменгі жолында 13-аркан тұрады. Бұл өмірде дәл сол жаста өмірге қауіп, шабуыл болады.",
  "14": "Өткен өмірде адам әулеттің кәсіптерін, мүлкін және білімін мұраға алу құқығынан айырылған. Әулеттен қуылуы немесе әулет оны қабылдамауы мүмкін. Тек өзіне сенген. Қазір ата-анасының көмегін қабылдамайды, жиі оларға қарсы әрекет етеді.",
  "15": "Адам өзіне бүлдіру (порча) тартқан, ол өлім сәтінде алынған, бірақ санаасты әлі күнге дейін ол бар деп санайды. Қазір адам бақсы-балгерлерге жүгіреді, «күйген су үрлеп ішеді», бәріне магияны кінәлайды.",
  "16": "Адам үйсіз болған, тұрақты тұрғылықты жері болмаған (сарбаз, саяхатшы, гастрольдік артист, баспанасыз). Бұл адамдардың өмірдің түрлі салаларында орасан зор тәжірибесі бар. Қазір отырықшы өмір салтын ұстанады.",
  "17": "Адам шығармашылық идеяларға қызмет етіп, дарынсыздықты дәріптеген (Леонардо да Винчидің көмекшісі, ғалымның ассистенті, кадр сыртындағы әнші). Қазір мұндай адам мойындалу үшін күреседі немесе терең шығармашылық депрессияға кетеді.",
  "18": "Өткен өмірде адам өз әулеті үшін «жер жыртқан». Оны тұрмыс жеп қойған. Қазір ол шаруашылық жүргізуден, өзіне қосымша жүк артудан бас тартады, өйткені тұрмыстық құлдыққа түсуден қорқады.",
  "19": "Өткен өмірде адам үкіметке жақын, мәртебелі отбасында туған, бірақ мәртебесі мен билігінен айырылған. Қазір билік үшін күреседі. Өз орнын бермейді.",
  "20": "Өткен өмірде адам әулетке қарғыс тартқан, бірақ өлім сәтінде ол алынған. Қазір әулеттің барлық бәлесін магияға жабады (ретроградты Меркурий). Әулет оларды әрқашан жақсы көрмейді, қабылдамайды, өйткені олар өз әулетіне күйе жаққан. Бұл санаастында жұмыс істейді. Олар әулет үшін «жанып тұрады», ал әулет оларды қабылдамайды.",
  "21": "Өткен өмірде адам аңсаған арманын орындамай кеткен. Қазір мереке іздейді. Олар үшін мереке болыңыз! Оларға барлық армандарын орындау керек.",
  "22": "Өткен өмірде адам мақсатсыз өткен уақыт үшін өзін кінәлаған. Қазір мұндай адамдар бәріне қатар жармасады, дүрбелеңге түседі, уақыттан қорқады, аурулардан қорқады. Бір нәрсеге назар шоғырландырған жөн."
 },
 "ku3": {
  "1": "Кеңес тыңдамайды. Өз бетімен әрекет етеді. Жас ұрпаққа қызғанады.",
  "2": "Алғыс сезімінің болмауы. Басқа адамдардың әлсіздігін қабылдамау.",
  "3": "Балаларға қызғаныш пен агрессия. Оларды өз сәтсіздіктеріне кінәлі санайды. Перзент ретіндегі бизнес болуы мүмкін.",
  "4": "Салқындық, қатыгездік, бәрінен пайда іздейді.",
  "5": "Адамдарды құрметтемеу. Үлкендерді, бастықтарды мойындамау. Адамды серіктесінің күшті жақтары ашуландырады.",
  "6": "Ымыраға келгісі келмеу, қыңырлық, опасыздыққа бейімділік. Адам қарым-қатынаста шынайы емес.",
  "7": "Адам әлсіздерді, төмен тұрғандарды, бағыныштыларды, жастарды «жейді». Сонымен бірге тең немесе күштілердің алдында жасқанады. Балалары өзіне тең болғанша оларға әділетсіз.",
  "8": "Адам заңдар мен ережелерді бұзуға бейім. Әдейі қарсы әрекет етеді. Басқалардың пікірі оған жат. Сотқа беруге бейім.",
  "9": "Өзімшілдер, жалғыз қасқырлар. Жақын адамдарды жиі өзінен алыстатады.",
  "10": "Пайдакүнемдік, есепқорлық, пайда іздеу. Ұрлыққа бейім.",
  "11": "Қырсық, агрессиялы, төбелеске, кек алуға бейім. Өздерінің «пунктиктері» бар, соның кесірінен «шатырын ұшырып» алады.",
  "12": "Жамандау, ұятсыздық (цинизм), қорлау, басқаларды психикалық тұрғыдан басу. Адамдардың әлсіз жерлерін әрқашан біледі.",
  "13": "Қатыгездік, аффектке бейімділік. Басқа адамдардың өмірі мен денсаулығын бағаламайды. Өктемдер (самодуры).",
  "14": "Сараңдық. Өздеріне міндеттіміз деп санайды. Өлшем сезімі жоқ. Игілік талап етіп, ата-анасына жиі қысым жасайды.",
  "15": "Манипуляторлар, бопсалаушылар. Тілі айлакер. Олар импульсивті, қызғаншақ. Адамдарды бір-біріне айдап салады. Бірақ мұның бәрі тек сөз! Олардан қорыққанын ұнатады. Олар блеф жасайды.",
  "16": "Суыққанды, принципшіл, кешірмейді, ойланбай кесіп тастайды. Үйде қатаң тәртіп (домострой) орнатады. Егер бұл адамға біреу сатқындық жасаса, ол оны өмірінен сызып тастайды.",
  "17": "Адамдардың еңбегі мен таланттарын бағаламайды. Басқалардың жетістіктерін пайдаланады. Бөтеннің талантына қызғанады.",
  "18": "Шебер өтірікшілер. Сенбейді. Күдікшіл. Сөздерді бұрмалайды. Жағдайды ушықтырады. Кешірім сұрауды талап етеді. Серіктесін опасыздыққа жиі итермелейді.",
  "19": "Билікке және басуға ұмтылу; не «патша» («мен қалай айтсам, солай істе!»), не «кілемше» («Мен барлық құрбандардың ішіндегі ең құрбан болғанымын!», «қалағаныңды істе, мен ешкім емеспін ғой, өлсем де байқамайсың!») — екеуінде де өзін-өзі бағалау төмен, бопсалауға ұмтылады, кейіп танытады, манипуляция жасайды, құрбан рөлін ойнайды.",
  "20": "Әулетті, Отанды, халықты құрметтемеу. Дәстүрлерді жалғастырудан бас тартады. Бөтен сенімді қабылдауы мүмкін.",
  "21": "Супермендер! Ең талантты, мойындалмаған данышпандар, басқа планетадан келгендер. «Көңнің арасындағы жалғыз раушан».",
  "22": "Жалған аңғалдар. Жауапкершілікті басқаға артады. Қыңыр. Шешім қабылдаудан және қылықтарына жауап беруден қорқады."
 },
 "gift": {
  "1": "Жоғарғы күштерден сый ретінде адам сөзді шебер меңгеруді алды. Дау-дамайда, жанжалда делдал болу. Өзінде және айналасында төрт стихияның энергиясын біріктіре білу. Кез келген ақпаратты оңай алу және оны қисынды әрі айқын біріктіру. Жаңа байланыстар орнатудағы епті болу.",
  "2": "Жоғарғы күштерден сый ретінде адам басқа адамдарды іштей түсінуді алды. Табиғат стихияларымен тамаша байланыс. Түйсік. Ол бәріне қамқоршы, әрқашан көмекке келуге дайын. Магиялық өнердегі талант, болашақты болжау практикасы.",
  "3": "Жоғарғы күштерден сый ретінде адам әсемдік пен сұлулықты сезінуді, эстетикалық, мінсіз талғамды алды. Өмірді қалай байырақ әрі молырақ ету керегі туралы білім. Сый ретінде әдемі сыртқы келбет алды.",
  "4": "Жоғарғы күштерден сый ретінде адам шешім қабылдай, басқара, әкімшілік ете білуді және ерекше жұмысқа қабілеттілікті алды. Неден оңай әрі пайдалы болатынын, ал не табыс пен рахат әкелмейтінін сезудің сирек дарыны.",
  "5": "Жоғарғы күштерден сый ретінде адам өз білімін өте жоғары деңгейде алып, өмірде қолдануды, өзі білетінін басқа адамдарға үйретуді, зерттеулер жүргізіп, нәтижелерді өңдеуді алды. Өткеннің тәжірибесі мен ғылымның ең жаңа жетістіктерін біріктіре алады. Беделге оңай ие болу дарыны, өз ісінің кәсіпқойы бола білу.",
  "6": "Жоғарғы күштерден сый ретінде адам сүйіспеншілікті сөздің кең мағынасында сыйлауды алды. Тіпті ең қиын жағдайларда да таңдау жасап, қажетті шешімдер қабылдай алады. Бизнесте де, өмірде де күрделі серіктестік қарым-қатынасты реттеу таланты.",
  "7": "Жоғарғы күштерден сый ретінде адам мансаптық өсуге және осы салада табысқа жетуге қабілет алды. Серпінділік, ұтқырлық, өзіне сенімділік, табысқа жетуге деген ықылас. Тұрғылықты жерді, кәсіпті жиі ауыстыру, саяхаттар. Тез мансаптық табысқа жетуге көмектесетін ең жаңа техниканы өміріне енгізеді. Адамдарды соңынан ерту дарыны. Рационализаторлық, өнертапқыштық таланты, техникалық жаңалықтарды игеру саласындағы жаңашылдық.",
  "8": "Жоғарғы күштерден сый ретінде адам ерекше әлеуметтік әділдік сезімі мен құқықтық сауаттылықты алды. Қате шешімдерді объективті бағалау, олардан алшақтау және оларды екі рет қайталамау қабілеті, бұл жоспарларын сәтті жүзеге асыруға және қойған мақсаттарына жетуге мүмкіндік береді.",
  "9": "Жоғарғы күштерден сый ретінде адам жоғары руханилықты, дұрыс өмір жолын таба білуді және болмыстың жоғары заңдарын (әмбебап және ғарыштық) түсінуді алды. Ата-бабалардың тәжірибесі мен заманауи білімді біріктіре білу. Өз үстінен жұмыс істей білу, рухани өсу, ішкі әлемін мәңгілік рухани құндылықтармен байыту.",
  "10": "Жоғарғы күштерден сый ретінде адам пайдалы істерді сезетін түйсікті алды. Ақшаға ұқыпты қарау, табыс таба білу және көбейту. Материалдық саланы рухани саладан ажырата алады. Қосымша мұндай адамдар карманы өңдейді, көбіне мұндай нәрсенің бар екенін білмей де. Өмірдің екінші жартысында ауқатты болып, қайырымдылықпен айналысады.",
  "11": "Жоғарғы күштерден сый ретінде адам физикалық денемен, денсаулықпен жұмыс істеуді алды. Біреулер сый ретінде жақсы денсаулық пен үлкен физикалық күш алды. Басқалары — әлсіз әрі ауру денсаулық. Және өмір бойы денсаулықты жақсартудың ақпараты мен әдістерін іздеумен өткізеді. Бойындағы әлеуеттерді, таланттарды, бейімділіктерді тиімді пайдалану таланты, бұл бастапқы алған орнына қарамастан, өмірде жоғары нәтижелерге жетуге мүмкіндік береді.",
  "12": "Жоғарғы күштерден сый ретінде адам Дұғаларды Жоғарғы күштерге жеткізуді, сананың өзгерген күйлеріне оңай кіруді, өзінің ішкі әлемімен, Құдаймен, басқа Әлемдермен байланыс орнатуды алды. Олардың Дұғаларының емдік қабілеті және тазартатын қасиеттері бар. Бәрін төңкеріп, басқаларға ұқсамайтын осындай көзқарастан бастап бәрін жаңадан бастау — сый.",
  "13": "Жоғарғы күштерден сый ретінде адам өзін де, айналадағы әлемді де трансформациялау қабілетін, сондай-ақ тән мен жанды емдеу талантын алды. Өзгерістерден, тағдырдың сын-қатерлерінен және туындайтын мүмкіндіктерден қорықпау. Басқа адамдардың тағдырына оңай өзгерістер әкеле алады немесе мықты жүйке мен өзін толық бақылауды талап ететін экстремалды кәсіптерде жүзеге аса алады.",
  "14": "Жоғарғы күштерден сый ретінде адам өте проблемалы әрі шиеленіскен қарым-қатынасқа тепе-теңдік енгізуді, қиын жағдайлардан шығар жол таба білуді, айналасына үйлесім мен тыныштық әкелуді алды. Жұмсақтық пен ішкі үйлесім.",
  "15": "Жоғарғы күштерден сый ретінде адам түрлі деңгейлерде жүзеге асуы мүмкін орасан зор энергияны алды. Емшілік дарыны. Кез келген ортада көңіл-күй көтеріп, жағымды энергия әкеле алады. Биоэнерготерапиямен, Рейкимен немесе емшіліктің басқа түрімен айналыса алады.",
  "16": "Жоғарғы күштерден сый ретінде адам ескі, өзін ескірткен, қатып қалған жүйелерді бұзып, олардың орнына жаңа, заманауилау жүйелерді құра білуді алды. Жоқтан кез келген жағдайда ұзақ жылдар өмір сүре алатын күрделі құрылым жасай алады. Болашағы бар, тұрақты деп санаса, кез келген құрылымға сыйып кетеді. Уақытты сезіну дарыны, оны ұйымдастырып, әр минутты пайдалы жұмсай алады. Логиктер. Ұйымдастырушылар.",
  "17": "Жоғарғы күштерден сый ретінде адам көркемдік талантты алды, олар креативті, өнер туындысын жасай алады. Достық байланыстар орната алады. Сезімталдық, нәзіктік, әдептілік. Жоғарғы күштердің қамқорлығы дарыны.",
  "18": "Жоғарғы күштерден сый ретінде адам түйсікті, адам психикасы туралы білімді, жанды қиялды, бай фантазияны, аса сезімталдықты алды. Санаастымен байланыс орнатып, оның кеңестерін түсіну дарыны.",
  "19": "Жоғарғы күштерден сый ретінде адам көшбасшы, басшы болуды алды. Кез келген басшылық лауазымға оңай орналасады. Харизма дарыны, көпшілік алдында сөйлеу таланты, өз көзқарасын сенімді әрі дәл баяндай білу, дәлелдеу және кез келген істің мәнін баяндау қабілеті.",
  "20": "Жоғарғы күштерден сый ретінде адам сау әрі дана құндылықтар жүйесін жасай білуді, адамдар арасында жағымды қарым-қатынасты дамытуды алды, сондай-ақ талдау мен жинақтауға аса қабілетті ашық ақыл көрсетеді, бұл жағдайды шынайы бағалауға, қорытынды жасауға және алған тәжірибені іс жүзінде қолдануға көмектеседі. Өте отбасылық адамдар. Көбі әулеттік кармалық қарыздарды өтеп жүргенін тіпті білмейді. Жағымды дүниетанымы бар, ал депрессия оларға мүлдем таныс емес.",
  "21": "Жоғарғы күштерден сый ретінде адам космополитизмді, төзімділікті, шетелдіктермен және шетелдік компаниялармен байланыс орната білуді алды. Мұндай адам кез келген ортада өзін жақсы сезінеді, кез келген жағдайға бейімделе алады, өзі өмір сүруге тура келген елдің тілін, салт-дәстүрі мен мәдениетін тез үйрене алады. Әзіл сезімі, өзіне сырттан қарай білу, өзінің және басқалардың өмірін жеңілдету таланты. Күлкімен, қызығушылықпен, позитивпен өмір сүру, заманауи әрі өзіне сенімді адамдар.",
  "22": "Жоғарғы күштерден сый ретінде адам ынта-жігерді, өмірге деген құштарлықты, кез келген істі ерекше, жаңа тәсілмен шешу мүмкіндіктерін алды. Өмір — ойын, және ойнап өмір сүру керек — бұл адам ұстанатын ұран осы. Ол жаңашыл және жаңа көкжиектерді қуана ашады."
 },
 "harmony": {
  "1": "Ғаламның өзі сізді алдыңғы шепке қойды. Туғаннан энергияларға сезімталсыз, істер жердегі де, рухани да, шығармашылық та болады. Сізде ақыл күші мен Жер күші бар. Сізге ақыл күшін, ой күшін басқаруды үйрену, тағдыр белгілерін түсінуге тырысу маңызды. Сіз көпке игілік әкелуге қабілеттісіз! Сізге Ғажайып жасаушы болып туғаныңызды түсіну керек! Өз қолыңызбен жасауға болатынның бәрі — сіздің бағытыңыз.",
  "2": "Сізге табиғатынан байқампаздық берілген, жасырын және әдеттегі қабылдау мен түсініктің шегінен тыс жатқан нәрсені көріп, байқай аласыз. Олардың қамқоршысы — магия құдайы. Психология, медицина, емшілік, магия, астрология, актерлік.",
  "3": "Сізге табиғатынан әлемнің, Ғаламның барлық қазынасына ие болуға, сөзсіз гүлденуге деген ықылас берілген. Табиғатынан өзін сүюмен және өз денесіне, сондай-ақ үйге және балаларға қамқорлық жасап, күтім жасай білумен дарытылған. Сыртқы сұлулыққа ие, ақшаны тарта біледі, ақша оларды жақсы көреді. Адамдарға ертеңгі күнге деген сенім сыйлаңыз. Молшылық тақырыбы — сіздің тақырыбыңыз. Бизнес, кондитерлер, мейрамхана бизнесі, сұлулық бизнесі.",
  "4": "Сізге табиғатынан шешім қабылдау және жауапкершілікті өз мойныңызға алу энергиясы, тек өзіңіз үшін ғана емес, көптеген адам үшін жауап бере білу берілген. Кімге тағдыры бойынша билік энергиясы берілсе, соған қоғамда өрлеу жолында үлкен мүмкіндіктер мен көкжиектер ашық. Басқару жолымен жүріңіз, сонда ақша сізді өзі табады. Бизнес, саясат, прорабтар, сәулетшілер, директорлар, басқарушылар.",
  "5": "Сіздің міндетіңіз — өмірде білім іздеу. Табиғат сізге шешендік, ұстаздық, сендіру талантын берген. Сізге дәстүрлерді, негіздерді, ережелерді, білімді, әдістерді сақтау, өзгерту және жақсарту қабілеті берілген. Әлемді жаңа біліммен толтыру. Педагогика, заңгерлер, жылжымайтын мүлік, психология, мемлекеттік қызметтер.",
  "6": "Сізге табиғатынан сұлулық пен өмір мерекесін сезіну берілген. Шынайылық дәл қуаныш пен нұрда туады. Айналаңызда мереке жасаңыз. Сұлулық. Сіз адамдарға сұлуырақ, жеңілірек, қуаныштырақ болуға, сиқырға, күлуге, әзілдесуге көмектесе аласыз. Продюсерлік, стилистика, мереке жүргізушілері, режиссерлер, махаббат магиясы.",
  "7": "Сізге табиғатынан көшбасшы, жауынгер энергиясы, жеңіске, мақсатқа ұмтылу берілген. Сіз үшін түпкі мақсатты түсіну және білу маңызды. Табандылық, нәтижеге бағытталу, қайсарлық, құлап, қайта тұрып, құлағаннан кейін тағы да тұрып, мақсатқа қарай жүре алады. Сізде үлкен мүмкіндіктер бар. Тәжірибемен бөлісіңіз, адамдарды шабыттандырыңыз, соңыңыздан ертіңіз. Бизнес, жол инспекциясы, курьерлер, фитнес жаттықтырушысы, әскери құрылымдар, армия, құқық қорғаушылар, шендер, арнайы қызметтер, туризм, рухани және саяси көшбасшылар.",
  "8": "Сізге табиғатынан өткен өмірлердің кармасымен көрінбейтін энергетикалық жіп берілген. Дәл соларға кармалық әділдік заңын тереңірек әрі нәзігірек көру, сезіну және түсіну берілген. Оларға үнемі өз кармасын жақсарту үстінде жұмыс істеу берілген. Сізге Ғаламдық кармалық заңмен терең байланыс берілген. Бұл — сіздің туғаннан, арнауыңыз бойынша берілген қасиетіңіз. Түйсікпен көру қабілеті. Карманы емдеу қабілеті. Заңдылық, билік, салық құрылымдарында жұмыс, заңгерлік, әскери қызмет. Бизнес, кармалық психология, нумерология, емшілік, эзотерика.",
  "9": "Сіз табиғатынан өзін-өзі жеткілікті және даналыққа ие адамсыз. Даналық пен жарқын ақыл оларға кез келген, тіпті көптеген басқалар үшін ең күрделі міндеттерді де түсінуге көмектеседі. Емшілік қабілеттер сізге туғаннан берілген. Сіз сөзбен емдей аласыз, сондықтан бұл дарынды бәрінің игілігіне пайдаланасыз. Сізге адамдар үшін пайдалана алатын жаңа білім ашылады. Қарапайым құралдармен көп нәрсеге жету. Қойылған мақсатқа баяу әрі сенімді жылжу. Сауықтыру, емдеу. Жоғары қамқоршылар. Жақсы оқу және жақсы оқыту. Ғылым, медицина, психология, Оқытушылық, жазушылар, монахтар, жаңа ғылыми әзірлемелер, жаңа технологиялар, жаңа әдістер.",
  "10": "Сіз туғаннан бақытты жұлдыз астындасыз. Жоғары қамқоршылар. Бақтың өзі сізді кез келген жағдайдан шығарады. Сізге жаңа ағымдардың Энергияларымен біртұтас болуды үйрену керек. Өмір дана, ол кармалық міндеттеріңізге сәйкес сізге қазіргі сәтте не керек екенін өзі біледі. Физикалық денемен айналысып, салауатты әрі белсенді өмір салтын ұстану керек, өйткені Ағын — белгілі бір бағыттағы қозғалыс. Ал адамның өзі өз өмірі мен тағдырының бағытын белгілеуі керек. Енжар емес, шығармашыл әрі жасампаз болу. Стюардессалар, туризм, футбол, би ұжымдары. Қаржы құрылымдары, банктер, бағалы қағаздар нарығы.",
  "11": "Сіз табиғатынан дарасыз. Әлеуетке ие, ойларыңыз бен энергияларыңызды басқаруды үйреніңіз. Көшбасшылық энергиясы. Адамдарды соңыңнан ерту. Сізге ерекше күш берілген. Жоғары рухани идеялар мен мақсаттарға назар аударыңыз. Тек сіздің жағымды тәжірибеңіз арқылы адамдар сізді естіп, өмірде өзгерістерге және жақсы жаққа өзгеруге келгісі келеді. Айналадағыларды азырақ қинап, өзіңіз де азырақ ширығуға тырысыңыз. Бизнес, өз ісіңіз, спорттық іс-шаралар, құқық қорғау органдары, құтқарушылар, күш жұмсаумен байланысты кәсіптер.",
  "12": "Сіз Құдайдың қызмет ету заңымен белгіленгенсіз. Сізде ерекше міндет бар: көбірек мейірім, рақым, жанашырлық әкелу. Адамдарды ашық болуға үйрету. Сізбен туғаннан Періштелер жұмыс істейді, сізде жақсы көктегі сақтаушылар бар. Сіз арқылы бірегей әдістер мен жаңа жолдар келеді. Сізге заттардың, оқиғалардың, адамдардың, құбылыстардың мәнін басқаша көру және түсіну берілген. Психология, эзотерика, емшілік, медицина, педагогика, балабақшалар, қайырымдылық жұмысы, науқас адамдармен жұмыс, фармацевтер, ветеринарлар, шығармашылық.",
  "13": "Сіз табиғатынан арнау энергияңыз бойынша мистикалық және болжауға келмейтінсіз. Сіз Жердегі циклдік ырғақтарды ешкімге ұқсамай түсінесіз. Батылдыққа, ержүректілікке, қорқынышсыздыққа иесіз, батыл, белсенді, ерлікке, сезім серпілістеріне қабілеттісіз. Сіздің өміріңіз циклдерге құрылған: бір күйлер басқаларымен ауысады, өмірдің өз тынысы сияқты. Адамдарға өзгеруге, қиындықтардан рухани сабақ алуға, ескіні жіберуге көмектесу, адамдарға өзгерістер жолын көрсету — бұл сіздің Жердегі миссияңыз, бұл сіздің арнауыңыз. Сізге энергетикалық практикалар мен энергетикалық гимнастикаларды дамыту, Ғаламның шексіз энергия көзінен нәр алу пайдалы. Жоғары бейімделу. Хирургтар, жедел жәрдем, ыстық нүктелердегі қызмет, каскадерлер, кеңістіктер мен аумақтарды тазарту, кармалық емшілік, психология, эзотерика.",
  "14": "Сізде туғаннан Періште-сақтаушымен байланыс бар, сондықтан түйсік пен экстрасенсорлық сезіну дамыған. Сізге Жерде шығармашылық процесті жасау энергиялары, адам жанын емдеу күші, оның өнер арқылы оянуы мен пісіп-жетілуі берілген. Психология, дәрігерлер, емшілік, фармацевтика, театр қызметі, өнертану, әдебиет, мұражай, энергетикалық емшілік.",
  "15": "Сізге Құдай үлкен мүмкіндіктер берген. Адамдарды жердегі қуаныштарды бағалауға үйретіңіз, бірақ жердегі нәрсеге жабыспаңыз, өйткені рух күші біз ілгектер мен тәуелділіктерді жібергенде қалыптасады. Ізгілік үшін өмір сүріңіз! Продюсерлер, қаржы, рухани практикалар жаттықтырушысы, шенеунік, бизнес. Жылжымайтын мүлік, музыка.",
  "16": "Адамдарды ояту — Жердегі игі миссия және жауапты міндет. Өмір алдыңызға биік планка қояды, сізге рухани өсу сатыларымен көтерілу керек. Құрылыс, сәулет, дизайн, медицина, травматология, спорт, сапёрлер, мергендер, ұсталар, археологтар, геологтар, мұнайшылар.",
  "17": "Сіз өзіңіздің бірегей жұлдызыңыздың астында өмір сүресіз және жарқын қабілеттер мен таланттарға иесіз. Сіз бәрінде талантсыз. Күнделікті дұғалар, медитациялар, энергетикалық жаттығулар практикасы сіздің табиғи энергетикалық, жұлдыздық арналарыңыздың өткізгіштігін арттырады. Жазушылар, суретшілер, әншілер, артистер, сұлулық салондары, теңіз ісі, астрономия, биоэнергеттер, емшілер.",
  "18": "Сізге магиялық күш берілген, оны бәрінің игілігі үшін пайдалануды үйрену керек. Энергетикалық заңды зерттеңіз. Түйсікпен көру, түс көру практикасын меңгеріңіз. Физикалық денеңізге күтім жасап, оны жаттықтырыңыз, мистикалық Ай сияқты сұлу әрі мықты етіңіз. Фантастар, ертегішілер, ақындар, фотографтар, музыканттар, театр, сән, флористер, оккультистер, магтар, емшілер, шығыстанушылар, психиатрлар, наркологтар, криминалистер, бағдарламашылар.",
  "19": "Сізге Құдай көптеген адамға арналған міндет берген. Жер мен адамдарды жақсартуға, емдеуге қатысыңыз. Сізге адамдардың ақыл-ойы мен санасын нұрландыру, жандарды нұрландырып, махаббатқа толтыру қабілеттері берілген. Көпке үлгі болу. Қоғамдық қызмет, саясат, бас қолбасшылар, мемлекет басшылары, маркетинг, бағалы қағаздар, валюта нарығы, бизнес. Мұғалімдер, директорлар, әскери-қорғаныс кәсіпорындары.",
  "20": "Сізге айқын есту, ақпарат беру және кармалық емшілік қабілеттері берілген. Сізге карманы және кармалық ауруларды емдеу мәселелері бағынады. Сіз адамдардың өткен өмірлері туралы, олардың осы өмірге арналған міндеттері туралы ақпаратты ала аласыз. Сізде жаңа уақытқа сай жаңа білімді беру миссиясы бар. Дәрігерлер, хирургтар, стоматологтар, психотерапевтер, криминалистер, жерлеу бюросы. Мистиктер, медиумдар, болжаушылар, экстрасенстер. Бизнес, саясат, журналистика, археология. Қолбасшылар, стратегтер. Қаржы құрылымдары. Шығармашылық. Жазушылар. Байланысшылар. Жердегі аномальды құбылыстарды зерттеу.",
  "21": "Сізді планетаның барлық адамдарымен кең жүрегіңіз, көптеген адамның игілігі үшін Жоғары қызметке толы болуыңыз біріктіреді. Сіз — басшы, сіз — байланыс. Планетамызды емдеу үшін барлық прогрессивті әрі жарқын нәрсені біріктіріңіз. Сіз — бітімгерсіз! Аудармашылар, гидтер, туризм, әскери қорғаныс. Саясат, дін, дипломатия. Журналистика. Экономика. Қаржы, инвестициялау, несиелеу. Фестивальдер, көрмелер. Пайдалы қазбалар. Емшілер, биоэнергеттер, бақсылар (шамандар).",
  "22": "Сіздің Жаныңыз өзін шығармашылықта көрсеткісі келеді. Сіз үшін қабілеттеріңізге ерік беру өте маңызды. Шығармашылық өзін-өзі көрсету сізді энергия мен қуанышқа толтырып, өмірге деген құштарлықты тұтандырады. Сізге тағдыр бойынша адамдарға өз үлгіңізбен жаңа жолдарды көрсету, көңілді болу берілген. Авантюрист, белгісізге қуана қадам басатын, жаңа циклдерді, істерді оңай бастайтын, жаңа жолдар ашатын, батыл. Туризм, саяхаттар, парашют спорты, журналистика, дипломатия, көрмелер, тренингтер."
 },
 "mission": {
  "1": "Мейірімді әрі дана сөзбен көмектесу. Әлемге үйлесім әкеліп, энергетикалық шиеленісті басу. Сіздің сөздеріңіз адамдардың санасында із қалдырады, айтылған сөздеріңізді қадағалап, адамдарды шабыттандырыңыз. Талантыңызды пайдаланбау немесе оны пайдакүнемдік мақсатта пайдалану қате болады.",
  "2": "Өз аналығыңызды сөздің кең мағынасында жүзеге асыру: басқа адамдарға қамқорлық, мұқтаждарды қамқорлыққа алу, өмірдегі бағытын жоғалтқан жастарға қолдау көрсету арқылы. Матрицада жатқан құпия білімді ашу. Бойыңыздағы әйелдік көріністен бас тарту қате болады, сонда әйелдермен мәселелер туындайды. Ер адамдарға бұл арканды өңдеу қиынырақ, бірақ мүмкін: дәрігерлер, емшілер, ветеринарлар, кез келген көріністегі құтқарушылар. Астрологтар, нумерологтар.",
  "3": "Адам сөздің кең мағынасында ана болуы керек: көп балалы аналар, балалары мен күйеуінің талантын ашқан аналар, балалардың бос уақытын, мектепке дейінгі білімді ұйымдастырған әйелдер. Шығармашылық шеберханалар құрғандар. «Берегиня» әйелдер клубтары және т.б. Талантты адамдардың жүзеге асуының жаңа жолдарын туғызу және ашу. Бала тууынан, балалардан, отбасынан, жаңа бағыттардан бас тарту, жан және шығармашылық бедеулігі қате болады.",
  "4": "Адам өзінен кейін із қалдыруы керек. Бойында биліктің шынайы сезімін ашу. Бейбітшілік пен мейіріммен басқару жауапкершілігін өз мойнына алу. Үлкен, жаһандық жобалар мен ақшадан қорқуды өңдеу. Сізден туыстарыңыз да, айналаңыздағы адамдар да нұсқау күтеді. Таланттары мен мүмкіндіктерін кәсіби жүзеге асырудан бас тарту қате болады. Алдыңызда тұрған жауапкершілікті түсінбеу. Пайда үшін билікке құштарлық.",
  "5": "Жоғары, ең жақсы білім алу. Немесе тұлғаның діни даму жолын таңдау. Ғылымда немесе көне құпия білімде, дінде, көне мәдениеттер мен салт-дәстүрлерде, басқа адамдардың дәстүрлерінде зерттеулермен айналысу. Миссия — адамдарды ақиқат жолға бағыттау, өмірдің түрлі салаларында ұстаз болу. Адамдарды түсінуді үйрену. Сондай-ақ әкемен, балалармен және өзіңіз жауапкершілік алған адамдармен, мысалы, бағыныштылармен, студенттермен қарым-қатынасты реттеу керек... Басқа ұстаздардың пікірін қабылдамау және жалпы білімнен бас тарту — қате.",
  "6": "Бүкіл әлемді және оның әр бөлшегін сүйіспеншілікпен сыйлау: барлық тіршілік иелерінің нәсілдері мен түрлеріне төзімділікпен қарау, өз отбасыңызды, жақын ортаңызды және бүкіл Ғаламды жақсы көру арқылы. Өз таңдауыңыз үшін жауапкершілік алуды үйрену. Махаббатқа жеңілтек, ұятсыз (циникалық) және бейқам қарау қате болады.",
  "7": "Өз табыстарыңыз, кәсіби қызметіңіз, мансабыңыз арқылы әлемді өзгерту және мойындалу. Адам мен оның еңбектері көрініп тұруы керек. Ең кең адамдар тобына пайдасы тиетін табыстарға жету. Тағдыр сізге қамқорлық жасағанша отырып күту қате болады.",
  "8": "Терең әділдік сезімі, басқа адамдардың ренжістеріне мұқият қарау, адамдардың құқықтарын сақтау және қорғау. Алдымен өзіңізге қатысты әділдік сезімін өзіңізде өңдеу. Отбасыңызға деген әділетсіз қарым-қатынасқа көз жұммай, оны қорғауға тұру. Кімге болсын әділетсіз қарым-қатынасқа немқұрайлы қарамау. Егер адам болып жатқан әділетсіздікке, тіпті ұсақ-түйекте де, немқұрайлы қалса, қате болады. Соттардан, сот талқылауларынан қорқу.",
  "9": "Құпия эзотерикалық білімді зерттеу. Аға буынмен өзара әрекеттесу және оларға көмек. Адам алған білімі мен даналығының арқасында қарт адамдардың өмірін «нұрландыруы», дәлірек айтқанда жеңілдетуі және өмірде болып жатқан барлық процестердің мәнін түсінуі керек. Рухани дамуды елемеу қате болады, сонымен бірге ол эзотерикамен айналысудан бас тартып, діни даму жолымен жүруі мүмкін.",
  "10": "Ақшаға және материалдық істерге тиісті көзқарас қалыптастыру. Әлемде тұрақты ештеңе жоқ екенін түсіну. Жоғары деңгейде аркан кармалық қарыздарды саналы түрде өңдеу және карманы тазарту туралы айтады. Өз әулетінің, отбасының, елінің гүлденуіне қамқорлық жасау. Қаржылық істерді елемеу қате болады, басқаның — ата-ананың, жұбайдың есебінен, несие есебінен өмір сүруге болмайды.",
  "11": "Өз денеңіздің үстінен жұмыс, өзіңізді физикалық әлемнен табу, алған әлеуетті дамыту. Әулеттің, отбасының, компанияның, елдің көшбасшысы болу. Мәселелерден қашу, сырттан болуы мүмкін қауіптерге көз жұму қате болады. Ұлы көсемдер, әскерилер.",
  "12": "Ішкі әлемді зерттеу, өзіңіздің Жоғарғы Меніңізді табу. Рухани өсу, рухани даму жолымен жүру, эмоцияларды және әлеммен эмоционалдық өзара әрекеттесуді зерттеу. Кез келген жағдайдан шығудың жаңа көзқарасын жеткізу. Өзіңіздің армандар әлеміңізге тұйықталу — қате. Оқшаулану.",
  "13": "Трансформация — адамның басты миссиясы: ішкі процестердің трансформациясы, сыртқы өзгерістер. Өзгерістерге үйреніп, оларды басқаруды үйрену. Қиын жағдайларда адамдарға қызмет етіп, көмектесу, шешім табу және қажет болса мұны пайдасыз жасау. Мысалы, біреудің үйі өртенді, ал сіз оны қайта салуға немесе қажетті қағаздарды рәсімдеуге көмектесе аласыз, немесе сізде үй мен саяжай бар және көмек ұсына аласыз, немесе күшіңіз жететін басқа бір нәрсе. Немқұрайлы немесе сырттан бақылаушы болып қалу қате болады.",
  "14": "«Алтын орта» — бұл өмірдегі сіздің кредоңыз. Сіз — үйлесім мен қамқорлықтың, тепе-теңдік пен теңгерімнің өзісіз. Төзімді мінез-құлық пен қарым-қатынасты көрсету. Қате — эмоционалдық тұрақсыздық, күмән, шектен шығушылық, шатастыру.",
  "15": "Өз энергияңызды бақылау және оны дұрыс бөлу. Миссия — қарапайым азғырулардан арылу. Эзотерика саласында, құпияны түсінуде тиісті көзқарас қалыптастыру. Адамдардың игілігі үшін пайдалану керек емшілік қабілеттер. Қате — энергияны, жыныстық қатынастарды теріс пайдалану, қылмыстық әрекеттер, азғыруларға берілу.",
  "16": "Кең мағынадағы құрылыс: тұлғаны, мінезді, қарым-қатынасты, әлеуметтік байланыстарды, саясатты, үйлерді, мүсіндерді салу. Жүзеге асудың заманауирақ әрі өзектірек жаңа жолдарын табу. Аяқталған бағдарламаларды жою. Қате — өмірде ештеңені өзгертпеуге деген қыңыр ықылас, ескі өмір құрылымдары мен психикалық бағдарламаларды пайдалану.",
  "17": "Мұндай адам біздің әлемге өзінің шығармашылық туындыларын әкелуі керек. Достық байланыстар орната білу, өзінің және басқалардың сезімдерін түсініп, ажырата білу, сұлулыққа, табиғатқа, тағамға, тарихқа сүйсіне білу... Өз таланттарын жете бағаламау және оларға сенбеу, шынайы қарым-қатынас пен достықтан бас тарту қате болады.",
  "18": "Отбасында, ұжымда ауа мен атмосфераны реттей білу. Тамақ дайындау, үйді безендіру шеберлігі. Түйсікті, қиялды, фантазияны дамыту үстінде жұмыс істеу. Әйелдік бастауды нығайтып, үйге көп уақыт арнау. Санаастымен байланыс орнату. Қате — басқалардың өтініштеріне жеңілтек қарау, түйсік пен санаасты кеңестерін елемеу, жақын адамдармен құрғақ қарым-қатынас, үйдегі ретсіздік.",
  "19": "Бойыңызда харизманы, асылдықты, мейірімді, адалдықты дамыту. Әрқашан дана әрі жауапты болу. Жалпы игілік үшін жұмыс істеу. Өз тұлғаңызға тұйықталу қате болады.",
  "20": "Мұндай адам жерге отбасылық қарым-қатынасты өңдеу, ата-анаға және жақындарға тиісті көзқарас қалыптастыру үшін жіберілген. Ол өз әулеті туралы бәрін біліп, өмірдегі өз орнын табуы керек. Өз құндылықтар жүйесін қайта қарап, кемелденген дүниетаным қалыптастыру. Әлемге сау әрі дұрыс құндылықтар жүйесін көрсету, отбасын қолдап, оған көмек көрсету. Қате — отбасындағы мәселелерді елемеу, шыққан тегіңізден, дүниетаныммен ұялу.",
  "21": "Мұндай адамның миссиясы — шетелдіктермен байланыс, техникалық инновацияларды енгізу, түрлі мәдениет пен дәстүрдегі адамдарды біріктіруге ұмтылу. Қате — надандық, өз нәсілін, ұлтын асқақтату, төзімділіктің болмауы.",
  "22": "Бастаманы өз қолына алу қабілеті, кәсіпкер, шебер (қолөнерші), фрилансер, стартапшы болу. Жаңалықтарды бірінші болып танып, оларды әлемге жаппай енгізу, өмірге жеңіл әрі ынталы көзқарас. Қате — өзін шектеу және өмірге тым байыпты қарау."
 },
 "cycles": {
  "1": "Кез келген адаммен тіл табыса білу. Ақпаратқа ғылыми тәсіл. Дамыған интеллект. Көпшілік алдында сөйлей білу. Тамаша мұғалім, дәріскер.",
  "2": "Емшілік. Басқа адамдардың психофизикалық және эмоционалдық күйін сезіну. Түйсік, жануарларды түсіну. Шөптерді ажырата білу.",
  "3": "Балаларды тәрбиелей білу. Ойларды материалдандыру («Құпия» (Секрет) фильмі). Жақсы кәсіпкерлер, бірақ оларға жұп (серіктес құрылтайшылар, достар) керек. Таланттар, шығармашылық.",
  "4": "Жоқтан бизнес құра білу. Бәрінде кәсіпқой, оған қажетті тәжірибе мен дағдылар беріледі. Тамаша басшылар, қатал, бірақ әділ.",
  "5": "Даналық, руханилық. Басқа адамдардың арнауын көре білу, олардың қажеттіліктерін оқу. Сөзбен емдеу. Не жақсы, не жаман екенін түсіну.",
  "6": "Отбасын, қарым-қатынаста үйлесім құра білу. Жақындарды алыстан сезіну. Қолөнер, қонақжайлылық, үйдегі барлық кәсіпті меңгеру. Қарым-қатынасқа ашықтық, күлімсіреу. Адамдар оларды әрқашан мейіріммен қабылдайды.",
  "7": "Толқынның қырын сезе білу, яғни керекті сәтте және керекті уақытта көру, тез шешім қабылдау. Көптеген нұсқаның ішінен ең сәттісін таңдау. Жылдам ойлау. Бейтаныс адаммен сәтті диалог құру дарыны.",
  "8": "Кез келген заңдарды, қағидаларды, негіздерді білу. Әділдік, өлшем сезімі. Эмоцияларды басқара білу. Жанжалда салқын, екі бағытта ойлайды. Әрқашан «Б» жоспары бар. Құжаттарды бәрінен жақсы қолдан жасайды.",
  "9": "Эзотерикалық таланттар, «айқын...» дегеннің барлық түрлері (айқын көру, айқын есту, айқын түсіну...). Абсолютті өзін-өзі жеткілікті, тәуелсіз, кез келген нәрсені жалғыз жасай алады. Жоғарғы күштердің көмегі.",
  "10": "Ауадан ақша жасай білу. Бизнесті қалай көбейту, дамыту керегін сезіну. Кез келген істегі болашақ.",
  "11": "Қарсыластың әлсіз жақтарын көреді. Тіпті шарасыз жағдайларда да жеңе білу. Басқа адамдардың эмоцияларын басқара білу. Жауларды және олардың жоспарларын алдын ала тани алады. Әсіресе сыни жағдайларда (шкафты жалғыз жылжыту) ғажайып күшке ие. Төзімділік пен ақылдың салқындығы.",
  "12": "Психологтар. Басқа адамдардың эмоцияларын сезеді. Лайықты сөздер таба білу. Қарым-қатынасқа ашықтық. Басқа адамдардың арнауын білу.",
  "13": "Көбірек көреді, көлемдірек түсінеді. Баламаларды көреді. Кез келген жағдайдан шығар жол табады. Ерекше (эксклюзивті) нәрсені көру. «А» жоспары мен «Б» жоспары бар. Гипноз дарыны. Басқа адамды қайта бағдарламалау қабілеті. Оған өз еркін таңу.",
  "14": "Кез келген динамикалық жағдайды тыныштандыра білу. Жасушалардың регенерациясына бейімділік. Емшілік дарыны. Тамаша селекционерлер. Өсімдіктердің жаңа сорттарын шығара алады. Жануарлар оларды қатты жақсы көреді (ветеринария).",
  "15": "Айқын көру және басқа экстрасенсорлық қабілеттер, соның ішінде магиялық қорғаныс. Қалағанының бәрі, тіпті басқа адамдарға зиян келтірсе де, орындалады. Ақылға сыймайтын харизма. Тамаша әзіл сезімі. Ұйымдастырушылық қабілеттер.",
  "16": "Ешқандай құралсыз кез келген нәрсені нөлден сала білу. Іске іргелі тәсіл. Тез шешімдер. Болашаққа жоспар құра білу. Алдын ала көру.",
  "17": "Шығармашылықтың барлық түрлері, сезімдердің романтикалығы. Түстердің, иістердің, дыбыстардың кеңірек ауқымы. Кез келген идеяны, арманды, міндетті іліп алып, жүзеге асыра білу. Даңқ пен табыс алу қабілеті.",
  "18": "Үйдегі қолөнердің барлық түрлері. Адамның стиль, сұлулық сезімі бар. Үйлеспейтінді үйлестіреді. Кез келген нәрсені өзгерте алады. Өтірікті сезеді. Өздері шебер өтірік айтады. Түс көру дарыны. Олардың қолында орасан зор жасампаз энергия бар. Сұлулық жарата алу қабілеті.",
  "19": "Мансап жасау қабілеті. Бәрінде сәтті, рухы мен еркі мықты. Сымбатты, келбетті. Әлеуметтік тұрғыда орташа деңгейден жоғары көрінеді.",
  "20": "Әулеттің барлық таланттары (ана мен әке жағынан).",
  "21": "Қажылық (зиярат). Адамдарды, басқа халықтарды түйсікпен түсіну. Бейнелі ойлау. Кез келген жағдайға бейімделе білу. Жаңашылдық.",
  "22": "Қарым-қатынасқа ашықтық. Жеңілдік, достық пейіл. Адам жағымды әрі сүйкімді. Бірнеше істі бір мезгілде атқара алады. Ең кемі — бәрінің екіден болуы. Көп қырлылық."
 },
 "eventsPlus": {
  "1": "Бауырлардың, құрдастардың және жасы кішілердің, шәкірттердің көмегі; жаңа жобалар (стартаптар) оңай жүзеге асады; тез нәтижелер; құжаттарды дұрыс рәсімдеу, жеңіл мәмілелер; көпшілік алдындағы кәсіптердегі табыс.",
  "2": "Мықты денсаулық; әйелдермен жақсы қарым-қатынас; ықпалды әйелдердің қамқорлығы; болашақ беретін мәмілелер; неке, бала тууы.",
  "3": "Неке, бала тууы; балалардың көмегі; адам анық елестеткеннің бәрі жүзеге асады; бірлескен жобаларды жүзеге асыру; өндіріске (материалдық немесе зияткерлік) байланысты шағын бизнестің тұрақтылығы.",
  "4": "Мансап, жақсы мансаптық өсу; адам тікелей қатысатын сәтті бизнес; ірі бизнес (50-ден көп адам); болашағы бар мәмілелер; әріптестер тарапынан көмек; адам өзі істесе, бәрі шығады; пайдакүнем (есеппен құрылған) некелер.",
  "5": "Ықпалды ер адамдар тарапынан көмек; адамға өмірлік тәлімгер беріледі; мансап сатысымен алдын ала (аванспен) жоғарылау; сапарлардағы табыс.",
  "6": "Неке, бала тууы; махаббатқа негізделген қарым-қатынас; шағын отбасылық бизнес немесе үйде жұмыс; отбасылық бизнесті немесе әулеттік кәсіпті дамыту; болашағы бар және ұзақ мерзімді келісімшарттар; жеке және дербес кәсіпкерліктегі табыс; шынайы серіктестікке негізделген болашағы бар мәмілелер.",
  "7": "Міндеттерді тез шешу; сәтті саяхаттар, сапарлар, көшулер; көп нұсқалылық (барлық нұсқа бірдей жақсы); жылдам мансаптық өсу; тез бастау, тез нәтижелер; «ауызша жарнама» (сарафанное радио).",
  "8": "Бизнес; мансап; сәтті мәмілелер, әсіресе сатып алу-сату; мемлекеттің көмегі; келісім бойынша неке.",
  "9": "Аға буынның (жасы, мәртебесі бойынша) көмегі; зейнеткерлердің көмегі; барлық бұрынғылардың көмегі; адам ешкімге сенбейтін істер жүзеге асады; ішкі әлеуеттер мен қабілеттердің ашылуы; денсаулық және эзотерика саласындағы әл-ауқат; құрылтайшыларсыз жеке бизнес (ірі де, ұсақ та, бастысы — құрылтайшы біреу болуы); адамда бәрі бақылауда екенінің кепілі.",
  "10": "Мансап пен бизнестегі табыс; ірі бизнес; үлкен қаржы ағындары; жоғары табыс, байлық; жылжымайтын мүлік сатып алу; болашаққа орасан зор перспектива; бәрі тез қозғалып, өте жоғары нәтижелер береді.",
  "11": "Сөзсіз жеңіс, бірақ күш салусыз емес; адам кез келген мақсат пен биікке тек бәсекеде жетеді; ірі, қуатты, резонанс тудыратын бизнес; мансаптық өсу; адам оңай еңсеретін кедергілер; күрделі, бірақ эмоционалды қарым-қатынас; белсенді әрекеттер басталғанға дейін бәсекелестер мен жауларды анықтау.",
  "12": "«Халықтың сүрлеуі бітелмейді»; кең танымалдылық; үлкен қарым-қатынас, клиенттер шеңбері; аз таныс адамдар тарапынан көмек; жолдағы қолдау мен жеңілдік; көптеген идея мен ұсыныс, бәрі әртүрлі, бірақ қолайлы.",
  "13": "Әрқашан жақсылыққа апаратын тез, күрт өзгерістер; оқиғалар калейдоскопы; нәтиже күткеннен жақсы; ерекше ұсыныстар; мансап пен бизнес, әсіресе ерекше әрі инновациялық жобалар бойынша; сәтті креативті бизнес; стандартты емес мансаптық өсу; адамға барлық жерде жол ашық; ғажайып сыйлықтар.",
  "14": "Шағын, бірақ тұрақты бизнес; адам өзіне лайықты нәрсені алады; лайықты мансаптық өсу; шағын, бірақ тұрақты табыс; тыныш, болжамды өмір; мүлдем үміттенбеген адамдар тарапынан көмек.",
  "15": "Кез келген тілектің орындалуы; байлық; кәсіппен байланысты емес ірі бизнес (мүмкін, қылмыстық); қылмыс әлемінің көмегі; сәтті мансаптық өсу; шығармашылық және экстрасенсорлық даму; шығармашылықта жүзеге асу; эмоционалды, құмарлы қарым-қатынас; жағымды оқиғаларды өршітеді (жылдамдатады).",
  "16": "Планетаның кез келген нүктесіндегі сапалы мүлік; мұра алу; көп филиалды ірі бизнес; қаржылық әл-ауқат; мансаптық өсу; тұрақты әрі сенімді өмір салты; серіктеспен тұрақты қарым-қатынас.",
  "17": "Жеңіс; шығармашылық жобаларды жүзеге асыру; мансаптық өсу, бизнес; шағын шығармашылық бизнес; сәттілік пен табыс; танымалдылық, даңқ, атақ; романтикалық қарым-қатынас; бала тууы; адам мақсаттарға жетуде жеңілдікке ие болады.",
  "18": "Неке, бала тууы; әдемі, жайлы әрі ыңғайлы үй; шағын, бірақ жеке мүлік; үйдегі бизнес; үй жағдайы бар бизнестегі табыс; адамдармен жақсы қарым-қатынас; әдемі, стильді өмір.",
  "19": "Жылдам мансаптық өсу; жоғары лауазымдар; мәртебе және үлкен өкілеттіктер; қуаныш пен табыс; сәтті мәмілелер; бизнес; әсіресе мемлекеттік қызметшілерге көмектеседі.",
  "20": "Неке, бала тууы; әулеттік отбасылық бизнес; тұрақты табыс; ертеңгі күнге деген сенім; әулеттік мүлік; туыстармен жақсы қарым-қатынас; жақын ортаның көмегі.",
  "21": "Шетелде, шетелдік компанияларда, шетелдіктермен табыс; шетелдегі бақуатты өмір; сәнді, сапалы өмір; адамды өз адамындай қабылдап, өмірде алға жылжытып, сыйлықтар береді.",
  "22": "Адам бір мезгілде көптеген игілік алады; неке, бала тууы; достардың қолдауы; көптеген жаңалықтар; көп функционалды және әр бағыттағы бизнес."
 },
 "eventsMinus": {
  "1": "Бауырлардың/құрдастардың/жасы кішілердің/шәкірттердің сатқындығы; бауырлардың ауруы/қайтыс болуы; барлық жаңа жобалар жүзеге аспайды; мәмілелерді дұрыс рәсімдемеу; сізге қарсы дәлелденбейтін алаяқтық; құжаттардағы жалғандық; процестердің созылуы; мәмілелердің бұзылуы; сатып алу-сату шарттарына қол қоюға болмайды.",
  "2": "Әйелдердің (лирика емес) сатқындығы; көңіл-күйдің нашарлығы; ананың ауруы/қайтыс болуы; болашақтан айыратын мәміле; отбасындағы жанжалдар; жүкті болу, бала туудағы қиындықтар (жүкті болуға болады, бірақ жүктілікті сақтап, көтеріп шығу қиын; жүктілікте, босануда асқынулар, баладағы мәселелер); несеп-жыныс жүйесінің созылмалы аурулары.",
  "3": "Балалардың ауруы, қайтыс болуы; жоспарлар жүзеге аспайды; балаларды бөлісумен ажырасу; шағын бизнестің (50 қызметкерге дейін) күйреуі.",
  "4": "Жұмыстан босату; мансап пен бизнестің күйреуі; әріптестер тарапынан арандату; мәртебеден, қоғамдағы орыннан айырылу; мәмілелер мен келісімшарттардың бұзылуы; серіктестің мансабындағы шиеленіс.",
  "5": "Тәлімгерлердің, бастықтардың сатқындығы; адамға жалған ақпарат берді, жаңылыстырды.",
  "6": "Кез келген серіктестің сатқындығы; жұбайының опасыздығы (байыпты емес); жұбайының ауруы/қайтыс болуы (яғни махаббатты тартып алады); отбасылық бизнестің немесе үйдегі жұмыстың күйреуі; мәмілелер мен келісімшарттардың бұзылуы; жүрек-қантамыр аурулары.",
  "7": "Ауыр салдары бар апаттар. 7-11, 7-13, 7-15, 7-16 үйлесімдері өліммен аяқталуы мүмкін; автонесиелермен қиындықтар; мансап пен бизнестің күйреуі; амалсыз көшулер; мәмілелер мен келісімшарттардың бұзылуы; нұсқалардың болмауы.",
  "8": "Нақты түрме мерзімі; заңдық салдары бар мансап пен бизнестің күйреуі; контрагенттердің сатқындығы; соттағы ұтылыстар; мемлекеттің қысымы.",
  "9": "Созылмалы аурулар; дәрігерге жиі бару; ауруханада ұзақ ауыру мүмкін; айналадағы екі адамнан айырылу; клиенттерден айырылу себебінен мансаптың немесе бизнестің күйреуі; адам басқа адамдарға артқанның бәрі жүзеге аспайды; адамның болмауы себебінен мәмілелердің бұзылуы; полиция немесе салық қызметінің әділетсіз ұстауы; физикалық емес, эмоционалдық жетімдік (ата-ана теріс айналады, араласқысы келмейді); жақын адаммен байланысты жоғалту; жақын туыстардың ауруы.",
  "10": "Ақшаның, мүліктің ірі жоғалуы, қарыздар; күйреу (разорение); қаржылық салдары бар мансап пен бизнестің күйреуі (нөлге дейін, әсіресе жалға алу шарттары қолайсыз); мүлікті бөлісумен ажырасу; шығынмен ажырасу; әл-ауқатқа жауап беретін өмірдің барлық айналым процестерінің тоқтауы.",
  "11": "Достар сатқын, жау болып шығады; еңсеру мүмкін емес кедергілер; дәрігерлік қателер; қажетсіз операциялар; шұғыл хирургиялық араласулар; денеге зақым; мертігу, жарақаттар, шабуылдар; бәсекелестік күрес немесе жаулардың астыртын келісімі себебінен мансаптың, бизнестің күйреуі; мансаптың, бизнестің, қарым-қатынастың, отбасының жанжалды күйреуі.",
  "12": "Адамнан қоғам, жақын ортасы теріс айналып, араласуды тоқтатады (жай ғана, бекерден-бекер); клиенттер мен келісімшарттардан айырылу; жанашырлық танытпайды; жақындардың құрметтемеуі, тұтынушылық көзқарасы; құпиялар бөтен адамдарға қолжетімді болады.",
  "13": "Белгі иесінің қайғылы өлімі; жақын адамдардың өлімі; ауыр аурулар; қалпына келтіру құқығынсыз мансап пен бизнестің күйреуі (бизнестің өлімі); отбасылық өмірдің күйреуі; серіктеспен бітіспес жанжалдар; жаман жаққа күрт өзгерістер; адамның өзегін сындыратын басқа оқиғалар; әрқашан күткеннен нашар болатын бақыланбайтын өзгерістер; тұрақтының бәрін сындырады.",
  "14": "«Барабашка» (үй иесі рухы) белгісі; мәселенің шынайы себебі жасырын, адам ол туралы ештеңе шешу мүмкін болмай қалғанда біледі; астыртын келісімдер, өсек; баяу күйреу; мансап пен бизнестің күйреуі; жасырын жаулар; әріптестер мен жақын ортаның арандатуы; жасырын мәселелер; шығар жолдың болмауы; баяу күйреу; ажырасқанда — сынық науаның басында қаласыз.",
  "15": "Өткір, бітіспес жанжалдар; бизнестің қылмыстық күйреуі; астыртын әрекеттер мен шабуылдар; ажырасқанда төбелес; арандатулар; ақшаның ірі жоғалуы, оның үстіне адам жеке өзі ешкімге қарыз емес (мысалы, жұбайы қашып кетіп, қарыз қалдырды); жыныстық шабуылдар.",
  "16": "Мүліктен айырылу; амалсыз жөндеу; мансап пен бизнестің түбірімен күйреуі; ажырасу; айналадағы адамнан (туыс емес) айырылу; ажырасудың ең күшті белгісі; алып тастауы дәрігерлік қате болып табылатын (дәрімен емдеуге болар еді) мүшеден айырылу, қайталама операцияларға әкеледі; аркан адамның өмірін бұзып, қол жеткізгенінің бәрінен айыруға қабілетті.",
  "17": "Идеялар жүзеге аспайды, ұрланады; адам лайықты нәтиже алмайды; достардың сатқындығы; көңіл қалу; тура және ауыспалы мағынада биіктен құлау; жоғары жылдамдықтағы апаттар; мансап пен бизнестің күйреуі; адамдардың ұятсыз, дөрекі, тұтынушылық көзқарасы.",
  "18": "Опасыздық пен сатқындық; махаббат үшбұрыштары; алаяқтық, алдау, жала, арандату, сатқындық; жақындармен жанжал; ажырасу (кейін қайта қосылады); жұмыстағы өтірік пен алдау.",
  "19": "Беделге нұқсан келтіріп, өз саласында қалпына келтіру құқығынсыз мансап пен бизнестің күйреуі; мәртебеден айырылу; мемлекетпен мәселелер; ықпалды жаулар; бөтен ойындарға (астыртын ойындар) байланысты жоғары лауазымнан түсіру; шарттарды оқу, сондай-ақ серіктестер туралы досье болу аса маңызды, өйткені жиі бизнесті басып алудың құрбаны болады.",
  "20": "Әулет мүшесінің ауруы немесе қайтыс болуы; туыстардың ауыр аурулары; ажырасулар; күйреу; әулеттік мүліктен айырылу; әулеттік бизнестің күйреуі.",
  "21": "Шетелдіктердің сатқындығы; шетелдік компаниялармен мәселелер; депортация; жануарлардың тістеуі; сирек, емделмейтін аурулар.",
  "22": "Өмірдің барлық салаларында бір мезгілде шешілмейтін мәселелер үйіндісі; жүктілікті сақтаудағы мәселелер; түсік жасатуға азғыру; айналадағылардың қыңырлығы мен байыпсыздығы."
 }
};
